
    const cards = [{"id":"opus-1","category":"人工知能とは","term":"AI 効果","summary":"AIで実現された技術が、当たり前になるとAIとは呼ばれにくくなる現象。AIの定義が時代で揺れる理由になる。","exam":"人工知能の定義が一つに定まらない理由や、AIへの期待と評価の変化として問われやすい。","difference":"人工知能そのものではなく、AIと見なされる範囲が変化する現象を指す。","mnemonic":"できたらAI卒業","field":"1","priority":"S"},{"id":"opus-2","category":"人工知能とは","term":"エージェント","summary":"環境を観測し、目的に沿って行動を選ぶ主体。人間、ロボット、ソフトウェアなどが例になる。","exam":"強化学習や探索問題と結びつき、環境・状態・行動・報酬との関係で見られやすい。","difference":"単なるプログラムより、環境を見て行動を決める主体という意味が強い。","mnemonic":"見て動く主体","field":"1","priority":"S"},{"id":"opus-3","category":"人工知能とは","term":"シンギュラリティ","summary":"AIが人間の知能を超え、社会や技術の変化が予測しにくくなるとされる仮説的な転換点。","exam":"AIの将来像や汎用人工知能の議論として、過度な断定を避ける文脈で問われやすい。","difference":"現在確立した事実ではなく、将来に関する予測・仮説として扱う点が重要。","mnemonic":"知能の転換点","field":"1","priority":"S"},{"id":"opus-4","category":"人工知能とは","term":"シンボルグラウンディング問題","summary":"記号や言葉の意味を、機械が現実世界の経験や感覚とどう結びつけるかという問題。","exam":"人工知能が本当に意味を理解しているのか、記号処理の限界として問われやすい。","difference":"フレーム問題は行動時の関連情報選択、こちらは記号の意味づけの問題。","mnemonic":"記号に意味を接地","field":"1","priority":"S"},{"id":"opus-5","category":"人工知能とは","term":"ダートマス会議","summary":"1956年に開かれ、人工知能という研究分野の出発点とされる会議。AI研究の歴史で重要。","exam":"人工知能という言葉の成立や、第1次AIブームの起点として問われやすい。","difference":"チューリングテストより後の出来事で、AI研究分野の始まりとして重要。","mnemonic":"AI研究の出発点","field":"1","priority":"S"},{"id":"opus-6","category":"人工知能とは","term":"チューリングテスト","summary":"人間との対話で相手が機械か人間か判別できなければ、知的とみなせるという考え方のテスト。","exam":"人工知能の知能判定や、会話能力による評価方法として問われやすい。","difference":"ローブナーコンテストは、この考えをもとにした会話プログラムの競技。","mnemonic":"会話で知能判定","field":"1","priority":"S"},{"id":"opus-7","category":"人工知能とは","term":"ディープラーニング","summary":"多層のニューラルネットワークを使い、画像・音声・言語などから特徴を自動的に学習する手法。","exam":"機械学習の一種として、特徴量設計との違いやニューラルネットワークとの関係が問われやすい。","difference":"機械学習の一部で、深いニューラルネットワークを使う点が特徴。","mnemonic":"深く特徴を学ぶ","field":"1","priority":"S"},{"id":"opus-8","category":"人工知能とは","term":"トイ・プロブレム","summary":"迷路やパズルなど、現実より単純化された人工知能研究用の小さな問題。","exam":"初期AIが限定的な問題では成果を出したが、現実問題に弱かった流れで問われやすい。","difference":"現実の複雑な問題ではなく、条件を絞った実験用の問題を指す。","mnemonic":"おもちゃ問題","field":"1","priority":"S"},{"id":"opus-9","category":"人工知能とは","term":"フレーム問題","summary":"AIが行動するとき、膨大な情報の中から何を考慮すべきか判断するのが難しい問題。","exam":"初期AIの限界や、現実世界で柔軟に行動する難しさとして問われやすい。","difference":"知識獲得のボトルネックは知識入力の難しさ、こちらは関連情報選択の難しさ。","mnemonic":"何を考える問題","field":"1","priority":"S"},{"id":"opus-10","category":"人工知能とは","term":"ルールベース機械翻訳","summary":"人手で作った文法規則や辞書を使い、入力文を解析して別言語へ変換する機械翻訳方式。","exam":"統計的機械翻訳やニューラル機械翻訳との比較で、規則中心の方式として問われやすい。","difference":"統計的機械翻訳は大量データから確率を学ぶが、こちらは人手の規則が中心。","mnemonic":"規則で翻訳","field":"1","priority":"S"},{"id":"opus-11","category":"人工知能とは","term":"ローブナーコンテスト","summary":"チューリングテストの考えをもとに、人間らしく対話できるプログラムを競わせたコンテスト。","exam":"チューリングテストの実例や、対話型AIの歴史に関する用語として問われやすい。","difference":"チューリングテストは考え方、ローブナーコンテストはその形式を使った競技。","mnemonic":"会話AI競技","field":"1","priority":"S"},{"id":"opus-12","category":"人工知能とは","term":"中国語の部屋","summary":"記号を規則通り操作できても、意味を理解しているとは限らないと主張する思考実験。","exam":"強いAIへの批判や、記号処理と理解の違いを問う文脈で出やすい。","difference":"シンボルグラウンディング問題と近いが、こちらは理解の有無を問う思考実験。","mnemonic":"処理しても理解別","field":"1","priority":"S"},{"id":"opus-13","category":"人工知能とは","term":"人工知能","summary":"人間の知的な働きを、コンピュータで実現しようとする技術や研究分野の総称。明確な定義は一つではない。","exam":"定義の曖昧さ、機械学習やディープラーニングとの包含関係が問われやすい。","difference":"機械学習やディープラーニングを含む、より広い概念。","mnemonic":"知能を機械で","field":"1","priority":"S"},{"id":"opus-14","category":"人工知能とは","term":"強いAI と弱いAI","summary":"強いAIは心や理解を持つAIを想定し、弱いAIは知的作業を道具として実行するAIを指す。","exam":"現在の多くのAIは弱いAIとして扱われ、強いAIは哲学的議論として問われやすい。","difference":"汎用AIと完全に同じ意味ではなく、心や理解を持つかという論点が中心。","mnemonic":"心ありか道具か","field":"1","priority":"S"},{"id":"opus-15","category":"人工知能とは","term":"機械学習","summary":"データから規則や判断基準を学び、未知のデータに対して予測や分類を行うAIの主要な方法。","exam":"教師あり・教師なし・強化学習の分類や、AIとの関係で問われやすい。","difference":"人工知能の一分野で、明示的なルール作成よりデータから学ぶ点が特徴。","mnemonic":"データから学ぶ","field":"1","priority":"S"},{"id":"opus-16","category":"人工知能とは","term":"知識獲得のボトルネック","summary":"専門家の知識を人手でルール化してシステムに入れる作業が難しく、限界になる問題。","exam":"エキスパートシステムや第2次AIブームの限界として問われやすい。","difference":"フレーム問題は関連情報選択の難しさ、こちらは知識を集め入力する難しさ。","mnemonic":"知識入力が詰まる","field":"1","priority":"S"},{"id":"opus-17","category":"人工知能とは","term":"統計的機械翻訳","summary":"大量の対訳データから単語や文の対応確率を学び、統計的にもっともらしい翻訳を選ぶ方法。","exam":"ルールベース機械翻訳との違いとして、データと確率を使う点が問われやすい。","difference":"ルールベースは人手の文法規則中心、統計的機械翻訳は対訳データ中心。","mnemonic":"対訳から確率翻訳","field":"1","priority":"S"},{"id":"opus-18","category":"人工知能とは","term":"身体性","summary":"知能は脳だけでなく、身体を通じた環境との相互作用から生まれるという考え方。","exam":"ロボットや認知科学と関係し、記号処理だけでは知能を説明しにくい例として見られる。","difference":"シンボルグラウンディング問題に対する手がかりとして語られることがある。","mnemonic":"身体で知る","field":"1","priority":"S"},{"id":"opus-19","category":"人工知能をめぐる動向","term":"Cyc プロジェクト","summary":"人間の常識的知識を大規模に蓄積し、AIに推論させようとした知識ベース構築プロジェクト。","exam":"常識知識の扱いや、知識を人手で入力する難しさの例として問われやすい。","difference":"意味ネットワークより大規模に常識知識を集める知識ベース構築の試み。","mnemonic":"常識をAIへ","field":"1","priority":"S"},{"id":"opus-20","category":"人工知能をめぐる動向","term":"DENDRAL","summary":"化学分野で分子構造を推定する初期のエキスパートシステム。専門知識をルール化して利用した。","exam":"第2次AIブームやエキスパートシステムの代表例として問われやすい。","difference":"MYCINは医療診断、DENDRALは化学の分子構造推定を扱う。","mnemonic":"化学の専門AI","field":"1","priority":"S"},{"id":"opus-21","category":"人工知能をめぐる動向","term":"ILSVRC","summary":"ImageNetを用いた画像認識コンペティション。深層学習の有効性を示す舞台になった。","exam":"2012年のAlexNetの高成績と関連し、第3次AIブームの契機として問われやすい。","difference":"ImageNetはデータセット、ILSVRCはそれを使った画像認識競技会。","mnemonic":"画像認識の大会","field":"1","priority":"S"},{"id":"opus-22","category":"人工知能をめぐる動向","term":"ImageNet","summary":"大量のラベル付き画像を集めたデータセット。画像認識研究の進展に大きく貢献した。","exam":"深層学習ブームの背景として、ILSVRCやAlexNetと結びついて問われやすい。","difference":"ILSVRCは競技会、ImageNetはその基盤となる画像データセット。","mnemonic":"画像の巨大教材","field":"1","priority":"S"},{"id":"opus-23","category":"人工知能をめぐる動向","term":"LeNet","summary":"手書き数字認識などに使われた初期の畳み込みニューラルネットワーク。CNNの代表的原型。","exam":"ディープラーニング以前からCNNの基礎があった例として問われやすい。","difference":"AlexNetより古いCNNで、主に手書き数字認識の文脈で知られる。","mnemonic":"CNNの原型","field":"1","priority":"S"},{"id":"opus-24","category":"人工知能をめぐる動向","term":"Mini-Max 法","summary":"相手も最善手を選ぶと仮定し、自分の利益を最大化し相手の利益を最小化する手を選ぶ探索法。","exam":"チェスや将棋などのゲームAIで、相手の最善手を読む方法として問われやすい。","difference":"αβ法はMini-Max法の探索を効率化する枝刈り手法。","mnemonic":"最悪を読んで選ぶ","field":"1","priority":"S"},{"id":"opus-25","category":"人工知能をめぐる動向","term":"Question- Answering","summary":"質問文を解析し、文書や知識ベースから答えを探して返す自然言語処理のタスク。","exam":"検索との違いや、ワトソン・東ロボくんなどの応用例と結びつきやすい。","difference":"検索は関連文書を返すことが多く、Question-Answeringは答えそのものを返す。","mnemonic":"質問に答えるAI","field":"1","priority":"S"},{"id":"opus-26","category":"人工知能をめぐる動向","term":"SHRDLU","summary":"積み木の仮想世界で、自然言語による命令を理解し実行した初期AIシステム。","exam":"限定世界では自然言語理解が可能だった例として、トイ・プロブレムと結びつきやすい。","difference":"STRIPSは行動計画の手法、SHRDLUは対話的に命令を扱うシステム。","mnemonic":"積み木と会話","field":"1","priority":"S"},{"id":"opus-27","category":"人工知能をめぐる動向","term":"STRIPS","summary":"初期状態・目標状態・行動の前提条件と効果を使って、計画を立てる古典的AIの手法。","exam":"プランニング研究の代表例として、行動の前提条件と結果を扱う点が問われやすい。","difference":"SHRDLUは自然言語対話システム、STRIPSは計画生成の枠組み。","mnemonic":"条件で計画","field":"1","priority":"S"},{"id":"opus-28","category":"人工知能をめぐる動向","term":"is-a の関係・has-a の関係・part-of の関係","summary":"is-aは分類、has-aは属性や所有、part-ofは部分関係を表し、知識表現で概念同士を結ぶ。","exam":"意味ネットワークやオントロジーで、概念間の関係を表す用語として問われやすい。","difference":"is-aは継承関係、has-aは持つ関係、part-ofは構成要素の関係。","mnemonic":"分類・所有・部分","field":"1","priority":"S"},{"id":"opus-29","category":"人工知能をめぐる動向","term":"αβ 法","summary":"Mini-Max法で明らかに選ばれない枝を探索せず、ゲーム木の計算量を減らす枝刈り手法。","exam":"Mini-Max法を効率化する方法として、探索範囲を削減する点が問われやすい。","difference":"Mini-Max法は手の選び方、αβ法は不要な探索を省く工夫。","mnemonic":"不要枝を切る","field":"1","priority":"S"},{"id":"opus-30","category":"人工知能をめぐる動向","term":"アルファ碁 (AlphaGo)","summary":"DeepMindが開発した囲碁AI。深層学習と強化学習、モンテカルロ木探索を組み合わせた。","exam":"囲碁でトップ棋士に勝利した事例として、第3次AIブームの象徴として問われやすい。","difference":"従来のゲーム木探索だけでなく、学習と探索を組み合わせた点が特徴。","mnemonic":"学習する囲碁AI","field":"1","priority":"S"},{"id":"opus-31","category":"人工知能をめぐる動向","term":"イライザ (ELIZA)","summary":"相手の発言を言い換えて返すなど、会話らしく見せた初期の対話プログラム。","exam":"初期の自然言語処理や、理解しているように見える対話AIの例として問われやすい。","difference":"本当に意味理解したのではなく、パターン応答で会話らしさを作った点が重要。","mnemonic":"会話風の元祖","field":"1","priority":"S"},{"id":"opus-32","category":"人工知能をめぐる動向","term":"インタビューシステム","summary":"利用者に質問を投げかけ、その回答をもとに情報収集や診断を進める対話型システム。","exam":"エキスパートシステムなどで、必要な情報を質問により集める仕組みとして見られる。","difference":"イライザは会話らしさが中心、インタビューシステムは目的に沿った情報収集が中心。","mnemonic":"質問で絞る","field":"1","priority":"S"},{"id":"opus-33","category":"人工知能をめぐる動向","term":"ウェブマイニング","summary":"Webページやリンク、アクセスログなどから有用な情報や傾向を発見する技術。","exam":"データマイニングのWeb版として、検索・推薦・アクセス解析と結びつきやすい。","difference":"データマイニング全般のうち、Web上のデータを対象にする点が特徴。","mnemonic":"Webから発掘","field":"1","priority":"S"},{"id":"opus-34","category":"人工知能をめぐる動向","term":"オントロジー","summary":"概念の種類や関係を明確に定義し、知識を共有・再利用しやすくするための体系。","exam":"セマンティックWebや知識表現で、概念関係を定義する仕組みとして問われやすい。","difference":"意味ネットワークより、概念や関係の定義を厳密に整理する意味が強い。","mnemonic":"概念の設計図","field":"1","priority":"S"},{"id":"opus-35","category":"人工知能をめぐる動向","term":"スパムフィルタ","summary":"メールなどが迷惑かどうかを、単語の出現や送信元などの特徴から分類する仕組み。","exam":"機械学習の分類問題や、実用的なAI応用例として問われやすい。","difference":"レコメンデーションは好みを推定し、スパムフィルタは不要なものを分類する。","mnemonic":"迷惑を分類","field":"1","priority":"S"},{"id":"opus-36","category":"人工知能をめぐる動向","term":"セマンティック Web","summary":"Web上の情報に意味づけを与え、機械が内容を理解・処理しやすくする構想。","exam":"オントロジーやメタデータと結びつき、Web情報の意味処理として問われやすい。","difference":"通常のWebが人間向け中心なのに対し、機械処理しやすい意味情報を重視する。","mnemonic":"Webに意味を付与","field":"1","priority":"S"},{"id":"opus-37","category":"人工知能をめぐる動向","term":"データマイニング","summary":"大量データから、人間が気づきにくい規則性・関連性・パターンを発見する技術。","exam":"機械学習や統計分析と関連し、知識発見の手法として問われやすい。","difference":"ウェブマイニングは、データマイニングの対象をWebデータに絞ったもの。","mnemonic":"大量データを発掘","field":"1","priority":"S"},{"id":"opus-38","category":"人工知能をめぐる動向","term":"ネオコグニトロン","summary":"福島邦彦が提案した視覚認識モデル。畳み込みニューラルネットワークの先駆けとされる。","exam":"LeNetやCNNの歴史的背景として、画像認識モデルの流れで問われやすい。","difference":"LeNetは実用的なCNNの代表例、ネオコグニトロンはその先駆的モデル。","mnemonic":"視覚CNNの祖","field":"1","priority":"S"},{"id":"opus-39","category":"人工知能をめぐる動向","term":"ハノイの塔","summary":"円盤をルールに従って別の棒へ移すパズルで、状態空間探索の例題として使われる。","exam":"トイ・プロブレムや探索問題の具体例として、手順や状態遷移と結びつきやすい。","difference":"実世界問題ではなく、条件が明確な探索の練習用問題。","mnemonic":"円盤を移す探索","field":"1","priority":"S"},{"id":"opus-40","category":"人工知能をめぐる動向","term":"ビッグデータ","summary":"量・種類・発生速度が大きいデータ群。機械学習の性能向上を支える材料になる。","exam":"第3次AIブームの背景として、計算資源や深層学習とセットで問われやすい。","difference":"単なる大量データではなく、多様性や速度も含めて扱われることが多い。","mnemonic":"大量多様な燃料","field":"1","priority":"S"},{"id":"opus-41","category":"人工知能をめぐる動向","term":"ブルートフォース","summary":"考えられる候補をしらみつぶしに調べる方法。単純だが候補が多いと計算量が大きくなる。","exam":"探索や暗号解読の文脈で、効率は悪いが確実な全探索として問われやすい。","difference":"ヒューリスティック探索は手がかりで絞るが、ブルートフォースは基本的に全候補を見る。","mnemonic":"力技の全探索","field":"1","priority":"S"},{"id":"opus-42","category":"人工知能をめぐる動向","term":"マイシン (MYCIN)","summary":"感染症の診断や抗生物質の選択を支援した医療分野のエキスパートシステム。","exam":"第2次AIブームやルールベース推論の代表例として問われやすい。","difference":"DENDRALは化学、MYCINは医療診断を対象にしたエキスパートシステム。","mnemonic":"医療の専門AI","field":"1","priority":"S"},{"id":"opus-43","category":"人工知能をめぐる動向","term":"モンテカルロ法","summary":"乱数を使って多数の試行を行い、確率的に近似解や評価値を求める手法。","exam":"ゲームAIやシミュレーションで、ランダム試行により判断する方法として問われやすい。","difference":"ブルートフォースは全探索寄り、モンテカルロ法は乱数で近似的に見積もる。","mnemonic":"乱数で見積もる","field":"1","priority":"S"},{"id":"opus-44","category":"人工知能をめぐる動向","term":"レコメンデーションエンジン","summary":"利用者の行動履歴や似た人の傾向から、商品・動画・記事などを推薦する仕組み。","exam":"協調フィルタリングなどと関連し、AIの身近な応用例として問われやすい。","difference":"検索は利用者が探すが、推薦はシステム側が好みに合う候補を提示する。","mnemonic":"好みを先回り","field":"1","priority":"S"},{"id":"opus-45","category":"人工知能をめぐる動向","term":"ワトソン","summary":"IBMが開発した質問応答システムで、クイズ番組で人間のチャンピオンに勝利した。","exam":"自然言語処理・Question-Answering・知識検索の応用例として問われやすい。","difference":"東ロボくんは入試問題、ワトソンはクイズ形式の質問応答で知られる。","mnemonic":"クイズ王AI","field":"1","priority":"S"},{"id":"opus-46","category":"人工知能をめぐる動向","term":"人間の神経回路","summary":"脳内の神経細胞が信号をやり取りする仕組み。ニューラルネットワークの発想元になった。","exam":"ニューラルネットワークの基本概念として、ニューロンや重みとの対応で問われやすい。","difference":"人工ニューラルネットワークは、生物の神経回路を単純化した計算モデル。","mnemonic":"脳から着想","field":"1","priority":"S"},{"id":"opus-47","category":"人工知能をめぐる動向","term":"幅優先探索","summary":"探索木を根に近い階層から順に調べる方法。最短手数の解を見つけやすいがメモリを使う。","exam":"深さ優先探索との違いとして、浅い階層から広く探索する点が問われやすい。","difference":"深さ優先探索は奥へ進むが、幅優先探索は同じ深さを先に広く調べる。","mnemonic":"浅く広く探す","field":"1","priority":"S"},{"id":"opus-48","category":"人工知能をめぐる動向","term":"意味ネットワーク","summary":"概念をノード、関係をリンクで表し、知識をネットワーク構造として表現する方法。","exam":"知識表現の代表例として、is-aなどの関係と一緒に問われやすい。","difference":"オントロジーは概念や関係をより体系的・明示的に定義する枠組み。","mnemonic":"意味を線で結ぶ","field":"1","priority":"S"},{"id":"opus-49","category":"人工知能をめぐる動向","term":"探索木","summary":"問題の状態や選択肢を木構造で表し、根から枝をたどって解や最善手を探す表現方法。","exam":"幅優先探索・深さ優先探索・ゲーム木の前提として問われやすい。","difference":"探索アルゴリズムそのものではなく、探索対象を表す構造。","mnemonic":"選択肢の木","field":"1","priority":"S"},{"id":"opus-50","category":"人工知能をめぐる動向","term":"東ロボくん","summary":"東京大学合格を目標に、入試問題を解くAIを研究した日本のプロジェクト。","exam":"自然言語理解や知識処理の難しさを示す事例として問われやすい。","difference":"ワトソンはクイズ番組での質問応答、東ロボくんは大学入試問題への挑戦。","mnemonic":"入試に挑むAI","field":"1","priority":"S"},{"id":"opus-51","category":"人工知能をめぐる動向","term":"次元の呪い","summary":"データの特徴量が増えるほど空間が広がり、必要なデータ量や計算量が急増する問題。","exam":"機械学習で高次元データを扱う難しさや、特徴量選択の必要性として問われやすい。","difference":"過学習は訓練データに寄りすぎる問題、次元の呪いは高次元でデータが疎になる問題。","mnemonic":"次元が増える罠","field":"1","priority":"S"},{"id":"opus-52","category":"人工知能をめぐる動向","term":"深さ優先探索","summary":"探索木の枝をできるだけ深く進み、行き止まりなら戻って別の枝を調べる方法。","exam":"幅優先探索との違いとして、メモリは少なめだが最短解とは限らない点が出やすい。","difference":"幅優先探索は浅い順、深さ優先探索は一つの枝を奥まで進む。","mnemonic":"深く潜る探索","field":"1","priority":"S"},{"id":"opus-53","category":"人工知能をめぐる動向","term":"生成 AI","summary":"学習したデータの特徴をもとに、文章・画像・音声・動画など新しいコンテンツを生成するAI。","exam":"大規模言語モデルや拡散モデルと関連し、近年のAI応用として問われやすい。","difference":"識別AIは分類や判定が中心、生成AIは新しいデータを作る点が中心。","mnemonic":"作り出すAI","field":"1","priority":"S"},{"id":"opus-54","category":"人工知能をめぐる動向","term":"統計的自然言語処理","summary":"大量の言語データから単語や文の出現傾向を学び、確率的に言語を処理する方法。","exam":"ルールベースから統計的手法への変化として、機械翻訳などと結びつきやすい。","difference":"ルールベースは人手の規則中心、統計的自然言語処理はデータの傾向中心。","mnemonic":"言葉を確率で","field":"1","priority":"S"},{"id":"opus-55","category":"AIの社会実装に向けて","term":"AI のビジネス活用","summary":"業務課題にAIを適用し、予測・自動化・最適化などで価値創出を狙う取り組み。","exam":"技術導入だけでなく、業務課題や費用対効果と結びつけて問われやすい。","difference":"研究開発は技術検証中心、ビジネス活用は業務価値や運用成果を重視する。","mnemonic":"業務にAIを効かす","field":"6","priority":"S"},{"id":"opus-56","category":"AIの社会実装に向けて","term":"AI プロジェクトの進め方","summary":"課題設定、データ確認、PoC、開発、運用改善を段階的に進めるAI導入の流れ。","exam":"AIは作って終わりでなく、目的設定・検証・運用が重要として問われやすい。","difference":"通常のIT開発より、データ品質やモデル精度の検証が大きな不確実性になる。","mnemonic":"課題から運用まで","field":"6","priority":"S"},{"id":"opus-57","category":"AIの社会実装に向けて","term":"AIプロジェクトの体制","summary":"データ・ドメイン・エンジニアリングの各専門家が協働して進める必要がある。","exam":"一人では完結しない点や、ステークホルダー調整の重要性として問われる。","difference":"データサイエンティスト単独の話ではなく、役割分担の話。","mnemonic":"役割分担で進める","field":"6","priority":"S"},{"id":"opus-58","category":"AIの社会実装に向けて","term":"AI利活用のリスクアセスメント","summary":"導入前に想定される損害や影響を洗い出し、対策を決める作業。","exam":"リスクベースアプローチやガバナンスと結びつけて問われる。","difference":"事後の監査ではなく、事前の評価である点が重要。","mnemonic":"事前に危険を洗う","field":"6","priority":"S"},{"id":"opus-59","category":"AIの社会実装に向けて","term":"BPR","summary":"既存業務を前提にせず、業務プロセス全体を見直して抜本的な改善を行う考え方。","exam":"AI導入時に、単なる自動化でなく業務改革と結びつけて問われやすい。","difference":"業務改善は部分修正も含むが、BPRは業務プロセスの根本的な再設計を重視する。","mnemonic":"業務を作り直す","field":"6","priority":"S"},{"id":"opus-60","category":"AIの社会実装に向けて","term":"CRISP-DM","summary":"ビジネス理解からデータ理解、前処理、モデリング、評価、展開へ進むデータ分析の標準プロセス。","exam":"データ分析プロジェクトの進行手順として、各段階の役割が問われやすい。","difference":"CRISP-MLは機械学習運用を意識し、CRISP-DMはデータマイニング全般の手順。","mnemonic":"分析の標準手順","field":"6","priority":"S"},{"id":"opus-61","category":"AIの社会実装に向けて","term":"CRISP-ML","summary":"機械学習プロジェクト向けに、ビジネス理解から運用・監視までを含めて整理したプロセス。","exam":"MLOpsやモデル運用を意識した機械学習プロジェクト管理として問われやすい。","difference":"CRISP-DMより、モデルのデプロイ後の監視や継続改善を重視する。","mnemonic":"MLの運用手順","field":"6","priority":"S"},{"id":"opus-62","category":"AIの社会実装に向けて","term":"Docker","summary":"アプリや実行環境をコンテナとしてまとめ、どこでも同じ環境で動かしやすくする技術。","exam":"AI開発環境の再現性やデプロイで使う道具として問われやすい。","difference":"Jupyter Notebookは分析作業の場、Dockerは実行環境を固めて共有する道具。","mnemonic":"環境を箱に入れる","field":"6","priority":"S"},{"id":"opus-63","category":"AIの社会実装に向けて","term":"Jupyter Notebook","summary":"コード、実行結果、メモを一つの画面で扱える対話型の開発環境。分析や実験に使われる。","exam":"Pythonによるデータ分析や機械学習の試行錯誤環境として問われやすい。","difference":"Dockerは環境を配布する技術、Jupyter Notebookは分析作業を行う画面。","mnemonic":"コードとメモ帳","field":"6","priority":"S"},{"id":"opus-64","category":"AIの社会実装に向けて","term":"KPI設定","summary":"事業上の目的をどの指標で測るかを事前に決めること。","exam":"精度だけでなくビジネス指標で評価する必要性として問われやすい。","difference":"精度指標は技術評価、KPIは事業成果の評価。","mnemonic":"何で測るか決める","field":"6","priority":"S"},{"id":"opus-65","category":"AIの社会実装に向けて","term":"MLOps","summary":"機械学習モデルを継続的に開発・配備・監視・改善するための運用管理の考え方。","exam":"モデルの劣化監視や再学習、CI/CDと関連し、AI運用の重要語として問われやすい。","difference":"DevOpsはソフトウェア運用中心、MLOpsはモデルやデータ変化の管理も含む。","mnemonic":"モデル運用の仕組み","field":"6","priority":"S"},{"id":"opus-66","category":"AIの社会実装に向けて","term":"PoC","summary":"本格導入前に、小さく試して技術的実現性や効果を検証する概念実証。","exam":"AIプロジェクトで、いきなり本番化せず小規模検証する段階として問われやすい。","difference":"プロトタイプは試作品、PoCは実現可能性や効果の検証が主目的。","mnemonic":"小さく試す検証","field":"6","priority":"S"},{"id":"opus-67","category":"AIの社会実装に向けて","term":"PoC死","summary":"実証実験を繰り返すだけで本番運用に至らない状態。","exam":"PoCの落とし穴として、目的や評価指標の事前設定の重要性で問われる。","difference":"PoC自体は有効な手法で、目的が曖昧なまま繰り返すことが問題。","mnemonic":"実験止まり","field":"6","priority":"S"},{"id":"opus-68","category":"AIの社会実装に向けて","term":"Python","summary":"読みやすくライブラリが豊富なプログラミング言語。AIやデータ分析で広く使われる。","exam":"機械学習開発で使われる代表言語として、ライブラリ活用と関連して問われやすい。","difference":"Jupyter NotebookはPythonなどを実行する環境で、Pythonはプログラミング言語。","mnemonic":"AI定番言語","field":"6","priority":"S"},{"id":"opus-69","category":"AIの社会実装に向けて","term":"Web API","summary":"ネットワーク越しにアプリ同士が機能やデータをやり取りするためのインターフェース。","exam":"AIモデルを外部サービスとして利用・提供する仕組みとして問われやすい。","difference":"UIは人が操作する画面、Web APIはシステム同士が機能を呼び出す窓口。","mnemonic":"機能を呼ぶ窓口","field":"6","priority":"S"},{"id":"opus-70","category":"AIの社会実装に向けて","term":"アジャイル","summary":"短い期間で開発と改善を繰り返し、変化する要件に柔軟に対応する開発方法。","exam":"AIプロジェクトの不確実性に対応する進め方として、ウォーターフォールとの違いが問われやすい。","difference":"ウォーターフォールは順番に進め、アジャイルは小さく作って改善を繰り返す。","mnemonic":"小さく早く回す","field":"6","priority":"S"},{"id":"opus-71","category":"AIの社会実装に向けて","term":"アノテーション","summary":"画像や文章などのデータに、正解ラベルや意味情報を人手または半自動で付ける作業。","exam":"教師あり学習のデータ準備として、ラベル品質がモデル性能に影響する点で問われやすい。","difference":"データ収集は素材を集める作業、アノテーションは集めたデータに正解を付ける作業。","mnemonic":"データに正解付け","field":"6","priority":"S"},{"id":"opus-72","category":"AIの社会実装に向けて","term":"ウォーターフォール","summary":"要件定義から設計、開発、テストへ順番に進める、計画重視の開発方法。","exam":"従来型開発手法として、アジャイルとの進め方の違いが問われやすい。","difference":"アジャイルは反復改善型、ウォーターフォールは工程を上流から下流へ進める。","mnemonic":"上から順に流す","field":"6","priority":"S"},{"id":"opus-73","category":"AIの社会実装に向けて","term":"オープンデータセット","summary":"研究や開発に利用できるよう公開されたデータセット。学習や評価の共通基盤になる。","exam":"AI開発でのベンチマークや再現性、利用条件の確認と関連して問われやすい。","difference":"自社データは内部利用中心、オープンデータセットは外部に公開されたデータ。","mnemonic":"公開された教材","field":"6","priority":"S"},{"id":"opus-74","category":"AIの社会実装に向けて","term":"オープン・イノベーション","summary":"自社だけでなく外部の技術や知見を取り入れ、新しい価値や事業を生み出す考え方。","exam":"AI活用で外部連携や共同研究が重要になる文脈で問われやすい。","difference":"自前主義は社内資源中心、オープン・イノベーションは外部資源も活用する。","mnemonic":"外の知恵も使う","field":"6","priority":"S"},{"id":"opus-75","category":"AIの社会実装に向けて","term":"クラウド","summary":"インターネット経由でサーバやストレージ、AI機能などを必要に応じて利用する仕組み。","exam":"AI開発で計算資源やサービスを柔軟に使う基盤として問われやすい。","difference":"オンプレミスは自社設備中心、クラウドは外部サービスをネット経由で使う。","mnemonic":"ネット越しの基盤","field":"6","priority":"S"},{"id":"opus-76","category":"AIの社会実装に向けて","term":"コンセプトドリフト","summary":"運用中にデータの傾向が変化し、モデルの性能が劣化する現象。","exam":"MLOpsや継続的な再学習の必要性として問われやすい。","difference":"データリーケージは学習時の不正な情報混入で、時期も原因も異なる。","mnemonic":"現場が変わる","field":"6","priority":"S"},{"id":"opus-77","category":"AIの社会実装に向けて","term":"コーパス","summary":"自然言語処理で使う大量の文章や発話を集めたデータ集合。言語モデル学習に使われる。","exam":"NLPの学習データとして、辞書や単語リストとの違いが問われやすい。","difference":"辞書は語の意味を整理し、コーパスは実際の文章や発話を大量に集めたもの。","mnemonic":"言葉の大きな森","field":"6","priority":"S"},{"id":"opus-78","category":"AIの社会実装に向けて","term":"ステークホルダーのニーズ","summary":"利用者、経営者、現場担当者など関係者がAI導入に期待する目的や要求。","exam":"AIプロジェクト初期の課題設定で、関係者調整の重要性として問われやすい。","difference":"技術要件はシステム側の条件、ステークホルダーのニーズは関係者の期待や課題。","mnemonic":"関係者の期待","field":"6","priority":"S"},{"id":"opus-79","category":"AIの社会実装に向けて","term":"スモールスタート","summary":"小さく始めて効果を確認しながら段階的に広げる進め方。","exam":"PoCやアジャイルと結びつけて、初期の進め方として問われやすい。","difference":"ウォーターフォールは全体を固めて一括で進める点が対照的。","mnemonic":"小さく始める","field":"6","priority":"S"},{"id":"opus-80","category":"AIの社会実装に向けて","term":"データサイエンティスト","summary":"データ分析、統計、機械学習、業務理解を使い、課題解決や意思決定を支援する人材。","exam":"AIプロジェクトの主要人材として、技術だけでなくビジネス理解も問われやすい。","difference":"エンジニアは実装・運用寄り、データサイエンティストは分析と課題解決寄り。","mnemonic":"データで課題解決","field":"6","priority":"S"},{"id":"opus-81","category":"AIの社会実装に向けて","term":"データリーケージ","summary":"本来使えない未来情報や正解に近い情報が学習データに混ざり、評価が不当に高くなる問題。","exam":"モデル評価の落とし穴として、訓練データとテストデータの分離で問われやすい。","difference":"過学習は訓練データへの適合しすぎ、データリーケージは評価前に答えが漏れる問題。","mnemonic":"答えが漏れる罠","field":"6","priority":"S"},{"id":"opus-82","category":"AIの社会実装に向けて","term":"ヒューマンインザループ","summary":"人間が判断や確認の工程に入り、AIの出力を検証・修正する仕組み。","exam":"高リスク領域での運用設計や、責任の所在として問われやすい。","difference":"完全自動化とは対照的に、人の関与を意図的に残す設計。","mnemonic":"人を輪の中に","field":"6","priority":"S"},{"id":"opus-83","category":"AIの社会実装に向けて","term":"モデルの再学習","summary":"運用後の性能劣化に対応して、新しいデータで学習し直すこと。","exam":"MLOpsやコンセプトドリフトへの対策として問われやすい。","difference":"ファインチューニングは適応が目的、再学習は劣化への対応が中心。","mnemonic":"定期的に学び直す","field":"6","priority":"S"},{"id":"opus-84","category":"AIの社会実装に向けて","term":"他企業や他業種との連携","summary":"自社外の企業や異なる業界と協力し、データ・技術・知見を組み合わせる取り組み。","exam":"AI社会実装で、自社だけでは足りないデータやノウハウを補う方法として問われやすい。","difference":"産学連携は大学・研究機関との協力、これは企業や業界間の協力を指す。","mnemonic":"業界を越えて組む","field":"6","priority":"S"},{"id":"opus-85","category":"AIの社会実装に向けて","term":"産学連携","summary":"企業と大学・研究機関が協力し、研究成果や専門知識を社会実装へつなげる取り組み。","exam":"AI人材や研究成果の活用として、オープン・イノベーションと関連して問われやすい。","difference":"他企業連携は企業同士、産学連携は企業と大学・研究機関の協力。","mnemonic":"企業と大学が組む","field":"6","priority":"S"},{"id":"opus-86","category":"AIに必要な数理・統計知識","term":"KLダイバージェンス","summary":"2つの確率分布の隔たりを測る量。0以上で、同じ分布なら0になる。","exam":"VAEの損失や分布の近さの指標として問われやすい。","difference":"距離と呼ばれるが対称ではなく、厳密な距離の定義は満たさない。","mnemonic":"分布のズレ具合","field":"7","priority":"S"},{"id":"opus-87","category":"AIに必要な数理・統計知識","term":"エントロピー","summary":"確率分布の不確かさ・乱雑さを表す量。情報量の期待値。均等な分布ほど大きい。","exam":"決定木の分岐基準や情報利得と結びついて問われやすい。","difference":"ジニ不純度も同じ目的で使うが計算式が異なる指標。","mnemonic":"不確かさの大きさ","field":"7","priority":"S"},{"id":"opus-88","category":"AIに必要な数理・統計知識","term":"コサイン類似度","summary":"2つのベクトルのなす角の近さで類似度を測る指標。文書や単語ベクトル比較に使う。","exam":"自然言語処理や推薦で、ベクトル同士の類似度として問われやすい。","difference":"ユークリッド距離は長さの差も見るが、コサイン類似度は主に方向の近さを見る。","mnemonic":"向きの近さ","field":"7","priority":"S"},{"id":"opus-89","category":"AIに必要な数理・統計知識","term":"ベイズの定理","summary":"結果から原因の確率を逆算する式。P(A|B)=P(B|A)P(A)/P(B)。事前確率を観測で事後確率に更新する。","exam":"迷惑メール判定や病気の検査など、条件付き確率の数値計算問題として頻出。","difference":"条件付き確率が定義そのもの、ベイズの定理はそれを逆向きに使う道具。","mnemonic":"原因を逆算する式","field":"7","priority":"S"},{"id":"opus-90","category":"AIに必要な数理・統計知識","term":"ベクトルのノルム","summary":"ベクトルの長さを表す量。L1は絶対値の和、L2は二乗和の平方根。","exam":"L1正則化・L2正則化の違いの前提として問われやすい。","difference":"L1はスパースになりやすく、L2は全体を小さく抑える。","mnemonic":"長さの測り方","field":"7","priority":"S"},{"id":"opus-91","category":"AIに必要な数理・統計知識","term":"ベルヌーイ分布","summary":"成功か失敗かのように、結果が2通りしかない1回の試行を表す確率分布。","exam":"二項分布の基本として、0か1の確率変数を扱う分布で問われやすい。","difference":"二項分布は複数回の成功回数、ベルヌーイ分布は1回の0・1結果。","mnemonic":"一回の成功失敗","field":"7","priority":"S"},{"id":"opus-92","category":"AIに必要な数理・統計知識","term":"ポアソン分布","summary":"一定時間や一定範囲で、まれな事象が何回起きるかを表す離散確率分布。","exam":"到着回数や故障回数など、回数データのモデルとして問われやすい。","difference":"二項分布は試行回数が決まる成功回数、ポアソン分布は一定範囲の発生回数。","mnemonic":"まれな回数分布","field":"7","priority":"S"},{"id":"opus-93","category":"AIに必要な数理・統計知識","term":"マハラノビス距離","summary":"データの分散や変数間の相関を考慮して、平均からどれだけ離れているかを測る距離。","exam":"異常検知や外れ値判定で、ユークリッド距離との違いが問われやすい。","difference":"ユークリッド距離は直線距離、マハラノビス距離は分散や相関を考慮する。","mnemonic":"分布込みの距離","field":"7","priority":"S"},{"id":"opus-94","category":"AIに必要な数理・統計知識","term":"ユークリッド距離","summary":"2点間を直線で結んだ最短距離。特徴量空間でデータ同士の近さを測る基本的な距離。","exam":"クラスタリングやk近傍法で使う距離として、コサイン類似度との違いが問われやすい。","difference":"コサイン類似度は向きの近さ、ユークリッド距離は座標上の直線距離を見る。","mnemonic":"まっすぐ距離","field":"7","priority":"S"},{"id":"opus-95","category":"AIに必要な数理・統計知識","term":"中央値","summary":"データを小さい順に並べたとき中央にくる値。外れ値の影響を平均より受けにくい代表値。","exam":"平均・最頻値と並ぶ代表値として、外れ値への強さの違いが問われやすい。","difference":"平均は全データを足して割る値、中央値は順番の真ん中の値。","mnemonic":"並べて真ん中","field":"7","priority":"S"},{"id":"opus-96","category":"AIに必要な数理・統計知識","term":"中心極限定理","summary":"標本平均の分布が、元の分布によらず正規分布に近づくという定理。","exam":"正規分布がなぜ広く使われるかの根拠として問われやすい。","difference":"大数の法則は値の収束、中心極限定理は分布の形の話。","mnemonic":"平均は正規に近づく","field":"7","priority":"S"},{"id":"opus-97","category":"AIに必要な数理・統計知識","term":"事前確率・事後確率","summary":"観測前に想定していた確率が事前確率、観測後に更新された確率が事後確率。","exam":"ベイズの定理とセットで、更新の前後どちらかを問う形で出やすい。","difference":"尤度は「その原因ならこの結果が出る確率」で、方向が逆。","mnemonic":"観測前と観測後","field":"7","priority":"S"},{"id":"opus-98","category":"AIに必要な数理・統計知識","term":"二項分布","summary":"成功か失敗かの試行を複数回行ったとき、成功回数が従う確率分布。","exam":"ベルヌーイ分布を複数回繰り返した分布として、成功回数の文脈で問われやすい。","difference":"ベルヌーイ分布は1回の成功失敗、二項分布は複数回の成功回数を扱う。","mnemonic":"成功回数の分布","field":"7","priority":"S"},{"id":"opus-99","category":"AIに必要な数理・統計知識","term":"交差エントロピー","summary":"予測分布と正解分布のズレを測る量。分類問題の損失関数として使われる。","exam":"分類は交差エントロピー、回帰は二乗誤差という対応で頻出。","difference":"二乗誤差は回帰用、交差エントロピーは分類用の損失。","mnemonic":"分類の損失関数","field":"7","priority":"S"},{"id":"opus-100","category":"AIに必要な数理・統計知識","term":"偏相関係数","summary":"他の変数の影響を取り除いたうえで、2つの変数の関係の強さを表す指標。","exam":"疑似相関や交絡の影響を考える場面で、相関係数との違いが問われやすい。","difference":"相関係数は単純な関係、偏相関係数は第三の変数の影響を調整する。","mnemonic":"余計な影響を除く","field":"7","priority":"S"},{"id":"opus-101","category":"AIに必要な数理・統計知識","term":"共分散","summary":"2つの変数が平均からどの向きに一緒に動くかを表す量。正なら同方向に動きやすい。","exam":"相関係数の前段階として、変数間の関係の向きを見る指標で問われやすい。","difference":"相関係数は共分散を標準化し、値の範囲を-1から1にそろえたもの。","mnemonic":"一緒に動く向き","field":"7","priority":"S"},{"id":"opus-102","category":"AIに必要な数理・統計知識","term":"分散","summary":"各データが平均からどれだけ離れているかを二乗して平均した、ばらつきの指標。","exam":"標準偏差の元になる量として、ばらつきの大きさを見る基本指標で問われやすい。","difference":"標準偏差は分散の平方根で、元の単位に戻して解釈しやすくしたもの。","mnemonic":"ズレ二乗の平均","field":"7","priority":"S"},{"id":"opus-103","category":"AIに必要な数理・統計知識","term":"外れ値","summary":"他のデータから大きく離れた値。測定ミスや異常、まれな重要事象を示す場合がある。","exam":"平均や分散、機械学習モデルへの影響として、前処理の注意点で問われやすい。","difference":"ノイズは不要な揺らぎ全般、外れ値は特に他から離れた観測値。","mnemonic":"ぽつんと離れ値","field":"7","priority":"S"},{"id":"opus-104","category":"AIに必要な数理・統計知識","term":"大数の法則","summary":"試行回数を増やすほど、標本平均が真の平均に近づくという法則。","exam":"モンテカルロ法やサンプル数の意味と結びつけて問われやすい。","difference":"中心極限定理は標本平均の分布が正規分布に近づくという別の主張。","mnemonic":"数を増やせば近づく","field":"7","priority":"S"},{"id":"opus-105","category":"AIに必要な数理・統計知識","term":"対立仮説","summary":"検定で示したい主張となる仮説。差がある、効果があるなど帰無仮説と対になる。","exam":"統計的仮説検定で、帰無仮説を棄却したときに支持される仮説として問われやすい。","difference":"帰無仮説は基準として置く仮説、対立仮説は検出したい差や効果を表す。","mnemonic":"示したい仮説","field":"7","priority":"S"},{"id":"opus-106","category":"AIに必要な数理・統計知識","term":"尤度","summary":"あるパラメータのもとで、手元のデータが得られる確率のこと。","exam":"最尤法とセットで、何を最大化しているのかを問われやすい。","difference":"確率はデータ側を動かす、尤度はパラメータ側を動かして測る。","mnemonic":"データのもっともらしさ","field":"7","priority":"S"},{"id":"opus-107","category":"AIに必要な数理・統計知識","term":"帰無仮説","summary":"検定でまず否定できるかを調べる基準となる仮説。差がない、効果がないなどと置く。","exam":"統計的仮説検定で、対立仮説やp値とセットで問われやすい。","difference":"対立仮説は示したい主張、帰無仮説はそれと対になる基準仮説。","mnemonic":"まず疑う仮説","field":"7","priority":"S"},{"id":"opus-108","category":"AIに必要な数理・統計知識","term":"平均","summary":"データの合計をデータ数で割った代表値。全体の中心を表すが外れ値に影響されやすい。","exam":"中央値・最頻値との違いとして、外れ値の影響を受けやすい点が問われやすい。","difference":"中央値は順番の中央、平均はすべての値を使って計算する。","mnemonic":"全部足して割る","field":"7","priority":"S"},{"id":"opus-109","category":"AIに必要な数理・統計知識","term":"度数分布","summary":"データを階級やカテゴリごとに分け、それぞれに何個あるかをまとめた分布。","exam":"ヒストグラムやデータの分布把握で、基本的な集計方法として問われやすい。","difference":"確率分布は確率を表し、度数分布は実際のデータ数を表す。","mnemonic":"数えて分布を見る","field":"7","priority":"S"},{"id":"opus-110","category":"AIに必要な数理・統計知識","term":"微分・偏微分","summary":"関数の変化の傾きを求める操作。多変数で1変数だけ動かすのが偏微分。","exam":"勾配降下法や誤差逆伝播の基礎として、勾配の意味を問われやすい。","difference":"勾配は偏微分を並べたベクトルで、最も急な増加方向を指す。","mnemonic":"傾きを求める","field":"7","priority":"S"},{"id":"opus-111","category":"AIに必要な数理・統計知識","term":"情報量（自己情報量）","summary":"起こりにくい事象ほど大きくなる情報の量。-log(確率)で表す。","exam":"エントロピーの前提知識として、確率が低いほど情報量が大きい点が問われる。","difference":"エントロピーは情報量の期待値で、個別ではなく全体の平均。","mnemonic":"レアほど情報大","field":"7","priority":"S"},{"id":"opus-112","category":"AIに必要な数理・統計知識","term":"最小二乗法","summary":"予測値と実測値の誤差の二乗和が最小になるように、回帰直線などを求める方法。","exam":"線形回帰のパラメータ推定方法として、誤差の二乗和最小化が問われやすい。","difference":"最尤法は確率モデルの尤度を最大化し、最小二乗法は二乗誤差を最小化する。","mnemonic":"誤差二乗を最小","field":"7","priority":"S"},{"id":"opus-113","category":"AIに必要な数理・統計知識","term":"最尤法","summary":"観測データが最も起こりやすくなるように、確率モデルのパラメータを決める推定方法。","exam":"ロジスティック回帰などで、尤度最大化による推定として問われやすい。","difference":"最小二乗法は誤差最小化、最尤法はデータの起こりやすさ最大化を考える。","mnemonic":"もっともらしく推定","field":"7","priority":"S"},{"id":"opus-114","category":"AIに必要な数理・統計知識","term":"最頻値","summary":"データの中で最も多く現れる値。カテゴリデータや分布の代表値として使われる。","exam":"平均値・中央値と並ぶ代表値として、外れ値への強さの違いが問われやすい。","difference":"平均値は合計を割る値、最頻値は最も出現回数が多い値。","mnemonic":"一番よく出る値","field":"7","priority":"S"},{"id":"opus-115","category":"AIに必要な数理・統計知識","term":"有意水準・p値","summary":"帰無仮説を棄却する基準が有意水準、観測された偏りの起こりにくさがp値。","exam":"仮説検定の手順として、帰無仮説・対立仮説とセットで問われやすい。","difference":"帰無仮説は否定したい仮説、p値はその仮説のもとでの珍しさ。","mnemonic":"小さければ棄却","field":"7","priority":"S"},{"id":"opus-116","category":"AIに必要な数理・統計知識","term":"期待値","summary":"確率変数が平均的にどのくらいの値になるかを、各値と確率の重み付き平均で表す量。","exam":"確率分布の代表値として、分散や平均との関係で問われやすい。","difference":"標本平均は得られたデータの平均、期待値は確率分布上の理論的平均。","mnemonic":"確率込み平均","field":"7","priority":"S"},{"id":"opus-117","category":"AIに必要な数理・統計知識","term":"条件付き確率","summary":"ある事象が起きたという条件のもとで、別の事象が起きる確率を表す考え方。","exam":"ベイズの定理や機械学習の確率モデルの基礎として問われやすい。","difference":"同時確率は両方起きる確率、条件付き確率は片方が起きた条件で考える。","mnemonic":"条件つきの確率","field":"7","priority":"S"},{"id":"opus-118","category":"AIに必要な数理・統計知識","term":"標準偏差","summary":"分散の平方根で、データが平均の周りにどれくらい散らばるかを元の単位で表す指標。","exam":"分散との関係や、正規分布のばらつき指標として問われやすい。","difference":"分散は二乗単位、標準偏差は平方根を取るため元の単位で解釈しやすい。","mnemonic":"ばらつき元単位","field":"7","priority":"S"},{"id":"opus-119","category":"AIに必要な数理・統計知識","term":"標準化（z-score）","summary":"平均0・分散1になるように変換する前処理。(x-平均)/標準偏差。","exam":"正規化との使い分けとして問われやすい。","difference":"正規化は0〜1に押し込める、標準化は平均0分散1にそろえる。","mnemonic":"平均0分散1","field":"7","priority":"S"},{"id":"opus-120","category":"AIに必要な数理・統計知識","term":"正規分布","summary":"平均を中心に左右対称の釣鐘型をした代表的な確率分布。多くの統計手法の前提になる。","exam":"統計の基本分布として、平均・分散・標準偏差と関連して問われやすい。","difference":"一様分布は値が同じ出やすさ、正規分布は平均付近が出やすい。","mnemonic":"釣鐘型の分布","field":"7","priority":"S"},{"id":"opus-121","category":"AIに必要な数理・統計知識","term":"正規化（Min-Max）","summary":"最小値0・最大値1の範囲に収める前処理。(x-最小)/(最大-最小)。","exam":"外れ値に弱い点や、標準化との違いが問われやすい。","difference":"標準化は外れ値に比較的強く、正規化は範囲が保証される。","mnemonic":"0から1に収める","field":"7","priority":"S"},{"id":"opus-122","category":"AIに必要な数理・統計知識","term":"疑似相関","summary":"直接の因果関係がないのに、第三の要因などにより相関があるように見える現象。","exam":"相関と因果を混同しない注意点として、データ分析の落とし穴で問われやすい。","difference":"相関は一緒に動く関係、疑似相関は別要因でそう見えるだけの場合がある。","mnemonic":"見せかけの関係","field":"7","priority":"S"},{"id":"opus-123","category":"AIに必要な数理・統計知識","term":"相互情報量","summary":"一方の変数を知ることで、もう一方の不確実性がどれだけ減るかを表す情報量。","exam":"特徴選択や変数間の依存関係を見る指標として問われやすい。","difference":"相関係数は主に線形関係、相互情報量は非線形な依存も捉えられる。","mnemonic":"知るほど減る不確実","field":"7","priority":"S"},{"id":"opus-124","category":"AIに必要な数理・統計知識","term":"相関係数","summary":"2つの変数の直線的な関係の強さと向きを、-1から1の範囲で表す指標。","exam":"相関と因果の違いや、共分散との関係で問われやすい。","difference":"共分散は単位に依存し、相関係数は標準化されて比較しやすい。","mnemonic":"関係の強さを数値","field":"7","priority":"S"},{"id":"opus-125","category":"AIに必要な数理・統計知識","term":"確率分布","summary":"確率変数がどの値をどのくらいの確率で取るかを表したもの。正規分布などが例。","exam":"機械学習や統計推定の基礎として、確率変数や期待値との関係で問われやすい。","difference":"確率変数は値を取る変数、確率分布はその値の出やすさ全体を表す。","mnemonic":"値の出やすさ表","field":"7","priority":"S"},{"id":"opus-126","category":"AIに必要な数理・統計知識","term":"確率変数","summary":"試行の結果によって値が決まる変数。サイコロの目や明日の売上などを数値として扱う。","exam":"確率分布や期待値の前提として、ランダムな結果を数値化する概念で問われやすい。","difference":"通常の変数は固定値を表し、確率変数は偶然により値が変わる。","mnemonic":"偶然で変わる値","field":"7","priority":"S"},{"id":"opus-127","category":"AIに必要な数理・統計知識","term":"確率密度","summary":"連続値の確率変数で、ある値の周辺にどれくらいデータが集まりやすいかを表す量。","exam":"正規分布など連続分布で、面積が確率を表す点が問われやすい。","difference":"離散確率は点ごとの確率、確率密度は区間の面積で確率を考える。","mnemonic":"面積で確率を見る","field":"7","priority":"S"},{"id":"opus-128","category":"AIに必要な数理・統計知識","term":"移動平均","summary":"時系列データで一定期間の平均を順に計算し、短期的な変動をならして傾向を見る方法。","exam":"時系列分析でノイズを抑え、トレンドを把握する基本手法として問われやすい。","difference":"単純平均は全体を一度に平均し、移動平均は期間をずらしながら平均する。","mnemonic":"ならして傾向を見る","field":"7","priority":"S"},{"id":"opus-129","category":"AIに必要な数理・統計知識","term":"第一種の誤り・第二種の誤り","summary":"第一種は正しい帰無仮説を誤って棄却、第二種は誤った帰無仮説を見逃すこと。","exam":"偽陽性・偽陰性と対応づけて問われやすい。","difference":"第一種は偽陽性、第二種は偽陰性に対応する。","mnemonic":"慌て者とぼんやり","field":"7","priority":"S"},{"id":"opus-130","category":"AIに必要な数理・統計知識","term":"行列積・内積","summary":"行列積はm×nとn×pでm×p。内積はベクトル同士を掛けて足した値。","exam":"形が合うかどうかの判定や、全結合層の計算として問われやすい。","difference":"内積はスカラーが返り、行列積は行列が返る。","mnemonic":"形を合わせて掛ける","field":"7","priority":"S"},{"id":"opus-131","category":"AIに必要な数理・統計知識","term":"転置","summary":"行列の行と列を入れ替える操作。記号はTで表す。","exam":"行列積の形合わせや、誤差逆伝播の式変形で登場する。","difference":"逆行列は掛けると単位行列になる行列で、転置とは別物。","mnemonic":"行と列を入れ替え","field":"7","priority":"S"},{"id":"opus-132","category":"AIに必要な数理・統計知識","term":"連鎖律（チェインルール）","summary":"合成関数の微分を、各段階の微分の積で求める規則。","exam":"誤差逆伝播法の数学的な正体として問われやすい。","difference":"誤差逆伝播は連鎖律をネットワークに適用した具体的手続き。","mnemonic":"掛け算でさかのぼる","field":"7","priority":"S"},{"id":"opus-133","category":"機械学習の概要","term":"Actor-Critic","summary":"方策を学ぶActorと価値を評価するCriticを組み合わせ、行動選択を改善する強化学習手法。","exam":"方策勾配法と価値関数を組み合わせる手法として、役割分担が問われやすい。","difference":"Actorは行動を選び、Criticはその行動の良さを評価する。","mnemonic":"役者と批評家","field":"2","priority":"A"},{"id":"opus-134","category":"機械学習の概要","term":"Q 学習","summary":"状態と行動の組み合わせの価値を学び、将来の報酬が大きくなる行動を選ぶ強化学習手法。","exam":"オフポリシーの価値ベース手法として、SARSAとの違いが問われやすい。","difference":"SARSAは実際に選んだ次行動で更新し、Q学習は最大価値の行動で更新する。","mnemonic":"行動価値を学ぶ","field":"2","priority":"A"},{"id":"opus-135","category":"機械学習の概要","term":"REINFORCE","summary":"得られた報酬を使って、良い結果につながった行動の確率を高める方策勾配法の一種。","exam":"方策を直接更新する代表的手法として、価値ベース手法との違いが問われやすい。","difference":"Q学習は行動価値を学ぶが、REINFORCEは方策そのものを更新する。","mnemonic":"報酬で方策更新","field":"2","priority":"A"},{"id":"opus-136","category":"機械学習の概要","term":"ROC 曲線・AUC","summary":"分類しきい値を変えたときの真陽性率と偽陽性率の関係を示し、AUCは全体性能を表す。","exam":"二値分類の評価で、しきい値に依存しにくい性能比較として問われやすい。","difference":"正解率は固定した判定結果を見るが、ROC・AUCはしきい値全体の性能を見る。","mnemonic":"しきい値評価地図","field":"2","priority":"A"},{"id":"opus-137","category":"機械学習の概要","term":"SARSA","summary":"状態・行動・報酬・次状態・次行動を使って行動価値を更新する強化学習手法。","exam":"オンポリシー手法として、Q学習との更新方法の違いが問われやすい。","difference":"Q学習は最大価値の次行動で更新し、SARSAは実際に選んだ次行動で更新する。","mnemonic":"実際の行動で更新","field":"2","priority":"A"},{"id":"opus-138","category":"機械学習の概要","term":"UCB 方策","summary":"平均報酬だけでなく試行回数の少なさも考慮し、不確かな選択肢も試す方策。","exam":"バンディット問題で、探索と活用を理論的に扱う方法として問われやすい。","difference":"ε-greedyはランダム探索、UCB方策は不確実性の大きさで探索を促す。","mnemonic":"未知にも点を足す","field":"2","priority":"A"},{"id":"opus-139","category":"機械学習の概要","term":"k- 分割交差検証","summary":"データをk個に分け、1つを検証用、残りを学習用にして評価をk回繰り返す方法。","exam":"交差検証の代表例として、限られたデータで安定して性能評価する方法として問われやすい。","difference":"ホールドアウト検証は1回分割、k分割交差検証は分割を入れ替えて複数回評価する。","mnemonic":"k回入れ替え評価","field":"2","priority":"A"},{"id":"opus-140","category":"機械学習の概要","term":"k-means 法","summary":"データを指定した数のクラスタに分け、各クラスタの中心に近いデータ同士をまとめる手法。","exam":"教師なし学習の代表例として、クラスタ数を事前に決める点が問われやすい。","difference":"階層的クラスタリングは段階的にまとめるが、k-means法は中心点を更新して分ける。","mnemonic":"中心で群分け","field":"2","priority":"A"},{"id":"opus-141","category":"機械学習の概要","term":"t-SNE","summary":"高次元データの近さを保ちながら、2次元や3次元に可視化しやすくする次元削減手法。","exam":"可視化向けの次元削減として、PCAとの違いや非線形な構造把握で問われやすい。","difference":"PCAは分散を重視する線形手法、t-SNEは近いデータのまとまりを可視化しやすい。","mnemonic":"近さを地図化","field":"2","priority":"A"},{"id":"opus-142","category":"機械学習の概要","term":"ε-greedy 方策","summary":"多くは価値が高い行動を選び、一定確率εでランダム行動を選んで探索する方策。","exam":"探索と活用のバランスを取る基本手法として、Q学習などと関連して問われやすい。","difference":"UCB方策は不確実性も考慮し、ε-greedyは一定確率でランダム探索する。","mnemonic":"たまに冒険する","field":"2","priority":"A"},{"id":"opus-143","category":"機械学習の概要","term":"アンサンブル学習","summary":"複数のモデルを組み合わせて、単独モデルより安定した高い予測性能を狙う学習方法。","exam":"バギング・ブースティング・ランダムフォレストなどの総称として問われやすい。","difference":"個別の手法名ではなく、複数モデルを組み合わせる考え方全体を指す。","mnemonic":"みんなで予測","field":"2","priority":"A"},{"id":"opus-144","category":"機械学習の概要","term":"ウォード法","summary":"クラスタを結合したときのばらつきの増加が小さい組み合わせからまとめる階層的手法。","exam":"階層的クラスタリングの手法として、デンドログラムと関連して問われやすい。","difference":"k-means法は非階層的、ウォード法は段階的にクラスタを結合する。","mnemonic":"ばらつき少なく結合","field":"2","priority":"A"},{"id":"opus-145","category":"機械学習の概要","term":"オッカムの剃刀","summary":"同じ程度に説明できるなら、より単純な仮説やモデルを選ぶべきという考え方。","exam":"過学習を避ける考え方や、AIC・BICの背景として問われやすい。","difference":"評価指標ではなく、不要に複雑な説明を避けるための原則。","mnemonic":"単純さを選ぶ","field":"2","priority":"A"},{"id":"opus-146","category":"機械学習の概要","term":"カーネル","summary":"データ同士の類似度や内積を計算する関数。SVMなどで非線形な関係を扱うために使う。","exam":"SVMやカーネルトリックとセットで、非線形分類を可能にする要素として問われやすい。","difference":"カーネルトリックは、カーネルを使って高次元計算を省く工夫。","mnemonic":"類似度の関数","field":"2","priority":"A"},{"id":"opus-147","category":"機械学習の概要","term":"カーネルトリック","summary":"高次元空間に写像した計算を直接行わず、カーネル関数で同等の結果を得る工夫。","exam":"SVMで非線形な分類境界を効率よく扱う仕組みとして問われやすい。","difference":"カーネルは関数そのもの、カーネルトリックはそれを使う計算上の工夫。","mnemonic":"高次元を省略","field":"2","priority":"A"},{"id":"opus-148","category":"機械学習の概要","term":"クラスタリング","summary":"正解ラベルなしのデータを、特徴の似ているもの同士のグループに分ける教師なし学習。","exam":"教師なし学習の代表例として、分類問題との違いが問われやすい。","difference":"分類は正解ラベルを学習するが、クラスタリングはラベルなしでグループ化する。","mnemonic":"似た者で分ける","field":"2","priority":"A"},{"id":"opus-149","category":"機械学習の概要","term":"コンテンツベースフィルタリング","summary":"商品の特徴や内容と、利用者が好んだ内容の類似性をもとに推薦する方法。","exam":"協調フィルタリングとの違いとして、利用者同士ではなく内容を見る点が問われやすい。","difference":"協調フィルタリングは人の行動の類似、こちらはアイテム内容の類似を見る。","mnemonic":"中身で推薦","field":"2","priority":"A"},{"id":"opus-150","category":"機械学習の概要","term":"コールドスタート問題","summary":"新しい利用者や商品に十分な履歴がなく、推薦や予測の精度が出にくい問題。","exam":"レコメンデーションで、協調フィルタリングの弱点として問われやすい。","difference":"過学習は訓練データへの寄りすぎ、コールドスタートは初期データ不足の問題。","mnemonic":"履歴ゼロの壁","field":"2","priority":"A"},{"id":"opus-151","category":"機械学習の概要","term":"サポートベクターマシン (SVM)","summary":"クラスの境界に近いデータを基準に、マージンが最大になる識別境界を求める分類手法。","exam":"マージン最大化やカーネルトリックと結びつき、分類アルゴリズムとして問われやすい。","difference":"ロジスティック回帰は確率的に分類し、SVMはマージン最大化を重視する。","mnemonic":"余白を最大に","field":"2","priority":"A"},{"id":"opus-152","category":"機械学習の概要","term":"デンドログラム (樹形図)","summary":"階層的クラスタリングの結果を、どのクラスタがどの順で結合したかを木で表した図。","exam":"ウォード法などの階層的クラスタリング結果の読み取りとして問われやすい。","difference":"クラスタリング手法そのものではなく、階層構造の結果を表す図。","mnemonic":"群れの家系図","field":"2","priority":"A"},{"id":"opus-153","category":"機械学習の概要","term":"トピックモデル","summary":"文書集合の中にある隠れた話題を推定し、文書や単語をトピックで説明するモデル。","exam":"自然言語処理の教師なし学習として、LDAとの関係で問われやすい。","difference":"LDAはトピックモデルの代表手法で、トピックモデルは考え方全体を指す。","mnemonic":"隠れ話題を探す","field":"2","priority":"A"},{"id":"opus-154","category":"機械学習の概要","term":"バギング","summary":"元データから複数の訓練データを作り、複数モデルを並列に学習して予測を統合する手法。","exam":"ランダムフォレストの基礎として、分散を下げ過学習を抑える方法で問われやすい。","difference":"ブースティングは順に弱点を補うが、バギングは並列に学習して平均化する。","mnemonic":"並列で平均化","field":"2","priority":"A"},{"id":"opus-155","category":"機械学習の概要","term":"バンディットアルゴリズム","summary":"複数の選択肢から、報酬を観測しながら最も得な選択を探す問題を解く手法群。","exam":"探索と活用のトレードオフを説明する例として、ε-greedyやUCBと出やすい。","difference":"MDPは状態遷移を扱うが、バンディットは基本的に状態遷移を考えない。","mnemonic":"試して稼ぐ","field":"2","priority":"A"},{"id":"opus-156","category":"機械学習の概要","term":"ブースティング","summary":"弱い学習器を順番に学習させ、前の誤りを補うことで全体の予測性能を高める手法。","exam":"バギングとの違いとして、逐次的にモデルを追加する点が問われやすい。","difference":"バギングは並列に独立学習、ブースティングは順番に誤りを補正する。","mnemonic":"弱点を継ぎ足す","field":"2","priority":"A"},{"id":"opus-157","category":"機械学習の概要","term":"ブートストラップサンプリング","summary":"元データから重複を許してランダムに標本を取り出し、複数の訓練データを作る方法。","exam":"バギングやランダムフォレストで使われるデータ作成方法として問われやすい。","difference":"バギングは学習手法、ブートストラップサンプリングは標本を作る方法。","mnemonic":"重複あり抽出","field":"2","priority":"A"},{"id":"opus-158","category":"機械学習の概要","term":"ベイズ情報量規準 (BIC)","summary":"モデルの当てはまりと複雑さを評価する指標。AICより複雑なモデルに強い罰則を与えやすい。","exam":"AICとの比較として、モデル選択や複雑さへの罰則の違いが問われやすい。","difference":"AICよりBICの方が、データ数を考慮して複雑さを厳しく見る傾向がある。","mnemonic":"複雑さに厳しい","field":"2","priority":"A"},{"id":"opus-159","category":"機械学習の概要","term":"ベクトル自己回帰モデル (VARモデル)","summary":"複数の時系列データが互いに影響すると考え、それぞれの過去値から予測するモデル。","exam":"ARモデルとの違いとして、複数の時系列を同時に扱う点が問われやすい。","difference":"ARモデルは単一系列中心、VARモデルは複数系列の相互関係も扱う。","mnemonic":"複数時系列で予測","field":"2","priority":"A"},{"id":"opus-160","category":"機械学習の概要","term":"ホールドアウト検証","summary":"データを学習用とテスト用に一度だけ分け、学習していないデータで性能を評価する方法。","exam":"交差検証との違いとして、簡単だが分割の仕方に評価が左右されやすい点が問われやすい。","difference":"交差検証は分割を変えて複数回評価し、ホールドアウトは基本的に一度だけ分ける。","mnemonic":"一度分けて評価","field":"2","priority":"A"},{"id":"opus-161","category":"機械学習の概要","term":"マルコフ決定過程","summary":"状態・行動・報酬・状態遷移で意思決定を表す枠組み。次状態は現在の状態と行動に依存する。","exam":"強化学習の基本モデルとして、状態・行動・報酬・遷移確率が問われやすい。","difference":"バンディットは状態遷移をほぼ扱わず、MDPは状態が移り変わる。","mnemonic":"状態が移る決定","field":"2","priority":"A"},{"id":"opus-162","category":"機械学習の概要","term":"マージン最大化","summary":"分類境界と最も近いデータとの距離をできるだけ大きくし、汎化性能を高める考え方。","exam":"SVMの基本原理として、境界からの余白を最大にする点が問われやすい。","difference":"SVMは手法名、マージン最大化はその分類境界を決める考え方。","mnemonic":"境界の余白最大","field":"2","priority":"A"},{"id":"opus-163","category":"機械学習の概要","term":"ランダムフォレスト","summary":"多数の決定木を作り、それぞれの予測を集約することで精度と安定性を高める手法。","exam":"バギングを用いた代表的アンサンブル手法として、決定木との関係が問われやすい。","difference":"決定木は単体モデル、ランダムフォレストは多数の決定木の集合。","mnemonic":"木を森にする","field":"2","priority":"A"},{"id":"opus-164","category":"機械学習の概要","term":"ロジスティック回帰","summary":"入力からクラスに属する確率を求め、主に二値分類に使われる線形分類モデル。","exam":"名前に回帰とあるが分類に使う点が、ひっかけとして問われやすい。","difference":"線形回帰は数値予測、ロジスティック回帰は確率を使った分類。","mnemonic":"回帰名だが分類","field":"2","priority":"A"},{"id":"opus-165","category":"機械学習の概要","term":"主成分分析 (PCA)","summary":"データの分散が大きい方向を主成分として取り出し、少ない軸で情報を表す線形次元削減。","exam":"次元削減の代表手法として、分散を最大化する方向を選ぶ点が問われやすい。","difference":"t-SNEは可視化向きの非線形手法、PCAは分散を重視する線形手法。","mnemonic":"分散の大軸","field":"2","priority":"A"},{"id":"opus-166","category":"機械学習の概要","term":"二乗平均平方根誤差 (RMSE)","summary":"MSEの平方根を取った回帰評価指標。元の目的変数と同じ単位で誤差を見られる。","exam":"MSEとの関係や、回帰問題の誤差評価として問われやすい。","difference":"MSEは二乗単位、RMSEは平方根を取るため元データの単位に戻る。","mnemonic":"MSEを元単位へ","field":"2","priority":"A"},{"id":"opus-167","category":"機械学習の概要","term":"交差検証","summary":"データの分け方を変えながら学習と評価を行い、モデル性能をより安定して見積もる方法。","exam":"ホールドアウト検証との違いとして、複数回評価してばらつきを抑える点が問われやすい。","difference":"k分割交差検証は、交差検証をk個の分割で行う具体的な方法。","mnemonic":"分け替えて評価","field":"2","priority":"A"},{"id":"opus-168","category":"機械学習の概要","term":"偽陽性・偽陰性","summary":"偽陽性は本当は陰性なのに陽性と判定する誤り、偽陰性は本当は陽性なのに陰性と判定する誤り。","exam":"医療診断やスパム判定などで、適合率・再現率との関係が問われやすい。","difference":"偽陽性は誤検出、偽陰性は見逃しとして覚えると区別しやすい。","mnemonic":"誤検出と見逃し","field":"2","priority":"A"},{"id":"opus-169","category":"機械学習の概要","term":"分類問題","summary":"入力データをあらかじめ決められたカテゴリやラベルに分ける問題。迷惑メール判定などが例。","exam":"回帰問題との違いとして、出力が数値ではなくカテゴリである点が問われやすい。","difference":"回帰問題は連続値を予測し、分類問題はカテゴリを予測する。","mnemonic":"ラベルを予測","field":"2","priority":"A"},{"id":"opus-170","category":"機械学習の概要","term":"割引率","summary":"将来の報酬を現在の価値としてどれだけ重視するかを決める係数。0から1の値を取る。","exam":"強化学習で、近い報酬と遠い報酬の重みづけとして問われやすい。","difference":"学習率は更新の大きさ、割引率は将来報酬の重みを決める。","mnemonic":"未来報酬の重み","field":"2","priority":"A"},{"id":"opus-171","category":"機械学習の概要","term":"勾配ブースティング","summary":"前のモデルの誤差を次のモデルが補うように、弱い学習器を順に追加して精度を高める手法。","exam":"ブースティングの代表例として、誤差を段階的に改善する点が問われやすい。","difference":"バギングは並列に学習し、勾配ブースティングは順番に弱点を補う。","mnemonic":"誤差を順に補う","field":"2","priority":"A"},{"id":"opus-172","category":"機械学習の概要","term":"協調フィルタリング","summary":"似た利用者の行動や評価をもとに、利用者が好みそうな商品や作品を推薦する方法。","exam":"レコメンデーションの代表手法として、コールドスタート問題とセットで問われやすい。","difference":"コンテンツベースは内容の類似、協調フィルタリングは人の行動の類似を見る。","mnemonic":"似た人から推薦","field":"2","priority":"A"},{"id":"opus-173","category":"機械学習の概要","term":"単回帰分析","summary":"1つの説明変数を使って、1つの目的変数を予測するもっとも基本的な回帰分析。","exam":"重回帰分析との違いとして、説明変数が1つだけである点が問われやすい。","difference":"重回帰分析は複数の説明変数を使い、単回帰分析は1つだけ使う。","mnemonic":"説明変数は1つ","field":"2","priority":"A"},{"id":"opus-174","category":"機械学習の概要","term":"回帰問題","summary":"数値を予測する問題。住宅価格や売上、気温など連続的な値を出力する場合に使う。","exam":"分類問題との違いとして、出力がカテゴリではなく連続値である点が問われやすい。","difference":"分類問題はラベルを予測し、回帰問題は数値を予測する。","mnemonic":"数値を予測","field":"2","priority":"A"},{"id":"opus-175","category":"機械学習の概要","term":"多クラス分類","summary":"3つ以上のカテゴリの中から、入力データがどのクラスに属するかを予測する分類問題。","exam":"二値分類との違いとして、出力候補が3種類以上ある分類として問われやすい。","difference":"二値分類は2クラス、多クラス分類は3クラス以上を扱う。","mnemonic":"三択以上の分類","field":"2","priority":"A"},{"id":"opus-176","category":"機械学習の概要","term":"多次元尺度構成法 (MDS)","summary":"データ間の距離や非類似度をできるだけ保ちながら、低次元空間に配置する可視化手法。","exam":"次元削減やデータ可視化の手法として、距離関係を保つ点が問われやすい。","difference":"PCAは分散を重視し、MDSはデータ同士の距離関係を重視する。","mnemonic":"距離を地図化","field":"2","priority":"A"},{"id":"opus-177","category":"機械学習の概要","term":"平均二乗誤差 (MSE)","summary":"予測値と正解値の差を二乗して平均した回帰評価指標。大きな誤差を強く罰する。","exam":"回帰モデルの評価指標として、RMSEやMAEとの違いが問われやすい。","difference":"RMSEはMSEの平方根、MAEは誤差の絶対値を平均する。","mnemonic":"誤差を二乗平均","field":"2","priority":"A"},{"id":"opus-178","category":"機械学習の概要","term":"平均絶対値誤差 (MAE)","summary":"予測値と正解値の差の絶対値を平均した回帰評価指標。外れ値の影響がMSEより小さい。","exam":"MSEやRMSEとの違いとして、大きな誤差を二乗しない点が問われやすい。","difference":"MSEは誤差を二乗するが、MAEは絶対値をそのまま平均する。","mnemonic":"誤差を絶対平均","field":"2","priority":"A"},{"id":"opus-179","category":"機械学習の概要","term":"方策勾配法","summary":"行動を選ぶ確率を表す方策を、報酬が大きくなる方向へ直接更新する強化学習手法。","exam":"REINFORCEやActor-Criticの基礎として、価値ベース手法との違いが問われやすい。","difference":"Q学習は価値を学んで行動を選び、方策勾配法は方策を直接学ぶ。","mnemonic":"方策を直接磨く","field":"2","priority":"A"},{"id":"opus-180","category":"機械学習の概要","term":"次元削減","summary":"多くの特徴量を、重要な情報をできるだけ残しながら少ない変数にまとめる処理。","exam":"可視化・計算量削減・次元の呪い対策として、PCAなどと関連して問われやすい。","difference":"特徴量選択は一部を選ぶが、次元削減は新しい少数の特徴に変換することが多い。","mnemonic":"情報を圧縮","field":"2","priority":"A"},{"id":"opus-181","category":"機械学習の概要","term":"正解率・適合率・再現率・F 値","summary":"正解率は全体の正しさ、適合率は陽性判定の正しさ、再現率は陽性の見逃しにくさ、F値は両者の調和平均。","exam":"分類評価の頻出指標として、不均衡データでは正解率だけでは不十分な点が問われやすい。","difference":"適合率は誤検出を重視し、再現率は見逃しを重視する。","mnemonic":"分類評価四兄弟","field":"2","priority":"A"},{"id":"opus-182","category":"機械学習の概要","term":"汎化性能","summary":"学習に使っていない未知データに対しても、正しく予測できる能力。機械学習で重要。","exam":"過学習や交差検証とセットで、モデルの本当の性能として問われやすい。","difference":"訓練性能は学習データ上の性能、汎化性能は未知データへの性能。","mnemonic":"未知にも強い","field":"2","priority":"A"},{"id":"opus-183","category":"機械学習の概要","term":"決定木","summary":"条件分岐を木構造で表し、特徴量に基づいて分類や回帰を行う分かりやすいモデル。","exam":"解釈しやすいが過学習しやすいモデルとして、ランダムフォレストと関連して問われやすい。","difference":"ランダムフォレストは多数の決定木を組み合わせたアンサンブル手法。","mnemonic":"分岐で判断","field":"2","priority":"A"},{"id":"opus-184","category":"機械学習の概要","term":"混同行列","summary":"分類結果を真陽性・偽陽性・真陰性・偽陰性に分け、判定の内訳を表す表。","exam":"正解率・適合率・再現率・F値を計算する土台として問われやすい。","difference":"評価指標そのものではなく、分類結果を整理するための表。","mnemonic":"分類結果の表","field":"2","priority":"A"},{"id":"opus-185","category":"機械学習の概要","term":"潜在的ディリクレ配分法 (LDA)","summary":"文書は複数のトピックの混合であり、各トピックは単語分布を持つと考えるトピックモデル。","exam":"トピックモデルの代表手法として、文書分類ではなく潜在トピック推定で問われやすい。","difference":"線形判別分析のLDAとは別物で、ここではトピックモデルを指す。","mnemonic":"文書に隠れ話題","field":"2","priority":"A"},{"id":"opus-186","category":"機械学習の概要","term":"特異値分解 (SVD)","summary":"行列を複数の行列に分解し、重要な成分を取り出す手法。次元削減や推薦で使われる。","exam":"行列分解による次元削減や、レコメンデーションとの関連で問われやすい。","difference":"PCAと関連が深いが、SVDは行列を分解する数学的手法として扱われる。","mnemonic":"行列を分解","field":"2","priority":"A"},{"id":"opus-187","category":"機械学習の概要","term":"状態価値関数","summary":"ある状態にいるとき、そこから将来どれだけ報酬が期待できるかを表す関数。","exam":"強化学習の価値評価として、行動価値関数との違いが問われやすい。","difference":"行動価値関数は行動まで含むが、状態価値関数は状態そのものの良さを見る。","mnemonic":"状態だけの価値","field":"2","priority":"A"},{"id":"opus-188","category":"機械学習の概要","term":"真陽性・真陰性","summary":"真陽性は陽性を正しく陽性と判定し、真陰性は陰性を正しく陰性と判定した結果。","exam":"混同行列の基本要素として、偽陽性・偽陰性との対応が問われやすい。","difference":"真は正しく判定、偽は誤って判定した結果を表す。","mnemonic":"正しく当てた陽陰","field":"2","priority":"A"},{"id":"opus-189","category":"機械学習の概要","term":"線形回帰","summary":"入力と出力の関係を直線や平面で表し、数値を予測する基本的な回帰モデル。","exam":"単回帰・重回帰の土台として、説明変数と目的変数の関係で問われやすい。","difference":"ロジスティック回帰は分類に使われるが、線形回帰は数値予測に使う。","mnemonic":"線で数値予測","field":"2","priority":"A"},{"id":"opus-190","category":"機械学習の概要","term":"自己回帰モデル (ARモデル)","summary":"時系列データで、過去の自分自身の値を使って現在や未来の値を予測するモデル。","exam":"時系列分析の基本モデルとして、過去の値を説明変数にする点が問われやすい。","difference":"VARモデルは複数系列を扱うが、ARモデルは主に単一系列の過去値を見る。","mnemonic":"過去の自分で予測","field":"2","priority":"A"},{"id":"opus-191","category":"機械学習の概要","term":"行動価値関数","summary":"ある状態で特定の行動を選んだとき、その後に期待できる累積報酬を表す関数。","exam":"Q学習やSARSAで学習する対象として、状態価値関数との違いが問われやすい。","difference":"状態価値関数は状態の良さ、行動価値関数は状態と行動の組の良さ。","mnemonic":"状態×行動の価値","field":"2","priority":"A"},{"id":"opus-192","category":"機械学習の概要","term":"赤池情報量規準 (AIC)","summary":"モデルの当てはまりと複雑さのバランスを評価し、小さいほど良いモデル選択指標。","exam":"過度に複雑なモデルを避ける指標として、BICやオッカムの剃刀と関連しやすい。","difference":"BICはAICよりモデルの複雑さに強い罰則を与える傾向がある。","mnemonic":"当てはめと罰則","field":"2","priority":"A"},{"id":"opus-193","category":"機械学習の概要","term":"過学習","summary":"訓練データに合わせすぎて、未知データへの予測性能が下がる状態。汎化性能の低下を招く。","exam":"訓練精度は高いのにテスト精度が低い状態として、頻出のひっかけになりやすい。","difference":"汎化性能は未知データへの強さ、過学習はそれが弱くなる状態。","mnemonic":"覚えすぎて弱い","field":"2","priority":"A"},{"id":"opus-194","category":"機械学習の概要","term":"重回帰分析","summary":"複数の説明変数を使って、1つの目的変数を予測する回帰分析。要因を同時に扱える。","exam":"単回帰分析との違いとして、説明変数が複数ある点が問われやすい。","difference":"単回帰分析は説明変数が1つ、重回帰分析は複数の説明変数を使う。","mnemonic":"説明変数は複数","field":"2","priority":"A"},{"id":"opus-195","category":"ディープラーニングの要素技術","term":"A-D 変換","summary":"連続的なアナログ音声信号を、コンピュータで扱える離散的なデジタル信号へ変換する処理。","exam":"音声処理の入口として、サンプリングや量子化、PCMとの関係で問われやすい。","difference":"PCMはデジタル化した音声の表現方式で、A-D変換は変換処理そのもの。","mnemonic":"音を数字に変換","field":"4/5","priority":"A"},{"id":"opus-196","category":"ディープラーニングの要素技術","term":"A3C","summary":"複数のエージェントが並列に環境を探索し、Actor-Criticで方策と価値を学習する強化学習手法。","exam":"非同期・並列学習を使う深層強化学習として、Actor-Criticとの関係が問われやすい。","difference":"PPOは方策更新の安定化が中心、A3Cは複数環境で非同期に学習する。","mnemonic":"並列で方策学習","field":"4/5","priority":"A"},{"id":"opus-197","category":"ディープラーニングの要素技術","term":"AIエージェント","summary":"目標を与えると、道具の利用や複数手順の実行を自律的に進めるAI。","exam":"生成AIの応用形態として、ツール利用や自律実行の文脈で問われやすい。","difference":"チャットボットは対話中心、エージェントは行動と手順の実行が中心。","mnemonic":"自分で手順を実行","field":"4/5","priority":"A"},{"id":"opus-198","category":"ディープラーニングの要素技術","term":"APE-X","summary":"多数のActorが経験を集め、優先度付き経験再生を使って効率よくDQNを学習する分散強化学習。","exam":"分散深層強化学習として、経験再生とDQNの拡張の文脈で問われやすい。","difference":"A3Cは非同期Actor-Critic、APE-Xは分散して経験を集めDQNを強化する。","mnemonic":"経験を大量収集","field":"4/5","priority":"A"},{"id":"opus-199","category":"ディープラーニングの要素技術","term":"Agent57","summary":"多数の探索方策を使い分け、Atariゲーム群で高い性能を示した深層強化学習エージェント。","exam":"強化学習の発展例として、探索と活用を高度に切り替える事例で問われやすい。","difference":"RainbowはDQN改良の統合、Agent57は探索方策の多様化も重視する。","mnemonic":"多様な探索で攻略","field":"4/5","priority":"A"},{"id":"opus-200","category":"ディープラーニングの要素技術","term":"AlexNet","summary":"2012年の画像認識コンペで高精度を示し、深層学習ブームのきっかけになったCNN。","exam":"ImageNet・ILSVRC・GPU利用・ReLUなどと結びつき、第3次AIブームの象徴として問われやすい。","difference":"LeNetより大規模で深く、VGGやResNet以前の代表的CNN。","mnemonic":"深層学習の火付け","field":"4/5","priority":"A"},{"id":"opus-201","category":"ディープラーニングの要素技術","term":"Atrous Convolution","summary":"フィルタの間隔を空けて畳み込み、パラメータを大きく増やさず受容野を広げる手法。","exam":"画像セグメンテーションなどで、広い文脈を捉える畳み込みとして問われやすい。","difference":"Dilated Convolutionとほぼ同義で、穴あき畳み込みとも呼ばれる。","mnemonic":"穴あき畳み込み","field":"4/5","priority":"A"},{"id":"opus-202","category":"ディープラーニングの要素技術","term":"Attention","summary":"入力のどの部分に注目するか重みづけし、重要な情報を選んで利用する仕組み。","exam":"Seq2SeqやTransformerの中核として、長距離依存を扱いやすい点が問われやすい。","difference":"Self-Attentionは同じ系列内で注目し、Attentionはより広い注意機構全般を指す。","mnemonic":"重要部分に注目","field":"4/5","priority":"A"},{"id":"opus-203","category":"ディープラーニングの要素技術","term":"BERT","summary":"Transformerのエンコーダを使い、文の左右両方向の文脈を考慮して言語表現を学習するモデル。","exam":"事前学習済み言語モデルとして、Transformerや双方向文脈との関係が問われやすい。","difference":"ELMoも文脈を扱うが、BERTはTransformerにより双方向文脈を強く扱う。","mnemonic":"左右から読む言語AI","field":"4/5","priority":"A"},{"id":"opus-204","category":"ディープラーニングの要素技術","term":"BPTT","summary":"RNNを時間方向に展開し、各時刻の誤差を逆伝播して重みを更新する学習方法。","exam":"RNNの学習手法として、時間方向に誤差逆伝播する点が問われやすい。","difference":"通常の誤差逆伝播は層方向中心、BPTTは時系列の時間方向にも展開する。","mnemonic":"時間にも逆伝播","field":"4/5","priority":"A"},{"id":"opus-205","category":"ディープラーニングの要素技術","term":"BoW (Bag-of-Words)","summary":"文書を単語の出現回数で表す方法。語順は無視し、どの単語がどれだけ出たかを特徴にする。","exam":"古典的な自然言語処理の特徴表現として、n-gramやTF-IDFとの違いが問われやすい。","difference":"n-gramは語順の一部を残すが、BoWは基本的に語順を捨てる。","mnemonic":"単語を袋に入れる","field":"4/5","priority":"A"},{"id":"opus-206","category":"ディープラーニングの要素技術","term":"Brightness","summary":"画像全体の明るさを変えるデータ拡張。照明条件の違いに強いモデルを作るために使う。","exam":"画像認識のデータ拡張として、環境変化への頑健性を高める方法で問われやすい。","difference":"Contrastは明暗差の調整、Brightnessは画像全体の明るさの調整。","mnemonic":"明るさを変える","field":"4/5","priority":"A"},{"id":"opus-207","category":"ディープラーニングの要素技術","term":"CAM","summary":"CNNの分類結果に強く影響した画像領域を、特徴マップから可視化する手法。","exam":"CNNの判断根拠をヒートマップで示すXAI手法として問われやすい。","difference":"Grad-CAMは勾配を使うため、CAMより適用できるモデル構造が広い。","mnemonic":"注目領域を可視化","field":"4/5","priority":"A"},{"id":"opus-208","category":"ディープラーニングの要素技術","term":"CBOW","summary":"周辺単語から中央の単語を予測するword2vecの学習方式。単語の分散表現を得る。","exam":"word2vecの代表手法として、Skip-gramとの違いや周辺文脈の使い方が問われやすい。","difference":"Skip-gramは中心語から周辺語を予測し、CBOWは周辺語から中心語を予測する。","mnemonic":"周りから中心語","field":"4/5","priority":"A"},{"id":"opus-209","category":"ディープラーニングの要素技術","term":"CEC","summary":"LSTMのセル状態で情報を長く保持し、勾配が流れやすくなるようにした仕組み。","exam":"LSTMが長期依存を扱える理由として、ゲート機構や勾配消失対策と問われやすい。","difference":"ゲート機構は情報の出入りを制御し、CECは情報を保つ通り道として働く。","mnemonic":"記憶の通り道","field":"4/5","priority":"A"},{"id":"opus-210","category":"ディープラーニングの要素技術","term":"CLIP","summary":"画像とテキストを同じ表現空間に対応づけ、文章から画像の意味を扱えるようにしたモデル。","exam":"マルチモーダル基盤モデルとして、Zero-shot画像分類やText-To-Imageとの関係が問われやすい。","difference":"DALL-Eは画像生成、CLIPは画像とテキストの対応関係を学ぶ。","mnemonic":"画像と言葉を結ぶ","field":"4/5","priority":"A"},{"id":"opus-211","category":"ディープラーニングの要素技術","term":"CTC","summary":"入力音声と出力文字の長さが一致しない場合でも、対応関係を学習できる損失関数。","exam":"音声認識で、フレームごとのラベル付けが難しい系列学習に使う方法として問われやすい。","difference":"教師強制は正解系列を入力に使う学習法、CTCは入出力の対応を推定する損失。","mnemonic":"ずれた系列を学ぶ","field":"4/5","priority":"A"},{"id":"opus-212","category":"ディープラーニングの要素技術","term":"Chain-of-Thought（思考の連鎖）","summary":"途中の推論過程を書かせることで、複雑な問題の精度を上げるプロンプト手法。","exam":"段階的に考えさせる手法として、推論タスクの改善策で問われやすい。","difference":"Few-shotは例示、CoTは推論過程そのものを促す点が違う。","mnemonic":"考えさせて答える","field":"4/5","priority":"A"},{"id":"opus-213","category":"ディープラーニングの要素技術","term":"Contrast","summary":"画像の明暗差を変えるデータ拡張。見え方が変わっても同じ対象と認識できるようにする。","exam":"画像データ拡張の一種として、過学習を抑え汎化性能を高める文脈で問われやすい。","difference":"Brightnessは全体の明るさ、Contrastは明るい部分と暗い部分の差を変える。","mnemonic":"明暗差を変える","field":"4/5","priority":"A"},{"id":"opus-214","category":"ディープラーニングの要素技術","term":"Crop","summary":"画像の一部を切り出して学習に使うデータ拡張。対象の位置ずれや構図の違いに強くする。","exam":"画像データ拡張として、Random Cropなど位置変化への頑健性で問われやすい。","difference":"Cutoutは一部を隠すが、Cropは一部を切り出して入力として使う。","mnemonic":"一部を切り出す","field":"4/5","priority":"A"},{"id":"opus-215","category":"ディープラーニングの要素技術","term":"CutMix","summary":"2枚の画像の一部を切り貼りし、ラベルも割合に応じて混ぜるデータ拡張手法。","exam":"画像分類の汎化性能向上手法として、Mixupとの違いが問われやすい。","difference":"Mixupは画像全体を混ぜ、CutMixは一部領域を切り貼りして混ぜる。","mnemonic":"切って混ぜる","field":"4/5","priority":"A"},{"id":"opus-216","category":"ディープラーニングの要素技術","term":"Cutout","summary":"画像の一部領域を黒塗りなどで隠し、欠けた情報でも認識できるようにするデータ拡張。","exam":"画像認識の正則化的手法として、Random Erasingとの関係で問われやすい。","difference":"Random Erasingと近いが、Cutoutは固定的な領域マスクとして説明されることが多い。","mnemonic":"一部を隠す","field":"4/5","priority":"A"},{"id":"opus-217","category":"ディープラーニングの要素技術","term":"CycleGAN","summary":"対応するペア画像がなくても、馬をシマウマ風にするような画像変換を学習するGAN。","exam":"画像変換の生成モデルとして、Pix2Pixとの教師データの違いが問われやすい。","difference":"Pix2Pixは対応ペア画像が必要で、CycleGANは対応なし画像集合から変換を学ぶ。","mnemonic":"対応なし変換","field":"4/5","priority":"A"},{"id":"opus-218","category":"ディープラーニングの要素技術","term":"DALL-E","summary":"テキストの指示から画像を生成するモデル。言語理解と画像生成を組み合わせた代表例。","exam":"Text-To-Imageの代表的モデルとして、生成AIやマルチモーダルモデルの文脈で問われやすい。","difference":"CLIPは画像と言葉を対応づけ、DALL-Eは言葉から画像を生成する。","mnemonic":"言葉から絵を作る","field":"4/5","priority":"A"},{"id":"opus-219","category":"ディープラーニングの要素技術","term":"DCGAN","summary":"畳み込みニューラルネットワークを使って画像生成を行うGAN。GANを画像生成に広く使わせた代表例。","exam":"GANの画像生成モデルとして、CNNを生成器・識別器に使う点が問われやすい。","difference":"GANは枠組み全体、DCGANは畳み込み層を用いた画像生成向けGAN。","mnemonic":"CNNで画像生成","field":"4/5","priority":"A"},{"id":"opus-220","category":"ディープラーニングの要素技術","term":"DQN","summary":"深層ニューラルネットワークで行動価値関数を近似し、Q学習を高次元入力へ広げた手法。","exam":"深層強化学習の代表例として、Atariや経験再生、ターゲットネットワークと問われやすい。","difference":"Q学習は表形式でも扱えるが、DQNはニューラルネットでQ値を近似する。","mnemonic":"深層Q学習","field":"4/5","priority":"A"},{"id":"opus-221","category":"ディープラーニングの要素技術","term":"DeepLab","summary":"空間解像度を保つ畳み込みなどを使い、画像の各画素を分類するセマンティックセグメンテーション手法。","exam":"セグメンテーション手法として、Dilated ConvolutionやAtrous Convolutionとの関係で問われやすい。","difference":"Faster R-CNNは物体検出、DeepLabは画素単位の領域分類が中心。","mnemonic":"画素ごと分類","field":"4/5","priority":"A"},{"id":"opus-222","category":"ディープラーニングの要素技術","term":"DenseNet","summary":"各層の出力を後続の層へ密に接続し、特徴の再利用と勾配伝播をしやすくしたCNN。","exam":"ResNetとの比較で、層を足すだけでなく特徴を連結して使う点が問われやすい。","difference":"ResNetは残差を加算し、DenseNetは前層の特徴を連結して使う。","mnemonic":"特徴を全部つなぐ","field":"4/5","priority":"A"},{"id":"opus-223","category":"ディープラーニングの要素技術","term":"Depthwise Separable Convolution","summary":"チャンネルごとの畳み込みと1×1畳み込みに分け、計算量を減らす畳み込み手法。","exam":"軽量CNNの要素技術として、通常の畳み込みより計算量を削減する点が問われやすい。","difference":"通常の畳み込みは空間方向とチャンネル方向を同時に処理する。","mnemonic":"分けて軽くする","field":"4/5","priority":"A"},{"id":"opus-224","category":"ディープラーニングの要素技術","term":"Diffusion Model","summary":"データにノイズを加える過程を学び、逆にノイズを少しずつ除去して生成するモデル。","exam":"画像生成AIの代表技術として、GANとの違いやノイズ除去過程が問われやすい。","difference":"GANは生成器と識別器の競争、Diffusion Modelはノイズ除去を段階的に学ぶ。","mnemonic":"ノイズから生成","field":"4/5","priority":"A"},{"id":"opus-225","category":"ディープラーニングの要素技術","term":"Dilated Convolution","summary":"フィルタ要素の間に隙間を入れて畳み込み、解像度を保ちつつ広い範囲を参照する手法。","exam":"CNNで受容野を広げる方法として、Atrous Convolutionとの関係が問われやすい。","difference":"Atrous Convolutionとほぼ同義で、どちらも間隔を空けた畳み込みを指す。","mnemonic":"間隔で広く見る","field":"4/5","priority":"A"},{"id":"opus-226","category":"ディープラーニングの要素技術","term":"ELMo","summary":"単語の意味を固定せず、文脈に応じて異なる単語ベクトルを生成する言語表現モデル。","exam":"文脈依存の単語埋め込みとして、word2vecやBERTとの違いが問われやすい。","difference":"word2vecは単語ごとに固定表現、ELMoは文脈ごとに表現が変わる。","mnemonic":"文脈で意味変化","field":"4/5","priority":"A"},{"id":"opus-227","category":"ディープラーニングの要素技術","term":"EfficientNet","summary":"ネットワークの深さ・幅・解像度をバランスよく拡大し、精度と効率を両立させたCNN。","exam":"軽量・高性能な画像分類モデルとして、MobileNetやNASとの関係で問われやすい。","difference":"MobileNetは軽量化重視、EfficientNetは複数方向の拡大バランスを重視する。","mnemonic":"効率よく大きく","field":"4/5","priority":"A"},{"id":"opus-228","category":"ディープラーニングの要素技術","term":"FCN (Fully Convolutional Netwok)","summary":"全結合層を畳み込み層に置き換え、画像の各位置に対して画素単位の分類を行うモデル。","exam":"セマンティックセグメンテーションの基本モデルとして、全結合層を使わない点が問われやすい。","difference":"CNN分類モデルは画像全体を分類し、FCNは各画素にラベルを与える。","mnemonic":"全畳み込みで画素","field":"4/5","priority":"A"},{"id":"opus-229","category":"ディープラーニングの要素技術","term":"FPN","summary":"異なる解像度の特徴マップを階層的に組み合わせ、小さい物体から大きい物体まで検出しやすくする構造。","exam":"物体検出で多スケール特徴を扱う仕組みとして、Faster R-CNNなどと関連して問われやすい。","difference":"単一特徴マップではなく、複数階層の特徴をピラミッド状に使う。","mnemonic":"特徴のピラミッド","field":"4/5","priority":"A"},{"id":"opus-230","category":"ディープラーニングの要素技術","term":"Fast R-CNN","summary":"候補領域ごとにCNNを何度も計算せず、特徴マップを共有して物体検出を高速化した手法。","exam":"R-CNN系の改良として、候補領域処理を効率化した流れで問われやすい。","difference":"Faster R-CNNは候補領域の生成もニューラルネットで行う点がさらに進んでいる。","mnemonic":"特徴を共有検出","field":"4/5","priority":"A"},{"id":"opus-231","category":"ディープラーニングの要素技術","term":"Faster R-CNN","summary":"RPNで物体候補領域を生成し、検出まで一体的に学習する高精度な物体検出手法。","exam":"二段階物体検出の代表として、Fast R-CNNやYOLO・SSDとの違いが問われやすい。","difference":"YOLOやSSDは一段階検出、Faster R-CNNは候補生成後に分類する二段階型。","mnemonic":"候補も学習する","field":"4/5","priority":"A"},{"id":"opus-232","category":"ディープラーニングの要素技術","term":"Few-shot","summary":"少数の例だけを与えて、新しいタスクやクラスに対応させる学習・推論の設定。","exam":"少量データでの汎化や、LLMのプロンプト内学習の文脈で問われやすい。","difference":"One-shotは例が1つ、Few-shotは少数の例を使う。","mnemonic":"少しの例で学ぶ","field":"4/5","priority":"A"},{"id":"opus-233","category":"ディープラーニングの要素技術","term":"Flamingo","summary":"画像や動画とテキストを組み合わせ、少数例から視覚と言語のタスクに対応するモデル。","exam":"マルチモーダル基盤モデルとして、Few-shotやVQAとの関係が問われやすい。","difference":"CLIPは対応づけ中心、Flamingoは画像を見ながら文章応答する能力が強調される。","mnemonic":"画像を見て答える","field":"4/5","priority":"A"},{"id":"opus-234","category":"ディープラーニングの要素技術","term":"GLUE","summary":"複数の自然言語理解タスクでモデル性能を評価するベンチマーク。言語モデル比較に使われる。","exam":"BERTなどの事前学習済み言語モデルの性能評価として問われやすい。","difference":"モデル名ではなく、自然言語理解モデルを評価するためのベンチマーク。","mnemonic":"言語AIの試験","field":"4/5","priority":"A"},{"id":"opus-235","category":"ディープラーニングの要素技術","term":"GRU","summary":"LSTMを簡略化した再帰型モデルで、ゲートにより必要な情報を保持・更新する。","exam":"LSTMより構造が簡単で計算量が少ないRNN改良版として問われやすい。","difference":"LSTMは主に3つのゲート、GRUは更新ゲートとリセットゲートで扱う。","mnemonic":"LSTMを軽量化","field":"4/5","priority":"A"},{"id":"opus-236","category":"ディープラーニングの要素技術","term":"GoogLeNet","summary":"Inceptionモジュールを使い、複数サイズの畳み込みを並列に組み合わせたCNN。","exam":"Inception構造や、VGG・ResNetなど画像分類モデルの歴史として問われやすい。","difference":"VGGは単純に層を深くし、GoogLeNetは複数の畳み込みを並列に組み合わせる。","mnemonic":"多窓で見るCNN","field":"4/5","priority":"A"},{"id":"opus-237","category":"ディープラーニングの要素技術","term":"Grad-CAM","summary":"分類結果に対する勾配を使い、CNNが画像のどこを見たかをヒートマップで示す手法。","exam":"画像認識モデルの説明手法として、CAMとの違いや可視化結果が問われやすい。","difference":"CAMは特定構造が必要だが、Grad-CAMは勾配を使い多くのCNNに適用しやすい。","mnemonic":"勾配で注目表示","field":"4/5","priority":"A"},{"id":"opus-238","category":"ディープラーニングの要素技術","term":"Image Captioning","summary":"画像の内容を説明する自然言語文を自動生成するタスク。視覚情報を文章へ変換する。","exam":"画像と言語を結ぶタスクとして、VQAやマルチモーダル学習と問われやすい。","difference":"VQAは画像に関する質問へ答え、Image Captioningは画像説明文を生成する。","mnemonic":"画像に説明文","field":"4/5","priority":"A"},{"id":"opus-239","category":"ディープラーニングの要素技術","term":"In-Context Learning","summary":"モデルを再学習せず、プロンプト内の例示だけでタスクに適応する能力。","exam":"Few-shot/One-shot/Zero-shotの土台として問われやすい。","difference":"ファインチューニングは重みが変わるが、こちらは重みが変わらない。","mnemonic":"例示だけで適応","field":"4/5","priority":"A"},{"id":"opus-240","category":"ディープラーニングの要素技術","term":"LIME","summary":"入力を少し変えたときの予測変化を使い、局所的に単純なモデルで説明するXAI手法。","exam":"ブラックボックスモデルの局所説明として、SHAPとの違いが問われやすい。","difference":"SHAPは特徴の貢献度を理論的に配分し、LIMEは近傍を単純モデルで近似する。","mnemonic":"近くを単純説明","field":"4/5","priority":"A"},{"id":"opus-241","category":"ディープラーニングの要素技術","term":"LSTM","summary":"長期記憶を保つセル状態とゲート機構により、長い時系列の依存関係を学習しやすくしたRNN。","exam":"勾配消失問題を抑えるRNNの代表的改良として問われやすい。","difference":"単純なRNNより長期依存を扱いやすく、GRUより構造は複雑。","mnemonic":"長く覚えるRNN","field":"4/5","priority":"A"},{"id":"opus-242","category":"ディープラーニングの要素技術","term":"LoRA","summary":"少数の追加パラメータだけを学習し、低コストで微調整する手法。","exam":"効率的なファインチューニング手法として問われやすい。","difference":"通常のファインチューニングは全パラメータを更新するが、LoRAはごく一部。","mnemonic":"少ない追加で調整","field":"4/5","priority":"A"},{"id":"opus-243","category":"ディープラーニングの要素技術","term":"Mask R-CNN","summary":"Faster R-CNNにマスク予測を追加し、物体検出とインスタンスセグメンテーションを行う手法。","exam":"物体の位置だけでなく個体ごとの領域を推定するモデルとして問われやすい。","difference":"Faster R-CNNは矩形検出中心、Mask R-CNNは個体ごとのマスクも出す。","mnemonic":"物体を塗り分ける","field":"4/5","priority":"A"},{"id":"opus-244","category":"ディープラーニングの要素技術","term":"Mixture of Experts（MoE）","summary":"複数の専門家ネットワークを用意し、入力ごとに一部だけを使う構造。","exam":"巨大モデルの計算効率化の工夫として問われやすい。","difference":"アンサンブルは全モデルを使って多数決、MoEは必要な専門家だけ使う。","mnemonic":"必要な専門家だけ","field":"4/5","priority":"A"},{"id":"opus-245","category":"ディープラーニングの要素技術","term":"Mixup","summary":"2つの入力画像とラベルを線形に混ぜ合わせ、滑らかな判断境界を学習させるデータ拡張。","exam":"過学習を抑えるデータ拡張として、CutMixとの違いが問われやすい。","difference":"CutMixは領域を貼り替え、Mixupは画像全体を重ねて混ぜる。","mnemonic":"全体を混ぜる","field":"4/5","priority":"A"},{"id":"opus-246","category":"ディープラーニングの要素技術","term":"MnasNet","summary":"モバイル端末での実行効率を考え、NASにより自動設計された軽量CNN。","exam":"NASやMobileNet系の軽量モデルとして、端末上での推論効率と関連して問われやすい。","difference":"MobileNetは人手設計の軽量CNNとして有名で、MnasNetは探索で設計された点が特徴。","mnemonic":"端末向け自動設計","field":"4/5","priority":"A"},{"id":"opus-247","category":"ディープラーニングの要素技術","term":"MobileNet","summary":"Depthwise Separable Convolutionを使い、計算量を減らしてモバイル向けにした軽量CNN。","exam":"軽量CNNの代表として、Depthwise Separable Convolutionとの関係が問われやすい。","difference":"EfficientNetは効率的な拡大設計、MobileNetは畳み込み分解による軽量化が中心。","mnemonic":"スマホ向けCNN","field":"4/5","priority":"A"},{"id":"opus-248","category":"ディープラーニングの要素技術","term":"Multi-Head Attention","summary":"複数のAttentionを並列に行い、異なる観点から単語間の関係や文脈を捉える仕組み。","exam":"Transformerの重要構成要素として、複数ヘッドで表現力を高める点が問われやすい。","difference":"Self-Attentionを複数のヘッドで並列実行するのがMulti-Head Attention。","mnemonic":"複数の目で見る","field":"4/5","priority":"A"},{"id":"opus-249","category":"ディープラーニングの要素技術","term":"NAS (Neural Architecture Search)","summary":"ニューラルネットワークの層構成や接続を、人手ではなく探索により自動で設計する方法。","exam":"モデル構造の自動設計として、MnasNetやEfficientNetなどと関連して問われやすい。","difference":"ハイパーパラメータ探索は設定値中心、NASはネットワーク構造そのものを探す。","mnemonic":"構造を自動探索","field":"4/5","priority":"A"},{"id":"opus-250","category":"ディープラーニングの要素技術","term":"NeRF","summary":"複数視点の画像から3次元空間の見え方を学び、新しい視点の画像を生成する手法。","exam":"3D表現や自由視点画像生成の技術として、画像生成との違いが問われやすい。","difference":"通常の画像生成は2D生成中心、NeRFは3D空間の見え方を学習する。","mnemonic":"視点を作る3D","field":"4/5","priority":"A"},{"id":"opus-251","category":"ディープラーニングの要素技術","term":"One-shot","summary":"1つの例だけを手がかりに、新しいクラスやタスクへ対応する学習・推論の設定。","exam":"顔認証や少量データ学習で、Few-shotとの違いとして問われやすい。","difference":"Few-shotは少数例、One-shotは特に1例だけを使う。","mnemonic":"一例で見抜く","field":"4/5","priority":"A"},{"id":"opus-252","category":"ディープラーニングの要素技術","term":"Open Pose","summary":"画像中の人物の関節点や骨格を推定し、姿勢を認識するための深層学習手法。","exam":"姿勢推定の代表例として、物体検出やセグメンテーションとは異なるタスクで問われやすい。","difference":"物体検出は枠を出すが、Open Poseは人の関節位置を推定する。","mnemonic":"人の骨格を読む","field":"4/5","priority":"A"},{"id":"opus-253","category":"ディープラーニングの要素技術","term":"OpenAI Five","summary":"OpenAIが開発したDota 2向けAI。複数エージェントの協調を強化学習で学習した事例。","exam":"マルチエージェント強化学習の応用例として、ゲームAIの発展で問われやすい。","difference":"AlphaStarはStarCraft II、OpenAI FiveはDota 2を対象にした。","mnemonic":"Dotaの協調AI","field":"4/5","priority":"A"},{"id":"opus-254","category":"ディープラーニングの要素技術","term":"PPO","summary":"方策を一度に大きく変えすぎないよう制限し、安定して方策を更新する強化学習手法。","exam":"方策勾配法の代表的改良として、RLHFでも使われることがある点が問われやすい。","difference":"REINFORCEは基本的な方策勾配、PPOは更新幅を抑えて安定化する。","mnemonic":"方策を慎重更新","field":"4/5","priority":"A"},{"id":"opus-255","category":"ディープラーニングの要素技術","term":"PSPNet","summary":"画像全体と局所情報を組み合わせるピラミッドプーリングを用いたセマンティックセグメンテーション手法。","exam":"セグメンテーションで広い文脈情報を使うモデルとして問われやすい。","difference":"FCNは基本的な画素分類、PSPNetは複数スケールの文脈をより強く使う。","mnemonic":"文脈を階層で見る","field":"4/5","priority":"A"},{"id":"opus-256","category":"ディープラーニングの要素技術","term":"PaLM","summary":"Googleが発表した大規模言語モデル。大量データと大規模パラメータで多様な言語タスクを扱う。","exam":"大規模言語モデルの例として、Transformer系モデルや生成AIの文脈で問われやすい。","difference":"BERTは理解系の事前学習で知られ、PaLMは生成も含む大規模言語モデルとして扱われる。","mnemonic":"巨大な言語モデル","field":"4/5","priority":"A"},{"id":"opus-257","category":"ディープラーニングの要素技術","term":"Permutation Importance","summary":"特徴量をランダムに並べ替え、予測性能がどれだけ下がるかで重要度を測る手法。","exam":"特徴量重要度を調べるモデル非依存の説明手法として問われやすい。","difference":"SHAPは各予測への貢献も見られ、Permutation Importanceは性能低下で重要度を見る。","mnemonic":"崩して重要度測定","field":"4/5","priority":"A"},{"id":"opus-258","category":"ディープラーニングの要素技術","term":"Pix2Pix","summary":"入力画像と正解画像のペアを使い、線画から写真のような対応画像変換を学習するGAN。","exam":"画像変換モデルとして、CycleGANとの教師データの違いが問われやすい。","difference":"CycleGANは対応ペア不要、Pix2Pixは入力と出力の対応ペアが必要。","mnemonic":"ペアで画像変換","field":"4/5","priority":"A"},{"id":"opus-259","category":"ディープラーニングの要素技術","term":"RAG（検索拡張生成）","summary":"外部の文書を検索して取り込み、それを根拠に回答を生成する仕組み。","exam":"ハルシネーション対策や最新情報への対応として頻出。","difference":"ファインチューニングは知識をモデルに埋め込むが、RAGは外から都度参照する。","mnemonic":"調べてから答える","field":"4/5","priority":"A"},{"id":"opus-260","category":"ディープラーニングの要素技術","term":"RLHF","summary":"人間の評価や好みを報酬モデルに反映し、AIの出力を望ましい方向へ調整する強化学習手法。","exam":"大規模言語モデルの調整方法として、人間のフィードバック利用が問われやすい。","difference":"通常の強化学習は環境報酬中心、RLHFは人間の選好を報酬に使う。","mnemonic":"人の好みで調整","field":"4/5","priority":"A"},{"id":"opus-261","category":"ディープラーニングの要素技術","term":"Rainbow","summary":"DQNの複数の改良手法を組み合わせ、性能を高めた深層強化学習アルゴリズム。","exam":"DQNの発展形として、ダブルDQNやデュエリングネットワークなどの統合で問われやすい。","difference":"DQN単体に対し、Rainbowは複数の改善アイデアをまとめたもの。","mnemonic":"DQN改良全部盛り","field":"4/5","priority":"A"},{"id":"opus-262","category":"ディープラーニングの要素技術","term":"RandAugument","summary":"複数の画像変換からランダムに選び、強さも調整してデータ拡張を自動化する手法。","exam":"自動データ拡張の一種として、手作業の拡張設計を減らす方法で問われやすい。","difference":"Random Flipなど単一変換と異なり、複数の変換をランダムに組み合わせる。","mnemonic":"拡張を自動くじ","field":"4/5","priority":"A"},{"id":"opus-263","category":"ディープラーニングの要素技術","term":"Random Erasing","summary":"画像のランダムな領域を消して学習し、一部が隠れても認識できるようにするデータ拡張。","exam":"画像認識の過学習対策として、Cutoutと似た隠す系の手法として問われやすい。","difference":"Cutoutと近いが、Random Erasingは位置や大きさをランダムに消す点が強調される。","mnemonic":"ランダムに消す","field":"4/5","priority":"A"},{"id":"opus-264","category":"ディープラーニングの要素技術","term":"Random Flip","summary":"画像をランダムに左右または上下反転するデータ拡張。向きの違いに強いモデルを作る。","exam":"画像データ拡張の基本として、反転しても意味が変わらない場面で有効と問われやすい。","difference":"Rotateは回転、Random Flipは鏡映のように反転する。","mnemonic":"ランダム反転","field":"4/5","priority":"A"},{"id":"opus-265","category":"ディープラーニングの要素技術","term":"ResNet","summary":"入力を後の層へ足し合わせる残差接続を使い、非常に深いCNNでも学習しやすくしたモデル。","exam":"残差接続により勾配消失を抑え、深いネットワークを実現した例として問われやすい。","difference":"通常のCNNより、層を飛び越えるショートカット接続を持つ点が特徴。","mnemonic":"残差で深くする","field":"4/5","priority":"A"},{"id":"opus-266","category":"ディープラーニングの要素技術","term":"Rotate","summary":"画像を一定角度またはランダム角度で回転させるデータ拡張。向きの変化に強くする。","exam":"画像認識で、回転しても同じ対象と見なせる場合の拡張として問われやすい。","difference":"Random Flipは反転、Rotateは角度を変えて回す。","mnemonic":"回して増やす","field":"4/5","priority":"A"},{"id":"opus-267","category":"ディープラーニングの要素技術","term":"SENet","summary":"重要なチャンネルを強調し、不要なチャンネルを抑えるSqueeze-and-Excitation機構を持つCNN。","exam":"チャンネル方向のAttentionに近い仕組みとして、画像分類モデルの改良で問われやすい。","difference":"通常のCNNが特徴を一様に扱うのに対し、SENetはチャンネルの重要度を調整する。","mnemonic":"特徴チャンネル選別","field":"4/5","priority":"A"},{"id":"opus-268","category":"ディープラーニングの要素技術","term":"SHAP","summary":"協力ゲーム理論の考え方を使い、各特徴量が予測にどれだけ貢献したかを配分する説明手法。","exam":"XAIの代表手法として、特徴量ごとの寄与を定量化する点が問われやすい。","difference":"LIMEは局所近似、SHAPはシャープレイ値に基づき貢献度を配分する。","mnemonic":"特徴の貢献配分","field":"4/5","priority":"A"},{"id":"opus-269","category":"ディープラーニングの要素技術","term":"SSD","summary":"複数スケールの特徴マップから物体の位置とクラスを一度に予測する一段階物体検出手法。","exam":"YOLOと同じ一段階検出として、高速な物体検出モデルの文脈で問われやすい。","difference":"Faster R-CNNは二段階検出、SSDは候補生成を分けず一度に検出する。","mnemonic":"一発で複数検出","field":"4/5","priority":"A"},{"id":"opus-270","category":"ディープラーニングの要素技術","term":"SegNet","summary":"エンコーダで特徴を圧縮し、デコーダで解像度を戻して画素単位分類を行うセグメンテーションモデル。","exam":"セマンティックセグメンテーションのモデルとして、エンコーダ・デコーダ構造で問われやすい。","difference":"U-Netはスキップ接続で詳細情報を戻し、SegNetは主にプーリング情報を使って復元する。","mnemonic":"圧縮して戻す","field":"4/5","priority":"A"},{"id":"opus-271","category":"ディープラーニングの要素技術","term":"Self-Attention","summary":"同じ系列内の各要素同士が互いに注目し、文脈に応じた表現を作るAttention。","exam":"Transformerの基本機構として、RNNなしで系列の依存関係を扱う点が問われやすい。","difference":"Source-Target Attentionは別系列間、Self-Attentionは同じ系列内で注目する。","mnemonic":"自分同士で注目","field":"4/5","priority":"A"},{"id":"opus-272","category":"ディープラーニングの要素技術","term":"Seq2Seq","summary":"入力系列を読み取り、別の出力系列を生成するモデル。機械翻訳や要約などで使われる。","exam":"エンコーダ・デコーダ構造として、機械翻訳やAttentionとの関係で問われやすい。","difference":"RNN単体は系列処理の部品、Seq2Seqは入力系列から出力系列を作る枠組み。","mnemonic":"系列から系列へ","field":"4/5","priority":"A"},{"id":"opus-273","category":"ディープラーニングの要素技術","term":"Source-Target Attention","summary":"出力側が入力側のどの部分を見るべきかを重みづけする、エンコーダ・デコーダ間のAttention。","exam":"翻訳などで、デコーダが入力文の重要部分を参照する仕組みとして問われやすい。","difference":"Self-Attentionは同じ系列内、Source-Target Attentionは入力系列と出力系列の間を見る。","mnemonic":"入力を見て出力","field":"4/5","priority":"A"},{"id":"opus-274","category":"ディープラーニングの要素技術","term":"TF-IDF","summary":"単語の出現頻度と文書集合内での珍しさを組み合わせ、重要な単語に高い重みを与える指標。","exam":"検索や文書分類の古典的特徴量として、BoWとの違いが問われやすい。","difference":"BoWは出現回数中心、TF-IDFは珍しく重要そうな単語を強く評価する。","mnemonic":"珍しい語を重視","field":"4/5","priority":"A"},{"id":"opus-275","category":"ディープラーニングの要素技術","term":"Text-To-Image","summary":"テキスト入力をもとに、内容に合う画像を生成するタスク。DALL-Eや拡散モデルが代表例。","exam":"生成AIの応用として、画像生成やマルチモーダルモデルとの関係が問われやすい。","difference":"Image Captioningは画像から文章、Text-To-Imageは文章から画像を作る。","mnemonic":"文章から画像","field":"4/5","priority":"A"},{"id":"opus-276","category":"ディープラーニングの要素技術","term":"Transformer","summary":"Attentionを中心に構成され、RNNを使わず系列全体を並列的に処理できるモデル。","exam":"自然言語処理や生成AIの基盤として、Self-Attentionと位置エンコーディングが問われやすい。","difference":"RNNは順番に処理するが、TransformerはAttentionで系列全体を並列に扱う。","mnemonic":"注意で読む模型","field":"4/5","priority":"A"},{"id":"opus-277","category":"ディープラーニングの要素技術","term":"U-Net","summary":"エンコーダ・デコーダ構造にスキップ接続を持ち、医用画像などのセグメンテーションで使われるモデル。","exam":"セグメンテーションの代表モデルとして、左右対称構造とスキップ接続が問われやすい。","difference":"SegNetより、エンコーダ側の特徴をデコーダへ直接渡す点が強調される。","mnemonic":"U字で領域分け","field":"4/5","priority":"A"},{"id":"opus-278","category":"ディープラーニングの要素技術","term":"Unified-IO","summary":"画像・言語など複数の入出力形式を統一的に扱い、多様なタスクを同じ枠組みで解くモデル。","exam":"マルチモーダル・マルチタスクの基盤モデル例として、統一的な入出力処理が問われやすい。","difference":"単一タスクモデルと違い、複数のモダリティとタスクをまとめて扱う点が特徴。","mnemonic":"全部まとめて入出力","field":"4/5","priority":"A"},{"id":"opus-279","category":"ディープラーニングの要素技術","term":"VGG","summary":"小さな3×3畳み込みを重ね、単純で深い構造により高精度を実現したCNN。","exam":"画像分類モデルの歴史で、AlexNet後の深いCNNとして問われやすい。","difference":"GoogLeNetは複数畳み込みを並列に使い、VGGは単純な畳み込みを深く重ねる。","mnemonic":"小窓を深く積む","field":"4/5","priority":"A"},{"id":"opus-280","category":"ディープラーニングの要素技術","term":"VQ-VAE・ info VAE・β-VAE","summary":"VAEの派生モデル群。離散表現、情報量の調整、潜在変数の分離などを目的に改良される。","exam":"VAEの発展形として、生成モデルや潜在表現の学習方法の違いが問われやすい。","difference":"VQ-VAEは離散表現、β-VAEは潜在表現の分離、info VAEは情報量制御を重視する。","mnemonic":"VAEの派生たち","field":"4/5","priority":"A"},{"id":"opus-281","category":"ディープラーニングの要素技術","term":"Vision Transformer","summary":"画像を小さなパッチに分け、TransformerのSelf-Attentionで画像認識を行うモデル。","exam":"CNN以外の画像認識モデルとして、パッチ分割とAttention利用が問われやすい。","difference":"CNNは畳み込みで局所特徴を捉え、Vision Transformerはパッチ間の関係をAttentionで見る。","mnemonic":"画像をパッチで読む","field":"4/5","priority":"A"},{"id":"opus-282","category":"ディープラーニングの要素技術","term":"Visual Question Answering","summary":"画像と質問文を入力し、画像内容に基づいて答えを返す視覚と言語の複合タスク。","exam":"マルチモーダルAIの代表タスクとして、画像認識と自然言語処理の統合で問われやすい。","difference":"Image Captioningは説明文生成、VQAは質問に対する答えを出す。","mnemonic":"画像に質問する","field":"4/5","priority":"A"},{"id":"opus-283","category":"ディープラーニングの要素技術","term":"WaveNet","summary":"音声波形を直接生成する深層生成モデル。自然な音声合成を実現したモデルとして知られる。","exam":"音声合成の代表的深層学習モデルとして、時系列生成や畳み込みとの関係で問われやすい。","difference":"従来の音声合成は特徴量設計中心、WaveNetは波形を生成する深層モデル。","mnemonic":"波形を直接生成","field":"4/5","priority":"A"},{"id":"opus-284","category":"ディープラーニングの要素技術","term":"Wide ResNet","summary":"ResNetの層を極端に深くする代わりに、チャンネル幅を広げて性能向上を狙うモデル。","exam":"ResNetの派生として、深さだけでなく幅を広げる設計が問われやすい。","difference":"ResNetは残差接続が中心、Wide ResNetはその構造を幅広にした派生。","mnemonic":"深さより幅","field":"4/5","priority":"A"},{"id":"opus-285","category":"ディープラーニングの要素技術","term":"YOLO","summary":"画像全体を一度に見て物体の位置とクラスを予測する、高速な一段階物体検出手法。","exam":"リアルタイム物体検出の代表として、Faster R-CNNやSSDとの違いが問われやすい。","difference":"Faster R-CNNは二段階で高精度寄り、YOLOは一段階で高速検出を重視する。","mnemonic":"一度で見つける","field":"4/5","priority":"A"},{"id":"opus-286","category":"ディープラーニングの要素技術","term":"Zero-shot","summary":"そのタスクの具体例を与えず、事前学習で得た知識だけで新しいタスクへ対応する設定。","exam":"基盤モデルやCLIP・LLMの汎化能力として、Few-shotとの違いが問われやすい。","difference":"Few-shotは少数例を与えるが、Zero-shotは例を与えずに解かせる。","mnemonic":"例なしで解く","field":"4/5","priority":"A"},{"id":"opus-287","category":"ディープラーニングの要素技術","term":"fastText","summary":"単語を文字n-gramの組み合わせで表し、未知語や表記ゆれにも対応しやすい単語表現手法。","exam":"word2vecの発展として、単語内部の文字情報を使う点が問われやすい。","difference":"word2vecは単語単位中心、fastTextは単語を部分文字列に分けて扱う。","mnemonic":"文字片も見る","field":"4/5","priority":"A"},{"id":"opus-288","category":"ディープラーニングの要素技術","term":"n-gram","summary":"連続するn個の文字や単語の並びを単位として扱う方法。語順の一部を特徴として残せる。","exam":"BoWより語順情報を少し扱える古典的特徴表現として問われやすい。","difference":"BoWは単語の袋、n-gramは連続した並びを特徴にする。","mnemonic":"n個ずつ読む","field":"4/5","priority":"A"},{"id":"opus-289","category":"ディープラーニングの要素技術","term":"noising","summary":"入力データにノイズを加え、多少の乱れがあっても正しく処理できるようにするデータ拡張。","exam":"画像・音声・言語などの頑健性向上や、ノイズ除去型学習と関連して問われやすい。","difference":"Dropoutはニューロンを無効化し、noisingは入力データ自体にノイズを加える。","mnemonic":"ノイズで鍛える","field":"4/5","priority":"A"},{"id":"opus-290","category":"ディープラーニングの要素技術","term":"paraphrasing","summary":"文章を意味を保ったまま別表現に言い換え、自然言語処理の学習データを増やす方法。","exam":"NLPのデータ拡張として、同じ意味の多様な表現に対応する方法で問われやすい。","difference":"noisingはノイズを加える方法、paraphrasingは意味を保って言い換える方法。","mnemonic":"意味そのまま言換","field":"4/5","priority":"A"},{"id":"opus-291","category":"ディープラーニングの要素技術","term":"sim2real","summary":"シミュレーションで学習したモデルを、現実世界のロボットや環境へ移す考え方。","exam":"ロボット強化学習で、現実データ収集の難しさを補う方法として問われやすい。","difference":"ドメインランダマイゼーションは、sim2realのずれを減らす具体的工夫。","mnemonic":"仮想から現実へ","field":"4/5","priority":"A"},{"id":"opus-292","category":"ディープラーニングの要素技術","term":"word2vec","summary":"単語を意味の近さが反映されたベクトルで表す手法。CBOWやSkip-gramで学習される。","exam":"単語分散表現の代表として、CBOW・Skip-gram・fastTextとの関係が問われやすい。","difference":"BoWは文書の単語数表現、word2vecは単語の意味をベクトルで表す。","mnemonic":"意味をベクトル化","field":"4/5","priority":"A"},{"id":"opus-293","category":"ディープラーニングの要素技術","term":"アルファスター(AlphaStar)","summary":"DeepMindが開発したStarCraft II向けAI。複雑なリアルタイム戦略ゲームを強化学習で扱った。","exam":"ゲームAIやマルチエージェント的な意思決定の応用例として問われやすい。","difference":"AlphaGoは囲碁、AlphaStarはStarCraft IIを対象にした。","mnemonic":"星戦略のAI","field":"4/5","priority":"A"},{"id":"opus-294","category":"ディープラーニングの要素技術","term":"インスタンスセグメンテーション","summary":"画像中の物体を個体ごとに区別し、それぞれの領域を画素単位で分けるタスク。","exam":"Mask R-CNNなどと関連し、物体検出とセグメンテーションの組み合わせとして問われやすい。","difference":"セマンティックセグメンテーションは同じクラスの個体を区別しない。","mnemonic":"個体ごと塗分け","field":"4/5","priority":"A"},{"id":"opus-295","category":"ディープラーニングの要素技術","term":"インスタンス正規化","summary":"画像1枚ごと、チャンネルごとに平均と分散をそろえる正規化手法。画像生成やスタイル変換で使われる。","exam":"画像変換や生成モデルで、バッチに依存しない正規化として問われやすい。","difference":"レイヤー正規化は特徴全体、インスタンス正規化は画像ごとのチャンネル単位で整える。","mnemonic":"画像ごと整える","field":"4/5","priority":"A"},{"id":"opus-296","category":"ディープラーニングの要素技術","term":"エッジ AI","summary":"クラウドではなく端末やセンサ近くでAI推論を行う仕組み。低遅延や通信削減に向く。","exam":"モデル圧縮や量子化と関連し、端末上でAIを動かす文脈で問われやすい。","difference":"クラウドAIはサーバ処理、エッジAIは端末側で処理する。","mnemonic":"端末でAI実行","field":"4/5","priority":"A"},{"id":"opus-297","category":"ディープラーニングの要素技術","term":"エルマンネットワーク","summary":"隠れ層の出力を次時刻の入力に戻す構造を持つ、基本的な再帰型ニューラルネットワーク。","exam":"RNNの初期的な構造として、ジョルダンネットワークとの違いが問われやすい。","difference":"ジョルダンネットワークは出力層を戻し、エルマンネットワークは隠れ層を戻す。","mnemonic":"隠れ層を戻す","field":"4/5","priority":"A"},{"id":"opus-298","category":"ディープラーニングの要素技術","term":"オフライン強化学習","summary":"事前に集めた行動データだけを使い、環境と新たに試行錯誤せず方策を学ぶ強化学習。","exam":"実環境で試行錯誤が危険・高コストな場合の手法として問われやすい。","difference":"通常の強化学習は環境と相互作用し、オフライン強化学習は既存データから学ぶ。","mnemonic":"記録だけで学習","field":"4/5","priority":"A"},{"id":"opus-299","category":"ディープラーニングの要素技術","term":"カーネル","summary":"畳み込みで画像上を移動しながら特徴を抽出する小さな重み行列。フィルタとも呼ばれる。","exam":"CNNの基本要素として、フィルタサイズや特徴マップとの関係で問われやすい。","difference":"機械学習のカーネル関数とは別で、CNNでは小さな重み行列を指す。","mnemonic":"特徴を抜く窓","field":"4/5","priority":"A"},{"id":"opus-300","category":"ディープラーニングの要素技術","term":"キー","summary":"Attentionで各要素が持つ照合用の表現。クエリと比較され、どこに注目するかを決める材料になる。","exam":"クエリ・バリューとセットで、Attentionの重み計算に使う要素として問われやすい。","difference":"クエリは探す条件、キーは照合される目印、バリューは取り出される中身。","mnemonic":"照合用の目印","field":"4/5","priority":"A"},{"id":"opus-301","category":"ディープラーニングの要素技術","term":"クエリ","summary":"Attentionで何を探したいかを表す表現。キーとの類似度から注目度を計算する。","exam":"キー・バリューとセットで、Attentionの重み計算の入口として問われやすい。","difference":"キーは照合される目印、クエリは照合するための問い合わせ。","mnemonic":"探すための問い","field":"4/5","priority":"A"},{"id":"opus-302","category":"ディープラーニングの要素技術","term":"グループ正規化","summary":"特徴チャンネルを複数グループに分け、各グループ内で平均と分散をそろえる正規化手法。","exam":"バッチサイズが小さい場合でも安定しやすい正規化として問われやすい。","difference":"バッチ正規化はバッチ方向、グループ正規化はチャンネルをグループ化して正規化する。","mnemonic":"チャンネルを班分け","field":"4/5","priority":"A"},{"id":"opus-303","category":"ディープラーニングの要素技術","term":"グローバルアベレージプーリング (GAP)","summary":"特徴マップ全体の平均を取り、各チャンネルを1つの値にまとめるプーリング手法。","exam":"CNNの全結合層削減や、位置に依存しにくい表現として問われやすい。","difference":"平均値プーリングは局所領域、GAPは特徴マップ全体を平均する。","mnemonic":"全体を平均圧縮","field":"4/5","priority":"A"},{"id":"opus-304","category":"ディープラーニングの要素技術","term":"ゲート機構","summary":"情報を通すか忘れるかを制御する仕組み。LSTMやGRUで長期依存を扱いやすくする。","exam":"LSTM・GRUの特徴として、勾配消失を抑え情報保持を制御する点が問われやすい。","difference":"単純RNNは状態をそのまま更新し、ゲート機構は情報の取捨選択を行う。","mnemonic":"情報の開閉弁","field":"4/5","priority":"A"},{"id":"opus-305","category":"ディープラーニングの要素技術","term":"コンテキストウィンドウ","summary":"モデルが一度に扱える入力トークンの上限。長いほど長文を扱える。","exam":"長文処理の制約や、RAGが必要になる理由として問われやすい。","difference":"パラメータ数はモデルの大きさで、扱える文の長さとは別の指標。","mnemonic":"一度に読める量","field":"4/5","priority":"A"},{"id":"opus-306","category":"ディープラーニングの要素技術","term":"ジョルダンネットワーク","summary":"出力層の情報を次時刻の入力に戻す構造を持つ、初期の再帰型ニューラルネットワーク。","exam":"RNNの古典的構造として、エルマンネットワークとの違いが問われやすい。","difference":"エルマンネットワークは隠れ層を戻し、ジョルダンネットワークは出力層を戻す。","mnemonic":"出力層を戻す","field":"4/5","priority":"A"},{"id":"opus-307","category":"ディープラーニングの要素技術","term":"スキップグラム","summary":"中心単語から周辺単語を予測するword2vecの学習方式。単語の意味表現を学ぶ。","exam":"word2vecの代表方式として、CBOWとの入力と出力の向きの違いが問われやすい。","difference":"CBOWは周辺語から中心語、スキップグラムは中心語から周辺語を予測する。","mnemonic":"中心から周辺へ","field":"4/5","priority":"A"},{"id":"opus-308","category":"ディープラーニングの要素技術","term":"スケーリング則","summary":"モデルサイズ・データ量・計算量を増やすほど性能が向上するという経験則。","exam":"大規模化が進んだ理由や、創発的能力の議論と結びつく。","difference":"ムーアの法則はハードウェアの話で、スケーリング則はモデル性能の話。","mnemonic":"大きくすれば伸びる","field":"4/5","priority":"A"},{"id":"opus-309","category":"ディープラーニングの要素技術","term":"ストライド","summary":"畳み込みやプーリングで、フィルタを何画素ずつずらして適用するかを表す間隔。","exam":"出力サイズを変える要因として、パディングやカーネルサイズと一緒に問われやすい。","difference":"パディングは周囲を埋める処理、ストライドは移動幅を決める設定。","mnemonic":"窓の歩幅","field":"4/5","priority":"A"},{"id":"opus-310","category":"ディープラーニングの要素技術","term":"スペクトル包絡","summary":"音声スペクトルの大まかな形を表す特徴。声道の形や母音らしさを反映しやすい。","exam":"音声分析で、フォルマントや声質の特徴と関連して問われやすい。","difference":"フォルマントは包絡の山にあたる共鳴周波数、スペクトル包絡は全体の形。","mnemonic":"周波数の輪郭","field":"4/5","priority":"A"},{"id":"opus-311","category":"ディープラーニングの要素技術","term":"セマンティックセグメンテーション","summary":"画像の各画素に、道路・人・車などのクラスラベルを割り当てるタスク。","exam":"FCN・DeepLab・U-Netなどと関連し、画素単位分類として問われやすい。","difference":"インスタンスセグメンテーションと違い、同じクラスの個体同士は区別しない。","mnemonic":"画素ごと分類","field":"4/5","priority":"A"},{"id":"opus-312","category":"ディープラーニングの要素技術","term":"ダブル DQN","summary":"DQNのQ値過大評価を抑えるため、行動選択と価値評価を別のネットワークで分ける手法。","exam":"DQNの改良として、過大評価バイアスを減らす方法で問われやすい。","difference":"DQNは同じ推定で選択と評価を行い、ダブルDQNはその役割を分ける。","mnemonic":"Q値の盛りすぎ防止","field":"4/5","priority":"A"},{"id":"opus-313","category":"ディープラーニングの要素技術","term":"デュエリングネットワーク","summary":"状態価値と行動ごとの優位性を分けて推定し、行動価値をより効率よく学ぶDQN改良構造。","exam":"DQN改良の一つとして、状態価値とアドバンテージを分ける点が問われやすい。","difference":"通常DQNはQ値を直接出し、デュエリングは状態の良さと行動差を分ける。","mnemonic":"状態価値と行動差","field":"4/5","priority":"A"},{"id":"opus-314","category":"ディープラーニングの要素技術","term":"トークン","summary":"文章を分割した処理単位。単語より細かい部分単語になることが多い。","exam":"課金単位やコンテキスト長の単位として問われやすい。","difference":"形態素は言語学的な最小単位で、トークンはモデル都合の分割単位。","mnemonic":"処理の最小単位","field":"4/5","priority":"A"},{"id":"opus-315","category":"ディープラーニングの要素技術","term":"ドメインランダマイゼーション","summary":"シミュレーションの見た目や物理条件をランダム化し、現実との差に強いモデルを学習する方法。","exam":"sim2realで現実移行を成功させる工夫として、ロボット学習で問われやすい。","difference":"sim2realは仮想から現実へ移す考え方、これは訓練環境を多様化する方法。","mnemonic":"仮想環境を乱す","field":"4/5","priority":"A"},{"id":"opus-316","category":"ディープラーニングの要素技術","term":"ノイジーネットワーク","summary":"ネットワークの重みにノイズを加え、行動選択の探索を学習可能にする強化学習手法。","exam":"DQN改良やRainbowの要素として、探索をランダム行動以外で行う方法として問われやすい。","difference":"ε-greedyは行動をランダム化し、ノイジーネットワークは重みにノイズを入れる。","mnemonic":"重みにノイズ探索","field":"4/5","priority":"A"},{"id":"opus-317","category":"ディープラーニングの要素技術","term":"ハルシネーション","summary":"もっともらしいが事実と異なる内容を生成してしまう現象。","exam":"生成AIのリスクや、RAG・人間の確認などの対策とセットで問われる。","difference":"バイアスは偏り、ハルシネーションは事実でない生成という別の問題。","mnemonic":"もっともらしい嘘","field":"4/5","priority":"A"},{"id":"opus-318","category":"ディープラーニングの要素技術","term":"バッチ正規化","summary":"ミニバッチ内のデータを使って各層の入力分布をそろえ、学習を安定・高速化する手法。","exam":"深いネットワークの学習安定化や、勾配消失対策に近い工夫として問われやすい。","difference":"レイヤー正規化は各データ内で正規化し、バッチ正規化はミニバッチ単位で正規化する。","mnemonic":"バッチで整える","field":"4/5","priority":"A"},{"id":"opus-319","category":"ディープラーニングの要素技術","term":"バリュー","summary":"Attentionで重みづけして実際に取り出される情報。キーとの照合結果に応じて合成される。","exam":"クエリ・キーとセットで、Attentionの出力に使われる中身として問われやすい。","difference":"キーは照合用、バリューは注目度に応じて取り出す情報。","mnemonic":"取り出す中身","field":"4/5","priority":"A"},{"id":"opus-320","category":"ディープラーニングの要素技術","term":"パディング","summary":"入力データの周囲に0などを追加し、畳み込み後のサイズ調整や端の情報保持を行う処理。","exam":"CNNの出力サイズ調整として、ストライドやカーネルサイズとセットで問われやすい。","difference":"ストライドはフィルタの移動幅、パディングは入力の周囲を埋める処理。","mnemonic":"端を埋める","field":"4/5","priority":"A"},{"id":"opus-321","category":"ディープラーニングの要素技術","term":"パノプティックセグメンテーション","summary":"背景を含む全画素を分類し、数えられる物体は個体ごとにも区別する統合的な領域分割。","exam":"セマンティックとインスタンスの統合タスクとして、近年の画像認識で問われやすい。","difference":"セマンティックはクラス単位、インスタンスは個体単位、パノプティックは両方を扱う。","mnemonic":"全部を個体込み分類","field":"4/5","priority":"A"},{"id":"opus-322","category":"ディープラーニングの要素技術","term":"パルス符号変調器(PCM)","summary":"音声などのアナログ信号を標本化・量子化し、デジタル値として表す方式。","exam":"音声のデジタル化で、A-D変換やサンプリングと関連して問われやすい。","difference":"A-D変換は変換処理、PCMは標本化と量子化でデジタル表現する方式。","mnemonic":"波を数字列に","field":"4/5","priority":"A"},{"id":"opus-323","category":"ディープラーニングの要素技術","term":"ファインチューニング","summary":"事前学習済みモデルを、特定タスクのデータで追加学習して調整すること。","exam":"転移学習との違いや、事前学習との順序で問われやすい。","difference":"転移学習は特徴抽出部を固定することが多く、ファインチューニングは重みを更新する。","mnemonic":"追加学習で仕上げ","field":"4/5","priority":"A"},{"id":"opus-324","category":"ディープラーニングの要素技術","term":"フィルタ","summary":"画像のエッジや模様など特定の特徴に反応する小さな重み行列。畳み込みで使われる。","exam":"CNNで特徴抽出を行う部品として、カーネルや特徴マップとの関係が問われやすい。","difference":"CNNではカーネルとほぼ同じ意味で使われ、特徴マップを作る側の重み。","mnemonic":"特徴検出器","field":"4/5","priority":"A"},{"id":"opus-325","category":"ディープラーニングの要素技術","term":"フォルマント","summary":"声道の共鳴により強く現れる周波数成分。母音の違いや声質の特徴に関わる。","exam":"音声特徴の基礎として、フォルマント周波数やスペクトル包絡と問われやすい。","difference":"フォルマント周波数は、フォルマントが現れる具体的な周波数を指す。","mnemonic":"声の共鳴の山","field":"4/5","priority":"A"},{"id":"opus-326","category":"ディープラーニングの要素技術","term":"フォルマント周波数","summary":"フォルマントが現れる周波数。第1・第2フォルマントなどが母音識別の手がかりになる。","exam":"音声認識や音声分析で、母音や声道特性を表す指標として問われやすい。","difference":"フォルマントは共鳴成分そのもの、フォルマント周波数はその位置を表す数値。","mnemonic":"共鳴の位置","field":"4/5","priority":"A"},{"id":"opus-327","category":"ディープラーニングの要素技術","term":"プルーニング","summary":"重要度の低い重みやニューロンを削除し、モデルを軽くする圧縮手法。","exam":"モデル圧縮やエッジAIで、精度を保ちながら計算量を減らす方法として問われやすい。","difference":"量子化は数値精度を下げ、プルーニングは不要な接続や重みを削る。","mnemonic":"不要枝を刈る","field":"4/5","priority":"A"},{"id":"opus-328","category":"ディープラーニングの要素技術","term":"プロンプトエンジニアリング","summary":"大規模言語モデルへの指示文を工夫し、望む出力を引き出す技術。","exam":"Few-shotやChain-of-Thoughtとセットで、応用問題として問われやすい。","difference":"ファインチューニングはモデル自体を更新するが、こちらは入力文だけで調整する。","mnemonic":"指示文の工夫","field":"4/5","priority":"A"},{"id":"opus-329","category":"ディープラーニングの要素技術","term":"マルチエージェント強化学習(MARL)","summary":"複数のエージェントが同じ環境で協力や競争をしながら学習する強化学習。","exam":"ゲームAIや群制御で、協調・競争・非定常性の難しさとして問われやすい。","difference":"単一エージェント強化学習は1主体、MARLは複数主体の相互作用を扱う。","mnemonic":"複数主体で学ぶ","field":"4/5","priority":"A"},{"id":"opus-330","category":"ディープラーニングの要素技術","term":"マルチタスク学習","summary":"複数の関連タスクを同時に学習し、共通する特徴を共有して性能向上を狙う学習方法。","exam":"基盤モデルやマルチモーダルモデルで、複数タスクをまとめて扱う考え方として問われやすい。","difference":"転移学習は先に学んだ知識を別タスクへ使い、マルチタスク学習は同時に複数タスクを学ぶ。","mnemonic":"複数仕事を同時学習","field":"4/5","priority":"A"},{"id":"opus-331","category":"ディープラーニングの要素技術","term":"マルチモーダル","summary":"画像・音声・テキストなど複数種類の情報をまとめて扱うこと。","exam":"CLIPやGPT-4系の特徴として、単一モダリティとの対比で問われる。","difference":"マルチタスク学習は複数の課題を解く話で、扱う情報の種類とは別。","mnemonic":"複数の情報を扱う","field":"4/5","priority":"A"},{"id":"opus-332","category":"ディープラーニングの要素技術","term":"メル周波数ケプストラム係数 (MFCC)","summary":"人間の聴覚特性に近いメル尺度を使い、音声の特徴を少数の係数で表す特徴量。","exam":"音声認識の代表的特徴量として、FFTやメル尺度との関係が問われやすい。","difference":"メル尺度は周波数の尺度、MFCCはその尺度を使って得る音声特徴量。","mnemonic":"聴覚寄り特徴量","field":"4/5","priority":"A"},{"id":"opus-333","category":"ディープラーニングの要素技術","term":"メル尺度","summary":"人間の音の高さの感じ方に近づけた周波数尺度。高周波ほど感覚上の差が圧縮される。","exam":"MFCCで使われる尺度として、人間の聴覚特性を反映する点が問われやすい。","difference":"Hzは物理的な周波数、メル尺度は人の聞こえ方に合わせた尺度。","mnemonic":"人の耳の尺度","field":"4/5","priority":"A"},{"id":"opus-334","category":"ディープラーニングの要素技術","term":"モデル圧縮","summary":"モデルの精度をなるべく保ちながら、サイズや計算量を小さくする技術の総称。","exam":"エッジAIや高速推論で、蒸留・量子化・プルーニングの総称として問われやすい。","difference":"蒸留や量子化は具体手法、モデル圧縮はそれらを含む広い概念。","mnemonic":"小さく速くする","field":"4/5","priority":"A"},{"id":"opus-335","category":"ディープラーニングの要素技術","term":"リカレントニューラルネットワーク (RNN)","summary":"過去の状態を内部に持ち、系列データの順序や文脈を扱うニューラルネットワーク。","exam":"時系列データや自然言語処理で使われ、勾配消失問題との関係で問われやすい。","difference":"CNNは空間的特徴に強く、RNNは時間的・順序的な依存関係に強い。","mnemonic":"過去を持つ網","field":"4/5","priority":"A"},{"id":"opus-336","category":"ディープラーニングの要素技術","term":"レイヤー正規化","summary":"1つのデータ内の特徴量方向で平均と分散をそろえる正規化手法。系列モデルで使われやすい。","exam":"TransformerやRNNなどで使われる正規化として、バッチ正規化との違いが問われやすい。","difference":"バッチ正規化はバッチ全体、レイヤー正規化は各サンプル内の特徴量を正規化する。","mnemonic":"特徴を横に整える","field":"4/5","priority":"A"},{"id":"opus-337","category":"ディープラーニングの要素技術","term":"ワンホットベクトル","summary":"語彙数分の長さを持ち、該当単語だけ1で他は0にする疎なベクトル表現。","exam":"単語表現の基本として、分散表現や単語埋め込みとの違いが問われやすい。","difference":"単語埋め込みは密ベクトル、ワンホットは意味の近さを直接表しにくい。","mnemonic":"一つだけ1","field":"4/5","priority":"A"},{"id":"opus-338","category":"ディープラーニングの要素技術","term":"一般物体認識","summary":"画像に何が写っているかをクラスとして判定するタスク。犬や車など対象カテゴリを識別する。","exam":"画像認識の基本タスクとして、物体検出やセグメンテーションとの違いが問われやすい。","difference":"物体検出は位置も求めるが、一般物体認識は主に画像内のカテゴリ判定を行う。","mnemonic":"何が写るか判定","field":"4/5","priority":"A"},{"id":"opus-339","category":"ディープラーニングの要素技術","term":"不変性の獲得","summary":"入力の位置や大きさが少し変わっても、同じ特徴として認識できる性質を得ること。","exam":"CNNやプーリングで、画像の平行移動などに頑健になる理由として問われやすい。","difference":"データ拡張は学習データを増やす工夫、不変性は変化に左右されにくい性質。","mnemonic":"少しズレても同じ","field":"4/5","priority":"A"},{"id":"opus-340","category":"ディープラーニングの要素技術","term":"事前学習","summary":"大規模データなどで先にモデルを学習し、その知識を別のタスクに利用する学習方法。","exam":"転移学習やファインチューニングと関連し、少ないデータで性能を高める方法として問われやすい。","difference":"ファインチューニングは事前学習済みモデルを目的タスク向けに再調整する段階。","mnemonic":"先に学んで使う","field":"4/5","priority":"A"},{"id":"opus-341","category":"ディープラーニングの要素技術","term":"事前学習済みモデル","summary":"大規模データであらかじめ学習され、別タスクへ転用できるモデル。少量データでも使いやすい。","exam":"転移学習やファインチューニングの出発点として問われやすい。","difference":"事前学習は学習過程、事前学習済みモデルはその結果得られたモデル。","mnemonic":"学習済みの土台","field":"4/5","priority":"A"},{"id":"opus-342","category":"ディープラーニングの要素技術","term":"位置エンコーディング","summary":"Transformerに単語の順序情報を与えるため、入力埋め込みに位置を表す情報を加える方法。","exam":"RNNを使わないTransformerが語順を扱うための仕組みとして問われやすい。","difference":"RNNは構造上順序を扱うが、Transformerは位置情報を別に加える必要がある。","mnemonic":"順番を足す","field":"4/5","priority":"A"},{"id":"opus-343","category":"ディープラーニングの要素技術","term":"分散表現","summary":"意味を1つの記号ではなく、複数次元のベクトル全体に分散して表す方法。","exam":"単語埋め込みの考え方として、ワンホット表現との違いが問われやすい。","difference":"ワンホットは1箇所だけ1、分散表現は多くの値で意味を表す。","mnemonic":"意味を散らして表す","field":"4/5","priority":"A"},{"id":"opus-344","category":"ディープラーニングの要素技術","term":"創発（Emergent Abilities）","summary":"一定規模を超えたときに、突然できるようになる能力のこと。","exam":"スケーリング則と合わせて、大規模モデルの特徴として問われやすい。","difference":"過学習は性能低下の現象で、創発は規模による性能の飛躍。","mnemonic":"規模で突然できる","field":"4/5","priority":"A"},{"id":"opus-345","category":"ディープラーニングの要素技術","term":"勾配消失問題","summary":"誤差逆伝播で勾配が小さくなり、前の層や遠い時刻の重みが学習しにくくなる問題。","exam":"RNNや深いネットワークの長期依存学習を妨げる問題として問われやすい。","difference":"勾配爆発は勾配が大きすぎる問題、勾配消失は小さすぎる問題。","mnemonic":"勾配が消える","field":"4/5","priority":"A"},{"id":"opus-346","category":"ディープラーニングの要素技術","term":"勾配爆発問題","summary":"誤差逆伝播で勾配が大きくなりすぎ、重み更新が不安定になって学習が壊れやすくなる問題。","exam":"RNNや深いネットワークで、勾配クリッピングなどの対策と一緒に問われやすい。","difference":"勾配消失は更新が進まない問題、勾配爆発は更新が暴走する問題。","mnemonic":"勾配が暴れる","field":"4/5","priority":"A"},{"id":"opus-347","category":"ディープラーニングの要素技術","term":"半教師あり学習","summary":"少量のラベル付きデータと大量のラベルなしデータを組み合わせて学習する方法。","exam":"教師あり・教師なし学習の中間として、ラベル不足への対応で問われやすい。","difference":"自己教師あり学習はラベルなしデータから疑似教師を作る点が特徴。","mnemonic":"少ラベル＋無ラベル","field":"4/5","priority":"A"},{"id":"opus-348","category":"ディープラーニングの要素技術","term":"単語埋め込み","summary":"単語を意味の近さが反映される低次元ベクトルに変換する表現方法。word2vecなどが例。","exam":"分散表現やword2vecと関連し、単語を数値化する方法として問われやすい。","difference":"ワンホットは疎で意味距離を表しにくく、単語埋め込みは密で意味を表しやすい。","mnemonic":"単語を意味ベクトル","field":"4/5","priority":"A"},{"id":"opus-349","category":"ディープラーニングの要素技術","term":"双方向 RNN (Bidirectional RNN)","summary":"過去から未来、未来から過去の両方向に系列を読み、前後の文脈を利用するRNN。","exam":"自然言語処理で、前後文脈を使えるが未来情報が必要な点が問われやすい。","difference":"通常のRNNは一方向に読むが、双方向RNNは前後両方向から読む。","mnemonic":"前後から読む","field":"4/5","priority":"A"},{"id":"opus-350","category":"ディープラーニングの要素技術","term":"基盤モデル","summary":"大規模データで事前学習され、多様な下流タスクへ転用できる大規模モデルの総称。","exam":"生成AIや転移学習の中心概念として、事前学習済みモデルとの関係が問われやすい。","difference":"事前学習済みモデル全般より、大規模で多目的に使える土台モデルを指すことが多い。","mnemonic":"多用途の土台","field":"4/5","priority":"A"},{"id":"opus-351","category":"ディープラーニングの要素技術","term":"報酬成形","summary":"望ましい行動を学びやすくするため、元の報酬に補助的な報酬を設計して加えること。","exam":"強化学習の学習効率改善として、報酬設計の重要性と一緒に問われやすい。","difference":"報酬関数そのものの調整であり、方策や価値関数のアルゴリズム名ではない。","mnemonic":"報酬で誘導する","field":"4/5","priority":"A"},{"id":"opus-352","category":"ディープラーニングの要素技術","term":"変分オートエンコーダ　(VAE)","summary":"入力を潜在分布に変換し、そこからデータを再構成する生成モデル。新しいデータ生成にも使える。","exam":"生成モデルの代表例として、潜在変数と確率分布を使う点が問われやすい。","difference":"通常のオートエンコーダは再構成中心、VAEは確率的な潜在分布を学ぶ。","mnemonic":"分布から生成","field":"4/5","priority":"A"},{"id":"opus-353","category":"ディープラーニングの要素技術","term":"大規模言語モデル(LLM)","summary":"大量のテキストと大規模パラメータで学習し、生成や要約、質問応答などを行う言語モデル。","exam":"生成AIの中心技術として、Transformerや事前学習との関係が問われやすい。","difference":"BERTは理解系の事前学習モデル、LLMは生成を含む広い言語能力を持つ大規模モデル。","mnemonic":"巨大な言葉の脳","field":"4/5","priority":"A"},{"id":"opus-354","category":"ディープラーニングの要素技術","term":"姿勢推定","summary":"画像や動画から人の関節点や骨格の位置を推定し、身体の姿勢を認識するタスク。","exam":"Open Poseなどの応用例として、物体検出や領域分割とは違うタスクで問われやすい。","difference":"物体検出は枠を出すが、姿勢推定は関節点や骨格の配置を求める。","mnemonic":"骨格を読む","field":"4/5","priority":"A"},{"id":"opus-355","category":"ディープラーニングの要素技術","term":"宝くじ仮説","summary":"大きなネットワーク内には、初期化次第で単独でも高性能な小さな部分構造があるという仮説。","exam":"プルーニングや疎なネットワークと関連し、小さな当たり部分構造として問われやすい。","difference":"プルーニングは削る操作、宝くじ仮説は有効な小ネットワークが存在するという考え。","mnemonic":"当たり部分網","field":"4/5","priority":"A"},{"id":"opus-356","category":"ディープラーニングの要素技術","term":"平均値プーリング","summary":"小さな領域内の平均値を取り、局所的な情報をならしながら特徴マップを小さくする処理。","exam":"最大値プーリングとの違いとして、強い反応だけでなく周辺情報も平均する点が問われやすい。","difference":"最大値プーリングは最大だけを残し、平均値プーリングは領域全体をならす。","mnemonic":"ならして縮める","field":"4/5","priority":"A"},{"id":"opus-357","category":"ディープラーニングの要素技術","term":"形態素解析","summary":"文章を意味を持つ最小単位である形態素に分け、品詞などを判定する処理。","exam":"日本語NLPの前処理として、単語分割や品詞推定の文脈で問われやすい。","difference":"構文解析は文の構造を見るが、形態素解析は単語単位への分割が中心。","mnemonic":"文を単語に割る","field":"4/5","priority":"A"},{"id":"opus-358","category":"ディープラーニングの要素技術","term":"情報検索","summary":"利用者の問い合わせに対し、関連する文書や情報をデータベースから探し出す技術。","exam":"検索エンジンやTF-IDF、ランキング手法と関連して問われやすい。","difference":"質問応答は答えを直接返すが、情報検索は関連する情報源を探す。","mnemonic":"関連情報を探す","field":"4/5","priority":"A"},{"id":"opus-359","category":"ディープラーニングの要素技術","term":"感情分析","summary":"文章から肯定・否定・中立などの感情や評価を推定する自然言語処理タスク。","exam":"レビュー分析やSNS分析の応用例として、分類問題の一種として問われやすい。","difference":"質問応答は答えを返すタスク、感情分析は文の評価や感情を分類する。","mnemonic":"文の気持ち判定","field":"4/5","priority":"A"},{"id":"opus-360","category":"ディープラーニングの要素技術","term":"指示チューニング（Instruction Tuning）","summary":"指示と応答の組で追加学習し、指示に従いやすいモデルにすること。","exam":"RLHFの前段階として、指示追従性の獲得方法で問われやすい。","difference":"RLHFは人間の好みを報酬として強化学習する、さらに後の工程。","mnemonic":"指示に従わせる","field":"4/5","priority":"A"},{"id":"opus-361","category":"ディープラーニングの要素技術","term":"教師強制","summary":"系列生成の学習時に、前時刻の予測ではなく正解データを次の入力として使う方法。","exam":"Seq2Seqなどで学習を安定させる工夫として、推論時との差に注意して問われやすい。","difference":"通常の生成は前の予測を使うが、教師強制は学習時に正解を入力する。","mnemonic":"正解を次に渡す","field":"4/5","priority":"A"},{"id":"opus-362","category":"ディープラーニングの要素技術","term":"敵対的生成ネットワーク (GAN)","summary":"生成器が偽物データを作り、識別器が本物か偽物かを見分ける競争で学習する生成モデル。","exam":"生成モデルの代表として、生成器・識別器の役割やDCGANとの関係が問われやすい。","difference":"DCGANはGANをCNNで構成した画像生成向けモデル。","mnemonic":"作る側と見抜く側","field":"4/5","priority":"A"},{"id":"opus-363","category":"ディープラーニングの要素技術","term":"文書要約","summary":"長い文書から重要な内容を短くまとめる自然言語処理タスク。抽出型と生成型がある。","exam":"Seq2SeqやTransformer、LLMの応用例として問われやすい。","difference":"機械翻訳は言語を変換し、文書要約は同じ内容を短く圧縮する。","mnemonic":"長文を短くする","field":"4/5","priority":"A"},{"id":"opus-364","category":"ディープラーニングの要素技術","term":"文章生成","summary":"学習した言語パターンをもとに、文章を続けたり要約や対話文を作ったりする生成AIタスク。","exam":"大規模言語モデルやTransformerの応用として、生成AIの文脈で問われやすい。","difference":"文章分類はラベル判定、文章生成は新しいテキストを作る。","mnemonic":"言葉を作る","field":"4/5","priority":"A"},{"id":"opus-365","category":"ディープラーニングの要素技術","term":"時系列データ","summary":"時間の順序を持って観測されたデータ。株価、音声、センサ値、文章の並びなどが例になる。","exam":"RNNやLSTMで扱う代表的データとして、順序情報が重要な点が問われやすい。","difference":"表形式データより、データの並び順や過去との関係が重要になる。","mnemonic":"時間順のデータ","field":"4/5","priority":"A"},{"id":"opus-366","category":"ディープラーニングの要素技術","term":"最大値プーリング","summary":"小さな領域内の最大値を取り出し、強く反応した特徴を残しながらサイズを小さくする処理。","exam":"CNNで特徴量を圧縮し、多少の位置ずれに強くする手法として問われやすい。","difference":"平均値プーリングは平均を取り、最大値プーリングは最も強い反応だけを残す。","mnemonic":"強い反応を残す","field":"4/5","priority":"A"},{"id":"opus-367","category":"ディープラーニングの要素技術","term":"構文解析","summary":"文中の単語同士の係り受けや文法構造を解析し、文の構造を明らかにする処理。","exam":"自然言語理解の基礎として、形態素解析の次段階の処理として問われやすい。","difference":"形態素解析は単語分割、構文解析は単語間の文法的関係を見る。","mnemonic":"文の骨組みを見る","field":"4/5","priority":"A"},{"id":"opus-368","category":"ディープラーニングの要素技術","term":"機械翻訳","summary":"ある言語の文を別の言語へ自動変換する技術。統計的手法からニューラル機械翻訳へ発展した。","exam":"Seq2SeqやAttention、Transformerの代表的応用として問われやすい。","difference":"統計的機械翻訳は確率モデル中心、現在はニューラル機械翻訳が主流。","mnemonic":"言語を自動変換","field":"4/5","priority":"A"},{"id":"opus-369","category":"ディープラーニングの要素技術","term":"次元削減","summary":"高次元データを、重要な情報を残しながら低次元の表現に変換する処理。可視化や圧縮に使う。","exam":"オートエンコーダやPCAと関連し、特徴抽出や圧縮の文脈で問われやすい。","difference":"PCAは線形手法、オートエンコーダはニューラルネットで非線形な圧縮も扱える。","mnemonic":"情報を低次元へ","field":"4/5","priority":"A"},{"id":"opus-370","category":"ディープラーニングの要素技術","term":"残差強化学習","summary":"既存の制御器や方策に、強化学習で学んだ補正分を足して性能改善を狙う方法。","exam":"ロボット制御などで、既存制御と学習制御を組み合わせる考え方として問われやすい。","difference":"一から方策を学ぶのではなく、既存方策の足りない部分を補う。","mnemonic":"制御に補正を足す","field":"4/5","priority":"A"},{"id":"opus-371","category":"ディープラーニングの要素技術","term":"物体検出","summary":"画像中の物体のカテゴリと位置を、バウンディングボックスなどで同時に推定するタスク。","exam":"YOLO・SSD・Faster R-CNNなどの代表タスクとして、分類との違いが問われやすい。","difference":"物体識別は何かを判定し、物体検出は何がどこにあるかまで求める。","mnemonic":"何がどこにある","field":"4/5","priority":"A"},{"id":"opus-372","category":"ディープラーニングの要素技術","term":"物体識別","summary":"切り出された画像や対象が、どのクラスに属するかを判定するタスク。分類に近い。","exam":"物体検出との違いとして、位置推定ではなくカテゴリ判定が中心と問われやすい。","difference":"物体検出は位置も推定するが、物体識別は対象の種類を見分ける。","mnemonic":"種類を見分ける","field":"4/5","priority":"A"},{"id":"opus-373","category":"ディープラーニングの要素技術","term":"特徴マップ","summary":"畳み込みによって得られる出力。入力のどこに特定の特徴が現れたかを表す地図のようなもの。","exam":"CNN内部の表現として、フィルタが検出した特徴の出力と問われやすい。","difference":"フィルタは特徴を探す重み、特徴マップは探した結果として得られる出力。","mnemonic":"特徴の地図","field":"4/5","priority":"A"},{"id":"opus-374","category":"ディープラーニングの要素技術","term":"状態表現学習","summary":"観測データから、強化学習で使いやすい状態の特徴表現を自動的に学ぶ方法。","exam":"画像入力や高次元観測を扱う強化学習で、表現学習の重要性として問われやすい。","difference":"状態価値関数は状態の価値を表し、状態表現学習は状態の表し方を学ぶ。","mnemonic":"状態をうまく表す","field":"4/5","priority":"A"},{"id":"opus-375","category":"ディープラーニングの要素技術","term":"画像生成","summary":"学習した画像の特徴をもとに、新しい画像を生成する技術。GANや拡散モデルが代表例。","exam":"生成AIの代表的応用として、GAN・Diffusion Modelとの関係で問われやすい。","difference":"画像認識は画像を判定し、画像生成は新しい画像を作る。","mnemonic":"絵を作るAI","field":"4/5","priority":"A"},{"id":"opus-376","category":"ディープラーニングの要素技術","term":"畳み込みニューラルネットワーク (CNN)","summary":"畳み込み層を使い、画像などの局所的なパターンや位置関係を効率よく学習するネットワーク。","exam":"画像認識の代表モデルとして、畳み込み・プーリング・特徴マップと問われやすい。","difference":"MLPは全結合中心、CNNは畳み込みで空間的特徴を捉える。","mnemonic":"画像に強い網","field":"4/5","priority":"A"},{"id":"opus-377","category":"ディープラーニングの要素技術","term":"畳み込み操作","summary":"フィルタを入力データ上で滑らせ、局所的な特徴を計算して特徴マップを作る操作。","exam":"CNNの中心処理として、局所受容野や重み共有と関連して問われやすい。","difference":"全結合層は全入力をつなぐが、畳み込みは局所領域に同じフィルタを適用する。","mnemonic":"窓で特徴抽出","field":"4/5","priority":"A"},{"id":"opus-378","category":"ディープラーニングの要素技術","term":"破滅的忘却","summary":"新しいタスクを学習すると、以前に学んだ知識や性能が大きく失われる現象。","exam":"継続学習の課題として、追加学習やファインチューニングの注意点で問われやすい。","difference":"過学習は訓練データへの合わせすぎ、破滅的忘却は過去タスクを忘れる問題。","mnemonic":"新しく学ぶと忘れる","field":"4/5","priority":"A"},{"id":"opus-379","category":"ディープラーニングの要素技術","term":"積層オートエンコーダ","summary":"複数のオートエンコーダを重ね、段階的に特徴を学習する深いネットワーク。","exam":"ディープラーニング初期の事前学習手法として、特徴抽出と関連して問われやすい。","difference":"単体のオートエンコーダより、複数層を重ねて階層的な表現を学ぶ。","mnemonic":"圧縮器を重ねる","field":"4/5","priority":"A"},{"id":"opus-380","category":"ディープラーニングの要素技術","term":"統計的機械翻訳","summary":"大量の対訳データから翻訳候補の確率を学び、もっともらしい訳を選ぶ機械翻訳方式。","exam":"ルールベース翻訳やニューラル機械翻訳との比較で、確率と対訳データが問われやすい。","difference":"ニューラル機械翻訳は深層学習を使い、統計的機械翻訳は確率モデル中心。","mnemonic":"対訳を確率で訳す","field":"4/5","priority":"A"},{"id":"opus-381","category":"ディープラーニングの要素技術","term":"線形関数","summary":"入力を重み付きで足し合わせ、直線や平面で表せる関係を作る関数。ニューラルネットの基本計算になる。","exam":"活性化関数を入れないと線形変換の重ね合わせに留まる点が問われやすい。","difference":"非線形関数は曲がった関係を表せ、深層学習では活性化関数が非線形性を与える。","mnemonic":"まっすぐ変換","field":"4/5","priority":"A"},{"id":"opus-382","category":"ディープラーニングの要素技術","term":"自己教師あり学習","summary":"データ自身から疑似的な正解を作り、ラベルなしデータで特徴表現を学習する方法。","exam":"事前学習や大規模言語モデルで、ラベルなしデータ活用として問われやすい。","difference":"半教師あり学習は少量ラベルを併用し、自己教師あり学習はデータ内から教師信号を作る。","mnemonic":"自分で問題作成","field":"4/5","priority":"A"},{"id":"opus-383","category":"ディープラーニングの要素技術","term":"蒸留","summary":"大きな教師モデルの出力を手がかりに、小さな生徒モデルへ知識を移すモデル圧縮手法。","exam":"モデル圧縮の代表として、教師モデルと生徒モデルの関係が問われやすい。","difference":"プルーニングは不要な重みを削り、蒸留は小型モデルへ知識を移す。","mnemonic":"大モデルを小型化","field":"4/5","priority":"A"},{"id":"opus-384","category":"ディープラーニングの要素技術","term":"話者識別","summary":"音声から誰が話しているかを推定するタスク。声質や発話特徴を手がかりに分類する。","exam":"音声認識との違いとして、何を話したかではなく誰が話したかを当てる点が問われやすい。","difference":"音声認識は内容を文字化し、話者識別は話している人物を推定する。","mnemonic":"声で人を当てる","field":"4/5","priority":"A"},{"id":"opus-385","category":"ディープラーニングの要素技術","term":"説明可能 AI (XAI)","summary":"AIの予測や判断について、人間が理解できる理由や根拠を示そうとする技術や考え方。","exam":"ブラックボックス性への対策として、CAM・LIME・SHAPなどと関連して問われやすい。","difference":"精度向上の手法ではなく、判断根拠を人が理解しやすくする考え方。","mnemonic":"理由が見えるAI","field":"4/5","priority":"A"},{"id":"opus-386","category":"ディープラーニングの要素技術","term":"質問応答","summary":"質問文を理解し、文書や知識から適切な答えを抽出または生成する自然言語処理タスク。","exam":"BERTや大規模言語モデルの評価タスクとして、情報検索との違いが問われやすい。","difference":"情報検索は関連文書を探し、質問応答は答えそのものを返す。","mnemonic":"問いに答える","field":"4/5","priority":"A"},{"id":"opus-387","category":"ディープラーニングの要素技術","term":"連続値制御","summary":"ロボットの関節角や速度のように、離散選択ではなく連続的な行動値を出力して制御すること。","exam":"ロボット制御で、DQNより方策勾配法やActor-Critic系が使われやすい点が問われやすい。","difference":"DQNは離散行動に向き、連続値制御は連続的な行動空間を扱う。","mnemonic":"なめらかに動かす","field":"4/5","priority":"A"},{"id":"opus-388","category":"ディープラーニングの要素技術","term":"重み","summary":"ニューラルネットワークで入力の重要度を調整する値。学習により更新され、出力結果に影響する。","exam":"パラメータの代表例として、バイアスや勾配降下法との関係で問われやすい。","difference":"ハイパーパラメータは人が設定し、重みは学習によって自動更新される。","mnemonic":"重要度のつまみ","field":"4/5","priority":"A"},{"id":"opus-389","category":"ディープラーニングの要素技術","term":"量子化","summary":"重みや活性化の数値精度を下げ、メモリ使用量や計算量を減らすモデル圧縮手法。","exam":"エッジAIでの高速化・省メモリ化として、プルーニングとの違いが問われやすい。","difference":"プルーニングは接続を削り、量子化は数値のビット幅を小さくする。","mnemonic":"数字を粗く軽く","field":"4/5","priority":"A"},{"id":"opus-390","category":"ディープラーニングの要素技術","term":"隠れマルコフモデル","summary":"観測できない状態が確率的に移り変わり、観測系列を生むと考える時系列モデル。","exam":"音声認識の古典的手法として、状態遷移と観測確率の考え方が問われやすい。","difference":"RNNはニューラルネットで系列を学び、HMMは確率的な状態遷移を明示する。","mnemonic":"隠れ状態が遷移","field":"4/5","priority":"A"},{"id":"opus-391","category":"ディープラーニングの要素技術","term":"音声合成","summary":"テキストや記号情報から人間の声のような音声を生成する技術。読み上げAIなどに使われる。","exam":"音声認識との対比として、入力と出力の向きの違いが問われやすい。","difference":"音声認識は音声を文字へ、音声合成は文字などを音声へ変換する。","mnemonic":"文字から声へ","field":"4/5","priority":"A"},{"id":"opus-392","category":"ディープラーニングの要素技術","term":"音声生成","summary":"音声波形や音声特徴を生成し、人の声や音楽、効果音などを作る生成AIの応用分野。","exam":"WaveNetや音声合成と関連し、生成AIの対象が画像や文章だけでない点で問われやすい。","difference":"音声認識は音声を文字へ、音声生成は新しい音声を作る。","mnemonic":"声や音を作る","field":"4/5","priority":"A"},{"id":"opus-393","category":"ディープラーニングの要素技術","term":"音声認識","summary":"人間の発話音声を解析し、単語や文章などの文字情報へ変換する技術。","exam":"CTCや隠れマルコフモデル、MFCCなどと関連して問われやすい。","difference":"音声合成は音を作る技術、音声認識は音を理解して文字化する技術。","mnemonic":"声を文字へ","field":"4/5","priority":"A"},{"id":"opus-394","category":"ディープラーニングの要素技術","term":"音素","summary":"言語で意味の違いを区別する最小の音単位。日本語の母音や子音の区別などが例になる。","exam":"音声認識の基礎単位として、音韻や発音モデルとの関係で問われやすい。","difference":"音韻は音の体系、音素はその中で意味を分ける最小単位。","mnemonic":"意味を分ける音","field":"4/5","priority":"A"},{"id":"opus-395","category":"ディープラーニングの要素技術","term":"音韻","summary":"言語の中で意味の違いを生む音の体系。音素を組み合わせ、言語ごとの音の区別を扱う。","exam":"音声認識や言語処理で、音素との違いとして問われやすい。","difference":"音素は最小の音の単位、音韻は言語内での音の体系や区別を指す。","mnemonic":"言語の音ルール","field":"4/5","priority":"A"},{"id":"opus-396","category":"ディープラーニングの要素技術","term":"高速フーリエ変換 (FFT)","summary":"時間波形を周波数成分へ高速に変換するアルゴリズム。音声の周波数分析に使われる。","exam":"音声特徴量抽出の前処理として、スペクトルやMFCCとの関係で問われやすい。","difference":"A-D変換は音をデジタル化し、FFTはデジタル信号を周波数成分に分ける。","mnemonic":"音を周波数へ","field":"4/5","priority":"A"},{"id":"opus-397","category":"AIに関する法律と契約","term":"AI 生成物","summary":"AIが出力した文章・画像・音声など。人の創作的関与の有無で権利関係が問題になる。","exam":"著作権の発生や侵害判断で、人間の関与や既存著作物との類似が問われやすい。","difference":"人が創作した著作物と違い、AIだけの出力は権利保護が問題になりやすい。","mnemonic":"AIが作った成果","field":"8","priority":"B"},{"id":"opus-398","category":"AIに関する法律と契約","term":"AI・データの利用に関する契約ガイドライン","summary":"AI開発やデータ利用の契約で、権利・責任・成果物の扱いなどを整理するための指針。","exam":"AI開発契約で、データ利用権や成果物、責任分担を明確にする文脈で問われやすい。","difference":"法律そのものではなく、契約実務で論点を整理するためのガイドライン。","mnemonic":"契約論点の地図","field":"8","priority":"B"},{"id":"opus-399","category":"AIに関する法律と契約","term":"AI生成物の著作物性","summary":"人間の創作的寄与があるかどうかで、著作物として保護されるかが分かれる。","exam":"AIが自動生成しただけの成果物の扱いとして問われやすい。","difference":"学習データの利用可否とは別で、こちらは出力側の権利の話。","mnemonic":"人の関与で決まる","field":"8","priority":"B"},{"id":"opus-400","category":"AIに関する法律と契約","term":"GDPR","summary":"EUの個人データ保護規則。個人データの取得・利用・移転に厳しいルールを定める。","exam":"海外データ利用や個人情報保護の代表的規制として問われやすい。","difference":"日本の個人情報保護法とは別に、EU域内の個人データ保護を扱う規則。","mnemonic":"EUの個人データ法","field":"8","priority":"B"},{"id":"opus-401","category":"AIに関する法律と契約","term":"NDA","summary":"秘密保持契約のこと。相手から得た技術情報や営業情報を外部に漏らさない約束。","exam":"AI開発前のデータ共有や共同検討で、営業秘密保護と関連して問われやすい。","difference":"利用規約はサービス利用条件、NDAは秘密情報の取り扱いを定める契約。","mnemonic":"秘密を守る約束","field":"8","priority":"B"},{"id":"opus-402","category":"AIに関する法律と契約","term":"PoC","summary":"本格開発や導入の前に、小規模に試してAIの実現可能性や効果を検証する段階。","exam":"AI契約では、研究開発前の検証段階として成果保証との違いが問われやすい。","difference":"本番開発は実運用を目指すが、PoCは実現性や効果の確認が主目的。","mnemonic":"小さく試す検証","field":"8","priority":"B"},{"id":"opus-403","category":"AIに関する法律と契約","term":"SaaS","summary":"ソフトウェアをインストールせず、クラウド上のサービスとして利用する提供形態。","exam":"生成AIや分析ツール利用時に、利用規約やデータ入力の扱いと関連して問われやすい。","difference":"パッケージソフトは手元に導入し、SaaSはネット経由でサービスを利用する。","mnemonic":"借りて使うソフト","field":"8","priority":"B"},{"id":"opus-404","category":"AIに関する法律と契約","term":"データ利用権","summary":"データを収集・加工・学習・分析などに使える範囲を定める権利や契約上の取り決め。","exam":"AI学習用データの利用可否や、成果物への利用範囲として問われやすい。","difference":"所有権とは限らず、契約で定めた目的や範囲内で使える権限を指す。","mnemonic":"データを使う権限","field":"8","priority":"B"},{"id":"opus-405","category":"AIに関する法律と契約","term":"プロファイリング","summary":"個人データを分析し、行動や嗜好、能力などを予測・評価すること。","exam":"GDPRの自動意思決定の規制や、差別リスクと結びつけて問われる。","difference":"単なるデータ分析ではなく、個人の評価・予測を伴う点が特徴。","mnemonic":"個人を予測評価","field":"8","priority":"B"},{"id":"opus-406","category":"AIに関する法律と契約","term":"不正競争防止法","summary":"営業秘密や限定提供データの不正な取得・使用を規制する法律。","exam":"データの保護手段として、著作権や特許と並べて問われやすい。","difference":"著作権は表現の保護、不正競争防止法は秘密性・管理性のあるデータの保護。","mnemonic":"秘密データを守る","field":"8","priority":"B"},{"id":"opus-407","category":"AIに関する法律と契約","term":"仮名加工情報","summary":"他の情報と照合しない限り個人を識別できないよう、個人情報を加工した情報。","exam":"匿名加工情報との違いとして、照合すれば個人識別の可能性が残る点が問われやすい。","difference":"匿名加工情報は復元困難、仮名加工情報は対応表などで識別可能性が残る。","mnemonic":"名前を仮に隠す","field":"8","priority":"B"},{"id":"opus-408","category":"AIに関する法律と契約","term":"保守契約","summary":"導入後のシステムやAIサービスについて、不具合対応や更新、運用支援を定める契約。","exam":"AIモデルの運用後の監視や再学習、障害対応と関連して問われやすい。","difference":"開発契約は作る段階、保守契約は導入後に安定して使うための契約。","mnemonic":"導入後を支える","field":"8","priority":"B"},{"id":"opus-409","category":"AIに関する法律と契約","term":"保有個人データ","summary":"事業者が開示・訂正・利用停止などの権限を持つ個人データ。本人請求の対象になる。","exam":"本人からの開示請求や訂正請求と関連し、個人データとの違いが問われやすい。","difference":"個人データのうち、事業者が一定の権限を持ち対応義務の対象になるもの。","mnemonic":"開示請求の対象","field":"8","priority":"B"},{"id":"opus-410","category":"AIに関する法律と契約","term":"個人データ","summary":"個人情報データベース等を構成する個人情報。検索や管理ができる形の個人情報を指す。","exam":"個人情報・保有個人データとの違いとして、データベース化された情報が問われやすい。","difference":"個人情報は広い概念、個人データはデータベース等に含まれるもの。","mnemonic":"DB内の個人情報","field":"8","priority":"B"},{"id":"opus-411","category":"AIに関する法律と契約","term":"個人情報","summary":"生存する個人に関する情報で、氏名や他情報との照合により特定個人を識別できるもの。","exam":"AIで扱うデータの法的注意点として、個人データとの違いが問われやすい。","difference":"個人データはデータベース化された個人情報で、個人情報より範囲がやや限定される。","mnemonic":"人を特定する情報","field":"8","priority":"B"},{"id":"opus-412","category":"AIに関する法律と契約","term":"個人識別符号","summary":"指紋データや旅券番号など、それだけで特定の個人を識別できる符号や番号。","exam":"個人情報に該当するものとして、身体特徴データや公的番号の例が問われやすい。","difference":"氏名のような記述ではなく、番号や生体特徴などで個人を識別する。","mnemonic":"符号で個人特定","field":"8","priority":"B"},{"id":"opus-413","category":"AIに関する法律と契約","term":"公正競争阻害性","summary":"取引の公正さや自由な競争を害するおそれがある性質。不公正な取引方法の判断で使われる。","exam":"データ共有やプラットフォーム利用で、公正な競争を妨げるかの観点として問われやすい。","difference":"競争制限は競争を減らす行為、公正競争阻害性は公正な競争を害する性質を指す。","mnemonic":"公正さを害する","field":"8","priority":"B"},{"id":"opus-414","category":"AIに関する法律と契約","term":"利用目的","summary":"個人情報を何のために使うかを示す目的。取得時の通知や公表、目的外利用の制限に関わる。","exam":"個人情報の取得・利用時に、目的を明確にする必要がある点で問われやすい。","difference":"同意は許可の取得、利用目的はデータを使う理由や範囲を示すもの。","mnemonic":"何に使うか明示","field":"8","priority":"B"},{"id":"opus-415","category":"AIに関する法律と契約","term":"利用規約","summary":"サービス利用時の条件を定めた契約。入力データや生成物の扱い、禁止事項などを確認する。","exam":"生成AIサービス利用で、権利帰属や商用利用可否を確認する文脈で問われやすい。","difference":"法律は一般的なルール、利用規約は各サービスごとの契約条件。","mnemonic":"使う前の約束","field":"8","priority":"B"},{"id":"opus-416","category":"AIに関する法律と契約","term":"創作性","summary":"著作物として保護されるために必要な、作者の個性が表れた表現上の工夫。","exam":"AI生成物の著作権を考える前提として、人の創作的関与が問われやすい。","difference":"単なるアイデアや事実ではなく、具体的な表現に個性があるかが重要。","mnemonic":"個性ある表現","field":"8","priority":"B"},{"id":"opus-417","category":"AIに関する法律と契約","term":"匿名加工情報","summary":"特定の個人を識別できず、元の個人情報を復元できないよう加工した情報。","exam":"データ利活用とプライバシー保護の両立として、仮名加工情報との違いが問われやすい。","difference":"仮名加工情報は照合で識別可能性が残り、匿名加工情報は復元困難にする。","mnemonic":"戻せない匿名化","field":"8","priority":"B"},{"id":"opus-418","category":"AIに関する法律と契約","term":"営業秘密","summary":"秘密管理され、有用で、公然と知られていない技術情報や営業情報。不正競争防止法で保護される。","exam":"学習データやノウハウの保護で、秘密管理性・有用性・非公知性が問われやすい。","difference":"特許は公開して独占権を得るが、営業秘密は秘密として管理して保護する。","mnemonic":"秘密の価値情報","field":"8","priority":"B"},{"id":"opus-419","category":"AIに関する法律と契約","term":"委託","summary":"業務の一部を外部に任せること。個人データを扱わせる場合は委託先の監督が必要になる。","exam":"第三者提供との違いとして、業務委託先への提供と監督義務が問われやすい。","difference":"第三者提供は外部に渡す行為、委託は自社業務の範囲で外部に処理を任せる。","mnemonic":"任せても監督","field":"8","priority":"B"},{"id":"opus-420","category":"AIに関する法律と契約","term":"忘れられる権利","summary":"本人が自分に関する情報の削除を求めることができる権利。","exam":"GDPRの権利として、消去権や利用停止と結びつけて問われる。","difference":"開示請求は内容の確認、忘れられる権利は削除を求めるもの。","mnemonic":"消してもらう権利","field":"8","priority":"B"},{"id":"opus-421","category":"AIに関する法律と契約","term":"新規性","summary":"発明が出願前に公に知られていないこと。特許を受けるための重要な要件の一つ。","exam":"特許要件として、すでに公開済みの技術では権利化できない点が問われやすい。","difference":"進歩性は容易に思いつくか、新規性は既に知られているかを見る。","mnemonic":"まだ知られてない","field":"8","priority":"B"},{"id":"opus-422","category":"AIに関する法律と契約","term":"準委任契約","summary":"業務を適切に遂行することを目的とする契約。完成物そのものより作業過程を重視する。","exam":"不確実性が高いAI開発で、請負契約より使われやすい場面として問われやすい。","difference":"請負契約は完成責任、準委任契約は善管注意義務に基づく業務遂行が中心。","mnemonic":"作業をきちんと行う","field":"8","priority":"B"},{"id":"opus-423","category":"AIに関する法律と契約","term":"特許権","summary":"特許を受けた発明を、一定期間独占的に実施できる権利。技術の利用を管理できる。","exam":"AI関連発明の保護手段として、著作権や営業秘密との違いが問われやすい。","difference":"著作権は表現を保護し、特許権は技術的な発明を出願により保護する。","mnemonic":"技術を独占する","field":"8","priority":"B"},{"id":"opus-424","category":"AIに関する法律と契約","term":"発明","summary":"自然法則を利用した技術的思想の創作のうち、高度なもの。特許保護の対象になる。","exam":"AI関連技術が特許になり得るかを考える前提として問われやすい。","difference":"著作物は表現を保護し、発明は技術的なアイデアや仕組みを保護する。","mnemonic":"技術の創作","field":"8","priority":"B"},{"id":"opus-425","category":"AIに関する法律と契約","term":"発明者","summary":"発明の創作に実質的に関与した自然人。単なる指示者や資金提供者は通常含まれない。","exam":"AIを使った発明で、誰が発明者になるかという論点として問われやすい。","difference":"権利者は特許を持つ人や法人、発明者は技術的創作をした人。","mnemonic":"作った人が発明者","field":"8","priority":"B"},{"id":"opus-426","category":"AIに関する法律と契約","term":"知的財産権","summary":"発明、著作物、商標、営業秘密など、人の知的活動から生まれた成果を守る権利の総称。","exam":"AI開発で、著作権・特許権・営業秘密を区別する文脈で問われやすい。","difference":"特許権や著作権は個別の権利で、知的財産権はそれらを含む広い概念。","mnemonic":"知の成果を守る","field":"8","priority":"B"},{"id":"opus-427","category":"AIに関する法律と契約","term":"競争制限","summary":"事業者間の競争を不当に減らす行為。価格固定や市場分割などが問題になり得る。","exam":"AIやデータ連携で、独占禁止法上の注意点として問われやすい。","difference":"公正競争阻害性は競争への悪影響の性質、競争制限は競争を減らす行為。","mnemonic":"競争を弱める","field":"8","priority":"B"},{"id":"opus-428","category":"AIに関する法律と契約","term":"第三者提供","summary":"個人データを本人・事業者以外の第三者へ提供すること。原則として本人同意が重要になる。","exam":"個人データの外部提供で、同意や例外、委託との違いが問われやすい。","difference":"委託は業務を任せる範囲での提供、第三者提供は別主体への提供として扱う。","mnemonic":"外部へ渡す注意","field":"8","priority":"B"},{"id":"opus-429","category":"AIに関する法律と契約","term":"精度保証","summary":"AIモデルが一定の予測精度を必ず満たすことを保証する考え方。契約上は慎重に扱う必要がある。","exam":"AIはデータや環境で性能が変わるため、安易な保証が難しい点として問われやすい。","difference":"性能目標は目指す水準、精度保証は達成を約束するため責任が重くなる。","mnemonic":"精度約束は慎重","field":"8","priority":"B"},{"id":"opus-430","category":"AIに関する法律と契約","term":"職務発明","summary":"従業員が職務上行った発明で、会社の業務範囲に属し職務に基づいて生まれたもの。","exam":"企業内AI開発で、発明者と会社の権利帰属や対価の論点として問われやすい。","difference":"通常の発明は個人発明も含むが、職務発明は勤務先の業務と職務に関係する。","mnemonic":"仕事で生まれた発明","field":"8","priority":"B"},{"id":"opus-431","category":"AIに関する法律と契約","term":"著作権","summary":"著作物を創作した人に発生する権利。複製や公衆送信などをコントロールできる。","exam":"AIとコンテンツ利用で、学習データや生成物の扱いと関連して問われやすい。","difference":"所有権は物への権利、著作権は創作的表現に関する権利。","mnemonic":"表現を守る権利","field":"8","priority":"B"},{"id":"opus-432","category":"AIに関する法律と契約","term":"著作権侵害","summary":"他人の著作物を無断で複製・翻案・公開するなど、著作権者の権利を害する行為。","exam":"AI生成物が既存著作物に似た場合や、学習・利用場面のリスクとして問われやすい。","difference":"著作権は権利そのもの、著作権侵害はその権利を不当に害する行為。","mnemonic":"他人の表現を侵す","field":"8","priority":"B"},{"id":"opus-433","category":"AIに関する法律と契約","term":"著作権法30条の4","summary":"情報解析など、著作物の表現を享受しない目的なら原則利用できるとする規定。","exam":"AI学習用データの収集が日本で認められる根拠として頻出。","difference":"30条の4は学習段階の話で、生成物の著作権侵害は別の論点。","mnemonic":"学習は原則OK","field":"8","priority":"B"},{"id":"opus-434","category":"AIに関する法律と契約","term":"著作物","summary":"思想や感情を創作的に表現したもので、文章・画像・音楽・プログラムなどが含まれる。","exam":"AI学習データや生成物利用で、著作権の対象となるかが問われやすい。","difference":"アイデア自体は著作物ではなく、具体的に創作的に表現されたものが著作物。","mnemonic":"表現が守られる","field":"8","priority":"B"},{"id":"opus-435","category":"AIに関する法律と契約","term":"要配慮個人情報","summary":"人種、信条、病歴、犯罪歴など、不当な差別や偏見につながりやすい個人情報。","exam":"取得時に特に慎重な扱いが必要な情報として、個人情報の中でも問われやすい。","difference":"通常の個人情報より、本人への不利益が生じやすく取扱いが厳しい。","mnemonic":"特に慎重な情報","field":"8","priority":"B"},{"id":"opus-436","category":"AIに関する法律と契約","term":"請負契約","summary":"仕事の完成を目的とする契約。完成物の納品や成果に対する責任が重視される。","exam":"AI開発では成果完成の保証が難しいため、準委任契約との違いが問われやすい。","difference":"準委任契約は作業遂行を目的とし、請負契約は完成した成果物を重視する。","mnemonic":"完成を約束する","field":"8","priority":"B"},{"id":"opus-437","category":"AIに関する法律と契約","term":"越境データ移転","summary":"個人データを国外の第三者に提供する際の規制。本人同意や体制確認が必要。","exam":"GDPRやクラウド利用の文脈で問われやすい。","difference":"第三者提供の一種だが、国外が相手であることで要件が加わる。","mnemonic":"国外提供は要注意","field":"8","priority":"B"},{"id":"opus-438","category":"AIに関する法律と契約","term":"進歩性","summary":"既存技術から当業者が簡単に思いつけない程度の技術的な工夫があること。","exam":"特許要件として、新規性と並び、容易に発明できたかどうかで問われやすい。","difference":"新規性は既知かどうか、進歩性は既知技術から容易かどうかを見る。","mnemonic":"簡単には思いつかない","field":"8","priority":"B"},{"id":"opus-439","category":"AIに関する法律と契約","term":"限定提供データ","summary":"業として特定の者に提供され、電磁的に管理された相当量の技術上または営業上の情報。","exam":"データ利活用時の不正取得・使用防止として、営業秘密との違いが問われやすい。","difference":"営業秘密は非公知性が必要だが、限定提供データは限定提供と電磁的管理が重視される。","mnemonic":"限定して渡すデータ","field":"8","priority":"B"},{"id":"opus-440","category":"AIに関する法律と契約","term":"類似性・依拠性","summary":"著作権侵害の判断基準。既存作品に似ていることと、それに基づいたこと。","exam":"AI生成物が著作権侵害になるかの判断枠組みとして問われやすい。","difference":"創作性は著作物として保護されるかの要件で、侵害判断とは別の段階。","mnemonic":"似て・見て作った","field":"8","priority":"B"},{"id":"opus-441","category":"AI倫理・AIガバナンス","term":"AI ガバナンス","summary":"AIのリスクを管理し、方針・体制・手続きにより適切に開発・運用する仕組み。","exam":"組織としてAIを安全に使うための管理体制として問われやすい。","difference":"AI倫理は価値原則、AIガバナンスはそれを実行する仕組み。","mnemonic":"AI運用の舵取り","field":"8","priority":"B"},{"id":"opus-442","category":"AI倫理・AIガバナンス","term":"AI 倫理","summary":"AIの開発・利用で、人権、公平性、透明性、安全性などを守るための考え方。","exam":"AIを社会で使う際の基本原則として、公平性や説明責任と関連して問われやすい。","difference":"AIガバナンスは体制や運用、AI倫理は守るべき価値や考え方を指す。","mnemonic":"AIの道徳地図","field":"8","priority":"B"},{"id":"opus-443","category":"AI倫理・AIガバナンス","term":"AI事業者ガイドライン","summary":"日本で開発者・提供者・利用者それぞれの責務を整理した政府のガイドライン。","exam":"日本のAI政策の中心的文書として、法的拘束力のないソフトローの例で出る。","difference":"EU AI Actは拘束力ある法律、こちらは指針としてのソフトロー。","mnemonic":"日本の指針","field":"8","priority":"B"},{"id":"opus-444","category":"AI倫理・AIガバナンス","term":"Adversarial Attack (Adversarial Examples)","summary":"人には分かりにくい小さな入力変化で、AIに誤認識や誤分類を起こさせる攻撃。","exam":"AIの安全性・頑健性のリスクとして、画像認識などの誤判定例で問われやすい。","difference":"データ汚染は学習データを汚す攻撃、Adversarial Attackは入力を細工して誤らせる。","mnemonic":"少し変えて騙す","field":"8","priority":"B"},{"id":"opus-445","category":"AI倫理・AIガバナンス","term":"EU AI Act（EU AI規則）","summary":"AIをリスクに応じて分類し、規制の強さを変えるEUの包括的な法規制。","exam":"リスクベースアプローチの代表例として、禁止・高リスクの区分が問われやすい。","difference":"ソフトローであるガイドラインと違い、法的拘束力を持つハードロー。","mnemonic":"リスクで規制する法","field":"8","priority":"B"},{"id":"opus-446","category":"AI倫理・AIガバナンス","term":"アラインメント","summary":"AIの振る舞いを人間の意図や価値観に沿わせること。","exam":"RLHFの目的として、安全性の文脈で問われやすい。","difference":"ガードレールは外側の制約、アラインメントは内側の調整。","mnemonic":"人の意図に合わせる","field":"8","priority":"B"},{"id":"opus-447","category":"AI倫理・AIガバナンス","term":"アルゴリズムバイアス","summary":"モデルやアルゴリズムの判断が、特定の集団に不利または有利に偏ること。","exam":"公平性問題として、データの偏りやセンシティブ属性との関係で問われやすい。","difference":"データの偏りは原因になり、アルゴリズムバイアスは判断結果の偏りとして現れる。","mnemonic":"判断の偏り","field":"8","priority":"B"},{"id":"opus-448","category":"AI倫理・AIガバナンス","term":"エコーチェンバー","summary":"似た意見の人同士で情報が反響し、同じ考えが強化されやすくなる現象。","exam":"SNSや推薦システムの社会的影響として、フィルターバブルと関連して問われやすい。","difference":"フィルターバブルはアルゴリズムで情報が偏り、エコーチェンバーは同質な集団内で強化される。","mnemonic":"同じ声が反響","field":"8","priority":"B"},{"id":"opus-449","category":"AI倫理・AIガバナンス","term":"カメラ画像利活用ガイドブック","summary":"カメラ画像を事業で使う際、生活者のプライバシーに配慮するための実務指針。","exam":"画像データ利用時の通知、公表、配慮事項として問われやすい。","difference":"法律そのものではなく、カメラ画像利用での望ましい対応を示すガイド。","mnemonic":"カメラ利用の作法","field":"8","priority":"B"},{"id":"opus-450","category":"AI倫理・AIガバナンス","term":"ガードレール","summary":"不適切な出力を防ぐために設ける制約や監視の仕組み。","exam":"生成AIの安全対策として、フィルタリングや制限と結びつく。","difference":"アラインメントはモデル自体を望ましい振る舞いに近づける学習の話。","mnemonic":"出力の柵","field":"8","priority":"B"},{"id":"opus-451","category":"AI倫理・AIガバナンス","term":"サンプリングバイアス","summary":"データを集める方法が偏り、母集団を正しく代表しないデータになること。","exam":"学習データの偏りがAIの不公平な判断につながる原因として問われやすい。","difference":"データの偏りは広い概念、サンプリングバイアスは収集時の偏りを指す。","mnemonic":"集め方の偏り","field":"8","priority":"B"},{"id":"opus-452","category":"AI倫理・AIガバナンス","term":"セキュリティ・バイ・デザイン","summary":"企画や設計の初期段階から、攻撃や情報漏えいを想定して安全対策を組み込む考え方。","exam":"AIシステムの安全な社会実装で、後付けでなく設計段階の対策として問われやすい。","difference":"プライバシー・バイ・デザインは個人情報保護、こちらは安全対策全般を重視する。","mnemonic":"最初から守る","field":"8","priority":"B"},{"id":"opus-453","category":"AI倫理・AIガバナンス","term":"センシティブ属性","summary":"性別、年齢、人種、障害など、不公平や差別につながりやすい個人属性。","exam":"公平性評価で、直接利用や間接利用に注意すべき属性として問われやすい。","difference":"代理変数はセンシティブ属性を間接的に推測させる別の特徴量。","mnemonic":"差別注意の属性","field":"8","priority":"B"},{"id":"opus-454","category":"AI倫理・AIガバナンス","term":"ソフトロー","summary":"ガイドラインや自主基準のように、法的拘束力は弱いが行動指針となるルール。","exam":"AIガバナンスで、変化の速い技術に柔軟に対応する手段として問われやすい。","difference":"ハードローは法律で強制し、ソフトローは自主的な遵守を促す。","mnemonic":"柔らかいルール","field":"8","priority":"B"},{"id":"opus-455","category":"AI倫理・AIガバナンス","term":"ディープフェイク","summary":"深層学習で人物の顔や声を本物らしく合成・改変した偽の画像や動画、音声。","exam":"生成AIの悪用例として、偽情報やなりすまし、社会的リスクと問われやすい。","difference":"フェイクニュースは虚偽情報全般、ディープフェイクはAI生成の偽メディアが中心。","mnemonic":"本物風の偽物","field":"8","priority":"B"},{"id":"opus-456","category":"AI倫理・AIガバナンス","term":"データの偏り","summary":"学習データが現実の集団や状況を十分に反映せず、一部に偏っている状態。","exam":"AIの精度低下や不公平な判断の原因として、前処理や評価で問われやすい。","difference":"サンプリングバイアスは収集方法による偏り、データの偏りはより広い概念。","mnemonic":"偏った教材で学ぶ","field":"8","priority":"B"},{"id":"opus-457","category":"AI倫理・AIガバナンス","term":"データの来歴","summary":"データがどこから、どのように収集・加工・利用されてきたかを示す履歴や由来。","exam":"学習データの信頼性や権利確認、説明責任の文脈で問われやすい。","difference":"データ品質は内容の良し悪し、データの来歴は由来や加工履歴を重視する。","mnemonic":"データの履歴書","field":"8","priority":"B"},{"id":"opus-458","category":"AI倫理・AIガバナンス","term":"データ汚染","summary":"学習データに不正・誤り・偏ったデータを混ぜ、モデルの性能や判断を悪化させる攻撃や問題。","exam":"AIセキュリティで、学習段階への攻撃やモデル汚染の原因として問われやすい。","difference":"モデル汚染は学習後のモデルへの悪影響、データ汚染は学習データ側の汚れ。","mnemonic":"教材を汚す攻撃","field":"8","priority":"B"},{"id":"opus-459","category":"AI倫理・AIガバナンス","term":"データ窃取","summary":"学習データや入力データなど、AIが扱うデータを不正に取得されること。","exam":"個人情報や営業秘密の漏えいリスクとして、AI利用時のセキュリティで問われやすい。","difference":"モデル窃取はモデル自体の模倣や取得、データ窃取はデータの不正取得を指す。","mnemonic":"データを盗まれる","field":"8","priority":"B"},{"id":"opus-460","category":"AI倫理・AIガバナンス","term":"トレーサビリティ","summary":"データやモデルの来歴・処理過程を追跡できるようにすること。","exam":"説明責任やデータの来歴と結びつけて問われやすい。","difference":"説明可能性は判断根拠の提示、トレーサビリティは履歴の追跡。","mnemonic":"履歴をたどれる","field":"8","priority":"B"},{"id":"opus-461","category":"AI倫理・AIガバナンス","term":"ハードロー","summary":"法律や規則のように、違反すると制裁や法的責任が生じる拘束力の強いルール。","exam":"AI規制で、ソフトローとの違いや法的拘束力の有無が問われやすい。","difference":"ソフトローは自主規範やガイドライン中心、ハードローは法的拘束力がある。","mnemonic":"強制力ある法律","field":"8","priority":"B"},{"id":"opus-462","category":"AI倫理・AIガバナンス","term":"フィルターバブル","summary":"推薦アルゴリズムなどにより、自分の好みに合う情報ばかり表示され視野が狭まる現象。","exam":"AI推薦の社会的リスクとして、情報の偏りや分断の文脈で問われやすい。","difference":"エコーチェンバーは人間関係内の反響、フィルターバブルは推薦による情報の偏り。","mnemonic":"好みの泡に包まれる","field":"8","priority":"B"},{"id":"opus-463","category":"AI倫理・AIガバナンス","term":"フェイクニュース","summary":"事実と異なる、または誤解を招く情報をニュースの形で広めるもの。AI生成で拡散しやすくなる。","exam":"生成AIの社会的リスクとして、ディープフェイクやエコーチェンバーと関連して問われやすい。","difference":"ディープフェイクは偽画像・音声などの合成、フェイクニュースは虚偽情報の内容を指す。","mnemonic":"偽情報が広がる","field":"8","priority":"B"},{"id":"opus-464","category":"AI倫理・AIガバナンス","term":"ブラックボックス","summary":"AIの内部処理や判断理由が外部から分かりにくい状態。深層学習で問題になりやすい。","exam":"説明可能性や説明責任の必要性として、AIガバナンスで問われやすい。","difference":"説明可能性は理由を見せる性質、ブラックボックスは理由が見えにくい状態。","mnemonic":"中身が見えない","field":"8","priority":"B"},{"id":"opus-465","category":"AI倫理・AIガバナンス","term":"プライバシー・バイ・デザイン","summary":"企画や設計の初期段階から、個人のプライバシー保護を組み込む考え方。","exam":"AIサービス設計で、後付けでなく最初から配慮する原則として問われやすい。","difference":"事後対応ではなく、システム設計時点でプライバシー保護を組み込む。","mnemonic":"最初から守る","field":"8","priority":"B"},{"id":"opus-466","category":"AI倫理・AIガバナンス","term":"プロンプトインジェクション","summary":"悪意ある指示を入力に混ぜ、モデルの本来の制約を破らせる攻撃。","exam":"生成AI特有のセキュリティリスクとして問われやすい。","difference":"Adversarial Examplesは主に画像への微小ノイズ攻撃で対象が異なる。","mnemonic":"指示を乗っ取る","field":"8","priority":"B"},{"id":"opus-467","category":"AI倫理・AIガバナンス","term":"モデル汚染","summary":"不正な学習や更新により、AIモデルの判断が意図せず偏ったり攻撃者に都合よく変わること。","exam":"継続学習や外部データ更新時のリスクとして、データ汚染と関連して問われやすい。","difference":"データ汚染は原因側、モデル汚染はその結果としてモデルが悪化した状態。","mnemonic":"モデルが汚れる","field":"8","priority":"B"},{"id":"opus-468","category":"AI倫理・AIガバナンス","term":"モデル窃取","summary":"API応答などを利用して、他者のAIモデルの機能や構造を推定・複製しようとする攻撃。","exam":"AIサービス提供時の知的財産やセキュリティ上のリスクとして問われやすい。","difference":"データ窃取は学習データ等を盗むが、モデル窃取はモデルの挙動や知識を盗む。","mnemonic":"モデルを盗む","field":"8","priority":"B"},{"id":"opus-469","category":"AI倫理・AIガバナンス","term":"リスクベースアプローチ","summary":"AIの利用場面や影響の大きさに応じて、必要な管理や対策の強さを変える考え方。","exam":"高リスクAIほど厳しく管理する考えとして、AIガバナンスで問われやすい。","difference":"一律規制ではなく、リスクの程度に合わせて対応を変える点が特徴。","mnemonic":"危険度で対策","field":"8","priority":"B"},{"id":"opus-470","category":"AI倫理・AIガバナンス","term":"レッドチーミング","summary":"攻撃者の立場でモデルを試し、危険な出力や脆弱性を洗い出す検証手法。","exam":"生成AIの安全性評価の実務として問われやすい。","difference":"通常のテストは性能確認、レッドチーミングは意図的に破ろうとする検証。","mnemonic":"わざと攻めて試す","field":"8","priority":"B"},{"id":"opus-471","category":"AI倫理・AIガバナンス","term":"人間中心のAI社会原則","summary":"日本政府が示した、人間の尊厳や多様性を尊重するAI活用の基本原則。","exam":"日本のAI原則として、公平性・説明責任・透明性と結びつけて問われる。","difference":"個別企業のAI倫理指針ではなく、国レベルの原則である点が重要。","mnemonic":"国が示す基本原則","field":"8","priority":"B"},{"id":"opus-472","category":"AI倫理・AIガバナンス","term":"代理変数","summary":"直接使わない属性の代わりに、その属性を推測できてしまう別の特徴量。","exam":"センシティブ属性を外しても不公平が残る理由として問われやすい。","difference":"センシティブ属性は保護すべき属性、代理変数はそれを間接的に表す情報。","mnemonic":"隠れた代役特徴","field":"8","priority":"B"},{"id":"opus-473","category":"AI倫理・AIガバナンス","term":"価値原則","summary":"AIの開発や利用で重視すべき価値を示す原則。公平性、透明性、安全性などが含まれる。","exam":"AI倫理ガイドラインで示される基本的な考え方として問われやすい。","difference":"具体的な法律ではなく、判断や設計の方向性を示す原則。","mnemonic":"守る価値の羅針盤","field":"8","priority":"B"},{"id":"opus-474","category":"AI倫理・AIガバナンス","term":"公平性の定義","summary":"AIの判断が公平かを測る基準。集団間の結果差や機会の均等など複数の考え方がある。","exam":"公平性には一つの絶対基準がなく、定義間でトレードオフがある点が問われやすい。","difference":"公平性は価値判断を含むため、精度指標だけでは判断できない。","mnemonic":"公平にも型がある","field":"8","priority":"B"},{"id":"opus-475","category":"AI倫理・AIガバナンス","term":"説明可能性","summary":"AIの判断理由や根拠を、人間が理解できる形で示せる性質。透明性や信頼性に関わる。","exam":"XAIやブラックボックス問題への対策として、社会実装で問われやすい。","difference":"予測精度は当たりやすさ、説明可能性はなぜそう判断したかを示す力。","mnemonic":"理由を見せる力","field":"8","priority":"B"},{"id":"opus-476","category":"AI倫理・AIガバナンス","term":"電子透かし（ウォーターマーク）","summary":"生成物にAI由来であることを示す情報を埋め込む技術。","exam":"ディープフェイク対策や生成物の識別手段として問われやすい。","difference":"データの来歴は記録の話、電子透かしは生成物側への埋め込み。","mnemonic":"AI印を埋める","field":"8","priority":"B"},{"id":"opus-477","category":"ディープラーニングの概要","term":"AMSBound","summary":"AMSGradやAdaBoundの考えをもとに、適応的学習率の安定性を高めようとする最適化手法。","exam":"Adam系の改良手法として、学習率の制御や収束の安定化の文脈で見られやすい。","difference":"AdaBoundはAdamからSGD的挙動へ近づけ、AMSBoundはAMSGradの考えも取り入れる。","mnemonic":"境界付き安定化","field":"3","priority":"C"},{"id":"opus-478","category":"ディープラーニングの概要","term":"AdaBound","summary":"Adamのように適応的に学習率を調整しつつ、最終的にSGDに近い挙動へ近づける最適化手法。","exam":"Adam系の改良手法として、学習率の上下限を動的に制御する点が問われやすい。","difference":"Adamは適応的学習率、AdaBoundはその学習率に境界を設ける。","mnemonic":"Adamに境界","field":"3","priority":"C"},{"id":"opus-479","category":"ディープラーニングの概要","term":"AdaDelta","summary":"AdaGradの学習率が小さくなりすぎる弱点を補い、過去の勾配を一定範囲で考慮する最適化手法。","exam":"適応的学習率の手法として、AdaGradの改良版という位置づけで問われやすい。","difference":"AdaGradは勾配履歴を累積し続け、AdaDeltaは古い履歴の影響を弱める。","mnemonic":"履歴をほどよく","field":"3","priority":"C"},{"id":"opus-480","category":"ディープラーニングの概要","term":"AdaGrad","summary":"各パラメータの過去の勾配に応じて学習率を調整し、よく更新される重みほど更新幅を小さくする。","exam":"適応的学習率の基本手法として、疎なデータに強いが学習率が減り続ける点が問われやすい。","difference":"RMSpropはAdaGradの学習率低下を抑えるため、移動平均を使う。","mnemonic":"頻出ほど慎重","field":"3","priority":"C"},{"id":"opus-481","category":"ディープラーニングの概要","term":"Adam","summary":"モーメンタムとRMSpropの考えを組み合わせ、勾配の平均と分散を使って更新幅を調整する手法。","exam":"代表的な最適化アルゴリズムとして、SGDやRMSpropとの違いが問われやすい。","difference":"SGDは基本的な更新、Adamは勾配の勢いとばらつきを考慮する。","mnemonic":"勢いと分散","field":"3","priority":"C"},{"id":"opus-482","category":"ディープラーニングの概要","term":"CPU","summary":"汎用的な処理を行う中央演算装置。複雑な制御や逐次処理は得意だが、並列計算はGPUほど得意ではない。","exam":"ディープラーニングで大量計算を行う際、GPUやTPUとの役割の違いが問われやすい。","difference":"GPUは並列計算、TPUはAI計算特化、CPUは汎用処理が中心。","mnemonic":"汎用の頭脳","field":"3","priority":"C"},{"id":"opus-483","category":"ディープラーニングの概要","term":"Contrastive Loss","summary":"似ているデータ同士は近く、異なるデータ同士は離れるように表現空間を学習する損失関数。","exam":"距離学習やSiamese Networkと関連し、ペア同士の近さを学ぶ文脈で問われやすい。","difference":"Triplet Lossはアンカー・正例・負例の3つを使うが、Contrastive Lossは主にペアを使う。","mnemonic":"ペアの距離学習","field":"3","priority":"C"},{"id":"opus-484","category":"ディープラーニングの概要","term":"GPU","summary":"多数の小さな計算を並列に行う装置。行列演算が多いディープラーニングの学習でよく使われる。","exam":"深層学習の発展を支えた計算資源として、CPUとの違いが問われやすい。","difference":"CPUは汎用処理、GPUは大量の並列計算に向く。","mnemonic":"並列計算の馬力","field":"3","priority":"C"},{"id":"opus-485","category":"ディープラーニングの概要","term":"L0 正則化","summary":"重みのうち0でない要素の数を罰則にし、使う特徴量やパラメータを減らそうとする正則化。","exam":"特徴選択に近い正則化として、L1・L2正則化との違いが問われやすい。","difference":"L1は絶対値、L2は二乗和、L0は0でない重みの個数を罰する。","mnemonic":"非ゼロ数を罰","field":"3","priority":"C"},{"id":"opus-486","category":"ディープラーニングの概要","term":"L1 正則化","summary":"重みの絶対値の和を罰則に加え、一部の重みを0にしやすくして特徴選択にも使える。","exam":"ラッソ回帰との関係や、不要な特徴量を削りやすい点が問われやすい。","difference":"L2は重みを小さくする傾向、L1は重みを0にして疎にしやすい。","mnemonic":"重みを削る","field":"3","priority":"C"},{"id":"opus-487","category":"ディープラーニングの概要","term":"L2 正則化","summary":"重みの二乗和を罰則に加え、大きすぎる重みを抑えて過学習を防ぎやすくする正則化。","exam":"リッジ回帰との関係や、重みをなめらかに小さくする点が問われやすい。","difference":"L1は重みを0にしやすく、L2は全体的に重みを小さくする。","mnemonic":"重みを丸める","field":"3","priority":"C"},{"id":"opus-488","category":"ディープラーニングの概要","term":"Leaky ReLU 関数","summary":"ReLUで負の入力を完全に0にせず、小さな傾きを残して出力する活性化関数。","exam":"ReLUの弱点であるニューロンが死ぬ問題への対策として問われやすい。","difference":"ReLUは負の値を0にするが、Leaky ReLUは負側にも小さな出力を残す。","mnemonic":"負側も少し通す","field":"3","priority":"C"},{"id":"opus-489","category":"ディープラーニングの概要","term":"RMSprop","summary":"過去の勾配二乗の移動平均を使い、パラメータごとに学習率を調整する最適化手法。","exam":"AdaGradの改良として、学習率が小さくなりすぎる問題を抑える点が問われやすい。","difference":"AdaGradは勾配を累積し続け、RMSpropは移動平均で最近の勾配を重視する。","mnemonic":"最近の勾配を見る","field":"3","priority":"C"},{"id":"opus-490","category":"ディープラーニングの概要","term":"ReLU 関数","summary":"入力が正ならそのまま出力し、負なら0を出力する活性化関数。深層学習で広く使われる。","exam":"勾配消失を起こしにくい活性化関数として、シグモイドとの違いが問われやすい。","difference":"シグモイドは出力が0から1に収まるが、ReLUは正の値をそのまま通す。","mnemonic":"正ならそのまま","field":"3","priority":"C"},{"id":"opus-491","category":"ディープラーニングの概要","term":"TPU","summary":"Googleが開発した、機械学習の行列演算などを高速に行うための専用プロセッサ。","exam":"AI専用ハードウェアとして、CPU・GPUとの違いが問われやすい。","difference":"GPUは画像処理由来の並列計算装置、TPUは機械学習計算に特化した装置。","mnemonic":"AI専用エンジン","field":"3","priority":"C"},{"id":"opus-492","category":"ディープラーニングの概要","term":"Triplet Loss","summary":"基準データを正例に近づけ、負例から遠ざけるように学習する距離学習の損失関数。","exam":"顔認証などの埋め込み表現学習で、アンカー・正例・負例の関係が問われやすい。","difference":"Contrastive Lossはペア中心、Triplet Lossは3つ組の相対距離を学ぶ。","mnemonic":"三つ組で距離","field":"3","priority":"C"},{"id":"opus-493","category":"ディープラーニングの概要","term":"tanh 関数","summary":"入力を-1から1の範囲に変換する活性化関数。シグモイドより中心が0に近い特徴を持つ。","exam":"シグモイド関数との違いとして、出力範囲が-1から1である点が問われやすい。","difference":"シグモイドは0から1、tanhは-1から1に出力を押し込める。","mnemonic":"マイナスも出す","field":"3","priority":"C"},{"id":"opus-494","category":"ディープラーニングの概要","term":"イテレーション","summary":"ミニバッチなどを1回使って重みを更新する処理単位。学習中の更新回数を表す。","exam":"エポックとの違いとして、1回の更新か全データ1周かが問われやすい。","difference":"エポックは全訓練データを1周、イテレーションは1回の重み更新。","mnemonic":"更新1回","field":"3","priority":"C"},{"id":"opus-495","category":"ディープラーニングの概要","term":"エポック","summary":"訓練データ全体を1回使い切る学習単位。複数エポックで同じデータを繰り返し学習する。","exam":"イテレーションやバッチサイズとの関係として、学習の回数管理で問われやすい。","difference":"イテレーションは更新1回、エポックはデータ全体を1周する単位。","mnemonic":"全データ1周","field":"3","priority":"C"},{"id":"opus-496","category":"ディープラーニングの概要","term":"オンライン学習","summary":"データを1件または少量ずつ受け取り、その都度モデルを更新する学習方法。","exam":"バッチ学習との違いとして、逐次更新できるが順序やノイズの影響を受けやすい点が問われやすい。","difference":"バッチ学習はまとめて学習し、オンライン学習はデータ到着ごとに更新する。","mnemonic":"来たらすぐ学習","field":"3","priority":"C"},{"id":"opus-497","category":"ディープラーニングの概要","term":"カルバック・ライブラー情報量 (KL)","summary":"2つの確率分布がどれだけ異なるかを測る指標。分布のずれを評価する場面で使われる。","exam":"生成モデルや確率分布の比較で、KLダイバージェンスとして問われやすい。","difference":"交差エントロピーは分類の損失によく使われ、KLは分布同士のずれを測る。","mnemonic":"分布のズレ量","field":"3","priority":"C"},{"id":"opus-498","category":"ディープラーニングの概要","term":"グリッドサーチ","summary":"ハイパーパラメータ候補を格子状にすべて組み合わせて試し、よい設定を探す方法。","exam":"ランダムサーチとの違いとして、候補を網羅的に試すが計算量が大きい点が問われやすい。","difference":"ランダムサーチは候補を無作為に試し、グリッドサーチは決めた組み合わせを全探索する。","mnemonic":"設定を総当たり","field":"3","priority":"C"},{"id":"opus-499","category":"ディープラーニングの概要","term":"シグモイド関数","summary":"入力を0から1の範囲に変換する関数。確率のように扱えるが、勾配消失を起こしやすい。","exam":"古典的な活性化関数として、勾配消失問題との関係が問われやすい。","difference":"ReLUは正の値をそのまま通すため、深い層で勾配消失を起こしにくい。","mnemonic":"0から1へ圧縮","field":"3","priority":"C"},{"id":"opus-500","category":"ディープラーニングの概要","term":"ソフトマックス関数","summary":"複数の出力値を合計1の確率分布に変換する関数。多クラス分類の出力層でよく使う。","exam":"多クラス分類で、交差エントロピーと組み合わせる出力関数として問われやすい。","difference":"シグモイドは主に二値分類、ソフトマックスは多クラス分類に使われやすい。","mnemonic":"確率に整える","field":"3","priority":"C"},{"id":"opus-501","category":"ディープラーニングの概要","term":"ドロップアウト","summary":"学習時に一部のニューロンをランダムに無効化し、特定の経路への依存を減らす手法。","exam":"ニューラルネットワークの過学習対策として、正則化の一種として問われやすい。","difference":"L1・L2は重みに罰則を加え、ドロップアウトはニューロンを一時的に無効化する。","mnemonic":"一部を休ませる","field":"3","priority":"C"},{"id":"opus-502","category":"ディープラーニングの概要","term":"ノーフリーランチの定理","summary":"すべての問題に万能なアルゴリズムはなく、平均すればどの手法も優劣がないという考え方。","exam":"モデル選択で、問題に応じた手法選びが必要な理由として問われやすい。","difference":"特定手法の性能説明ではなく、万能な最良手法は存在しないという原理。","mnemonic":"万能手法なし","field":"3","priority":"C"},{"id":"opus-503","category":"ディープラーニングの概要","term":"ハイパーパラメータ","summary":"学習で自動的に決まる重みではなく、学習率や層数など人が事前に設定する値。","exam":"グリッドサーチやランダムサーチで調整する対象として問われやすい。","difference":"パラメータは学習で更新され、ハイパーパラメータは学習前に設定する。","mnemonic":"人が決める設定","field":"3","priority":"C"},{"id":"opus-504","category":"ディープラーニングの概要","term":"バッチ学習","summary":"訓練データ全体を使ってまとめてモデルを学習する方法。安定しやすいが大規模データでは重い。","exam":"オンライン学習やミニバッチ学習との違いとして、全データを使う点が問われやすい。","difference":"オンライン学習は逐次更新、バッチ学習は全データをまとめて使う。","mnemonic":"全部まとめて学習","field":"3","priority":"C"},{"id":"opus-505","category":"ディープラーニングの概要","term":"ミニバッチ学習","summary":"訓練データを小さなまとまりに分け、それぞれで勾配を計算して重みを更新する方法。","exam":"SGDとバッチ学習の中間として、深層学習で広く使われる点が問われやすい。","difference":"バッチ学習は全データ、オンライン学習は1件ずつ、ミニバッチは小分けで更新する。","mnemonic":"小分けで更新","field":"3","priority":"C"},{"id":"opus-506","category":"ディープラーニングの概要","term":"モーメンタム","summary":"過去の更新方向を考慮し、勾配降下の進み方に勢いを持たせて収束を速める工夫。","exam":"SGDの改良として、振動を抑えながら谷方向へ進みやすくする点が問われやすい。","difference":"通常のSGDは現在の勾配中心、モーメンタムは過去の進行方向も使う。","mnemonic":"勢いを足す","field":"3","priority":"C"},{"id":"opus-507","category":"ディープラーニングの概要","term":"ラッソ回帰","summary":"L1正則化を加えた線形回帰。不要な説明変数の係数を0にしやすく、特徴選択に使える。","exam":"L1正則化との関係や、リッジ回帰との違いとして問われやすい。","difference":"リッジ回帰はL2正則化、ラッソ回帰はL1正則化を使う。","mnemonic":"L1で特徴選択","field":"3","priority":"C"},{"id":"opus-508","category":"ディープラーニングの概要","term":"ランダムサーチ","summary":"ハイパーパラメータの候補をランダムに選んで試し、よい設定を探す方法。","exam":"グリッドサーチより少ない試行で有効な設定を見つける場合がある点が問われやすい。","difference":"グリッドサーチは全組み合わせ、ランダムサーチは無作為に一部を試す。","mnemonic":"設定をくじ引き","field":"3","priority":"C"},{"id":"opus-509","category":"ディープラーニングの概要","term":"リッジ回帰","summary":"L2正則化を加えた線形回帰。係数が大きくなりすぎるのを抑え、過学習を防ぎやすい。","exam":"L2正則化との関係や、ラッソ回帰との違いとして問われやすい。","difference":"ラッソ回帰は係数を0にしやすく、リッジ回帰は係数を小さく保つ。","mnemonic":"L2で重み抑制","field":"3","priority":"C"},{"id":"opus-510","category":"ディープラーニングの概要","term":"二重降下現象","summary":"モデルを複雑にすると一度性能が悪化した後、さらに複雑化すると再び性能が良くなる現象。","exam":"従来の過学習理解だけでは説明しにくい、近年の深層学習の挙動として問われやすい。","difference":"過学習は単純に複雑化で汎化悪化、二重降下は再改善も起こる点が特徴。","mnemonic":"悪化後に再上昇","field":"3","priority":"C"},{"id":"opus-511","category":"ディープラーニングの概要","term":"交差エントロピー","summary":"正解ラベルの分布と予測確率のずれを測る損失関数。分類問題でよく使われる。","exam":"ソフトマックス関数と組み合わせた多クラス分類の損失として問われやすい。","difference":"MSEは数値誤差向き、交差エントロピーは分類の確率誤差に向く。","mnemonic":"分類のズレ罰","field":"3","priority":"C"},{"id":"opus-512","category":"ディープラーニングの概要","term":"信用割当問題","summary":"最終的な結果に対して、どの層・重み・行動がどれだけ貢献したかを割り当てる難しさ。","exam":"誤差逆伝播や強化学習で、成果の原因をどこに帰すかという問題として問われやすい。","difference":"勾配消失は学習信号が弱まる問題、信用割当問題は貢献度を決める問題。","mnemonic":"誰の手柄か問題","field":"3","priority":"C"},{"id":"opus-513","category":"ディープラーニングの概要","term":"勾配消失問題","summary":"誤差逆伝播で勾配が層を戻るほど小さくなり、前の層の重みが学習しにくくなる問題。","exam":"深いネットワークの学習困難さとして、ReLUやLSTMとの関係で問われやすい。","difference":"勾配爆発は勾配が大きくなりすぎる問題、勾配消失は小さくなりすぎる問題。","mnemonic":"勾配が消える","field":"3","priority":"C"},{"id":"opus-514","category":"ディープラーニングの概要","term":"勾配爆発問題","summary":"誤差逆伝播で勾配が大きくなりすぎ、重み更新が不安定になって学習が壊れやすくなる問題。","exam":"勾配消失問題と対で、RNNや深いネットワークの学習課題として問われやすい。","difference":"勾配消失は更新量が小さすぎ、勾配爆発は更新量が大きすぎる。","mnemonic":"勾配が暴れる","field":"3","priority":"C"},{"id":"opus-515","category":"ディープラーニングの概要","term":"勾配降下法","summary":"損失関数の値が小さくなる方向へ、勾配を使ってパラメータを少しずつ更新する最適化手法。","exam":"ニューラルネットワークの学習の基本として、学習率や局所最適解と関連して問われやすい。","difference":"SGDは勾配降下法をデータの一部で近似して更新する手法。","mnemonic":"坂を下る学習","field":"3","priority":"C"},{"id":"opus-516","category":"ディープラーニングの概要","term":"単純パーセプトロン","summary":"入力に重みをかけて足し合わせ、しきい値で出力を決める最も基本的なニューロンモデル。","exam":"線形分離可能な問題しか解けない点や、多層化の必要性として問われやすい。","difference":"多層パーセプトロンは隠れ層により非線形な表現も扱える。","mnemonic":"しきい値で判定","field":"3","priority":"C"},{"id":"opus-517","category":"ディープラーニングの概要","term":"多層パーセプトロン","summary":"入力層と出力層の間に1つ以上の隠れ層を持つニューラルネットワーク。非線形問題も扱える。","exam":"単純パーセプトロンとの違いとして、隠れ層を持つ点が問われやすい。","difference":"単純パーセプトロンは隠れ層なし、多層パーセプトロンは隠れ層あり。","mnemonic":"層を重ねて学ぶ","field":"3","priority":"C"},{"id":"opus-518","category":"ディープラーニングの概要","term":"大域最適解","summary":"探索範囲全体で損失が最も小さい解。理想的だが、複雑なモデルでは見つけにくい。","exam":"局所最適解との違いとして、全体で最良か近所で最良かが問われやすい。","difference":"局所最適解は一部範囲の最良、大域最適解は全体で最良。","mnemonic":"全体の最良","field":"3","priority":"C"},{"id":"opus-519","category":"ディープラーニングの概要","term":"学習率","summary":"勾配に従って重みをどれだけ更新するかを決める値。大きすぎても小さすぎても学習が難しい。","exam":"最適化の重要なハイパーパラメータとして、収束速度や発散との関係で問われやすい。","difference":"重みそのものではなく、重みを更新する歩幅を決める設定値。","mnemonic":"更新の歩幅","field":"3","priority":"C"},{"id":"opus-520","category":"ディープラーニングの概要","term":"局所最適解","summary":"近くの範囲では最も良いが、全体で見ると最も良いとは限らない解。最適化で問題になる。","exam":"大域最適解との違いとして、探索が途中で止まる可能性として問われやすい。","difference":"大域最適解は全体で最良、局所最適解は近所だけで最良。","mnemonic":"近所の最良","field":"3","priority":"C"},{"id":"opus-521","category":"ディープラーニングの概要","term":"平均二乗誤差関数","summary":"予測値と正解値の差を二乗して平均する損失関数。主に回帰問題で使われる。","exam":"回帰の損失関数として、分類で使う交差エントロピーとの違いが問われやすい。","difference":"交差エントロピーは分類向き、平均二乗誤差関数は連続値の回帰向き。","mnemonic":"回帰の二乗罰","field":"3","priority":"C"},{"id":"opus-522","category":"ディープラーニングの概要","term":"早期終了","summary":"検証データの性能が悪化し始めた時点で学習を止め、過学習を防ぐ正則化的な手法。","exam":"過学習対策として、検証誤差を見て学習を打ち切る点が問われやすい。","difference":"エポック数を固定するのではなく、検証性能を見て途中で止める。","mnemonic":"悪化前に止める","field":"3","priority":"C"},{"id":"opus-523","category":"ディープラーニングの概要","term":"正則化","summary":"モデルの複雑さに罰則を加え、訓練データへの合わせすぎを防いで汎化性能を高める工夫。","exam":"過学習対策として、L1・L2正則化やドロップアウトと関連して問われやすい。","difference":"正則化は考え方全体で、L1・L2・ドロップアウトは具体的な方法。","mnemonic":"複雑さに罰則","field":"3","priority":"C"},{"id":"opus-524","category":"ディープラーニングの概要","term":"確率的勾配降下法(SGD)","summary":"訓練データの一部または1件から勾配を計算し、少しずつ重みを更新する最適化手法。","exam":"勾配降下法の実用的な派生として、ミニバッチ学習との関係が問われやすい。","difference":"勾配降下法は全データで更新し、SGDは一部データで近似的に更新する。","mnemonic":"少しずつ下る","field":"3","priority":"C"},{"id":"opus-525","category":"ディープラーニングの概要","term":"連鎖律","summary":"合成関数の微分を、内側と外側の微分の積で求める法則。誤差逆伝播の数学的基礎になる。","exam":"バックプロパゲーションで、各層の勾配を順に計算する原理として問われやすい。","difference":"誤差逆伝播は学習手順、連鎖律はその勾配計算を支える微分法則。","mnemonic":"微分を鎖で渡す","field":"3","priority":"C"},{"id":"opus-526","category":"ディープラーニングの概要","term":"隠れ層・入力層・出力層","summary":"入力層はデータを受け取り、隠れ層は特徴を変換し、出力層は分類や予測結果を出す。","exam":"ニューラルネットワークの基本構造として、各層の役割が問われやすい。","difference":"隠れ層は入力と出力の間で特徴を段階的に変換する層。","mnemonic":"入口・加工・出口","field":"3","priority":"C"},{"id":"opus-527","category":"ディープラーニングの概要","term":"鞍点","summary":"ある方向では谷、別の方向では山になる点。勾配が小さく、学習が停滞しやすい場所。","exam":"局所最適解と混同されやすく、最適化が止まる原因の一つとして問われやすい。","difference":"局所最適解は近くで最も良い点、鞍点は最適でないのに勾配が小さい点。","mnemonic":"山でも谷でもある","field":"3","priority":"C"}];
    const STORAGE_KEY = "gkentei-tango-opus-v1";
    let saved;
    try { saved = JSON.parse(localStorage.getItem(STORAGE_KEY)) || {}; } catch { saved = {}; }
    saved.status ||= {};
    saved.memo ||= {};
    let filtered = [...cards];
    let index = 0;
    let reviewMode = false;

    const el = (id) => document.getElementById(id);
    const category = el("category");
    [...new Set(cards.map((card) => card.category))].forEach((name) => {
      const option = document.createElement("option");
      option.value = option.textContent = name;
      category.append(option);
    });

    function store() { localStorage.setItem(STORAGE_KEY, JSON.stringify(saved)); }
    function current() { return filtered[index]; }
    function updateStats() {
      const statuses = Object.values(saved.status);
      const known = statuses.filter((value) => value === "known").length;
      const review = statuses.filter((value) => value === "review").length;
      el("total-count").textContent = cards.length;
      el("known-count").textContent = known;
      el("review-count").textContent = review;
      el("bar-fill").style.width = `${Math.round(known / cards.length * 100)}%`;
    }
    function applyFilters() {
      const query = el("search").value.trim().toLowerCase();
      filtered = cards.filter((card) => {
        const categoryMatch = !category.value || card.category === category.value;
        const text = Object.values(card).join(" ").toLowerCase();
        const reviewMatch = !reviewMode || saved.status[card.id] === "review";
        return categoryMatch && reviewMatch && (!query || text.includes(query));
      });
      index = 0;
      render();
    }
    function render() {
      const card = current();
      const hasCard = Boolean(card);
      el("content").hidden = !hasCard;
      el("empty").hidden = hasCard;
      ["review-button","known-button","random-button","next-button"].forEach((id) => { el(id).disabled = !hasCard; });
      el("result-count").textContent = `${filtered.length}件を表示`;
      el("position").textContent = hasCard ? `${index + 1} / ${filtered.length}` : "";
      if (!hasCard) return;
      el("card-category").textContent = card.category;
      el("term").textContent = card.term;
      el("mnemonic").textContent = `覚え方：${card.mnemonic}`;
      el("summary").textContent = card.summary;
      el("exam").textContent = card.exam;
      el("difference").textContent = card.difference;
      el("memo").value = saved.memo[card.id] || "";
      el("answer").hidden = true;
      el("reveal").hidden = false;
    }
    function reveal() { el("answer").hidden = false; el("reveal").hidden = true; }
    function advance() { if (filtered.length) { index = (index + 1) % filtered.length; render(); } }
    function setStatus(status) {
      const card = current();
      if (!card) return;
      saved.status[card.id] = status;
      store();
      updateStats();
      if (reviewMode) applyFilters(); else advance();
    }

    el("reveal").addEventListener("click", reveal);
    el("reveal").addEventListener("keydown", (event) => { if (event.key === "Enter" || event.key === " ") reveal(); });
    el("memo").addEventListener("input", () => { const card = current(); if (card) { saved.memo[card.id] = el("memo").value; store(); } });
    el("review-button").addEventListener("click", () => setStatus("review"));
    el("known-button").addEventListener("click", () => setStatus("known"));
    el("next-button").addEventListener("click", advance);
    el("random-button").addEventListener("click", () => { if (filtered.length) { index = Math.floor(Math.random() * filtered.length); render(); } });
    el("review-only").addEventListener("click", () => {
      reviewMode = !reviewMode;
      el("review-only").textContent = reviewMode ? "すべてのカードに戻る" : "復習だけ表示";
      applyFilters();
    });
    category.addEventListener("change", applyFilters);
    el("search").addEventListener("input", applyFilters);
    updateStats();
    render();
  